import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { useRWFilter } from '../../contexts/RWFilterContext';
import StatCard from '../../components/StatCard';
import BantuanSosialWidget from '../../components/BantuanSosialWidget';
import StrataEkonomiSection from '../../components/dashboard/StrataEkonomiSection';
import DonutChart from '../../components/DonutChart';
import Pie3DChart from '../../components/Pie3DChart';
import { Button } from '@/components/ui/button';
import { exportElementToPdf, exportBantuanSosialPdf } from '../../lib/exportSectionPdf';
import {
  Users, Home, DollarSign, FileText, AlertCircle,
  TrendingUp, Building2, MapPin, CheckCircle, Bell, Printer, Loader2
} from 'lucide-react';
import { API_BASE_URL } from '../../config/api';

const RWDashboard = () => {
  const { token } = useAuth();
  const { rtId, selectedRT } = useRWFilter();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Print PDF — Bantuan Sosial (native lewat autoTable) & Statistik/Chart
  // (Strata Ekonomi + Demografi, capture canvas). Subjudul PDF mengikuti
  // filter RT yang sedang aktif di header RW (per-RT tertentu atau semua RT).
  const strataDemografiRef = useRef(null);
  const [printingBantuan, setPrintingBantuan] = useState(false);
  const [printingStrata, setPrintingStrata] = useState(false);

  const rwLabel = data?.rw_nama || data?.rw_info?.rw_list?.map((r) => r.nama_rw).join(', ') || '';
  const scopeLabel = selectedRT ? `RT ${selectedRT.name}` : 'Semua RT';
  const pdfSubtitle = [rwLabel, scopeLabel].filter(Boolean).join(' - ');

  const handlePrintBantuanSosial = async () => {
    if (!data?.bantuan_stats) return;
    setPrintingBantuan(true);
    try {
      await exportBantuanSosialPdf({
        stats: data.bantuan_stats,
        title: 'Laporan Penerima Bantuan Sosial',
        subtitle: pdfSubtitle,
        filename: `bantuan-sosial-rw-${new Date().toISOString().slice(0, 10)}.pdf`,
      });
    } catch (err) {
      console.error('Gagal export PDF Bantuan Sosial:', err);
      alert('Gagal membuat PDF. Coba lagi.');
    } finally {
      setPrintingBantuan(false);
    }
  };

  const handlePrintStrataDemografi = async () => {
    if (!strataDemografiRef.current) return;
    setPrintingStrata(true);
    try {
      await exportElementToPdf(strataDemografiRef.current, {
        title: 'Laporan Statistik & Demografi Warga',
        subtitle: pdfSubtitle,
        filename: `statistik-demografi-warga-rw-${new Date().toISOString().slice(0, 10)}.pdf`,
        backgroundColor: '#ffffff',
      });
    } catch (err) {
      console.error('Gagal export PDF Statistik Demografi:', err);
      alert('Gagal membuat PDF. Coba lagi.');
    } finally {
      setPrintingStrata(false);
    }
  };

  useEffect(() => {
    fetchDashboard();
  }, [token, rtId]);

  const fetchDashboard = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = rtId ? { rt_id: rtId } : {};
      const res = await axios.get(`${API_BASE_URL}/api/rw/dashboard`, { headers, params });
      setData(res.data);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (val) =>
    new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(val || 0);

  if (loading) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat dashboard RW...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span>
        <span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Dashboard</span>
      </div>

      {/* Header */}
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center shadow">
          <Building2 className="h-5 w-5 text-white" />
        </div>
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Dashboard RW</h1>
          <p className="text-sm text-gray-500 dark:text-gray-400">Supervisory layer — agregasi seluruh data RT</p>
        </div>
      </div>

      {/* RW Info Banner */}
      {(data?.rw_nama || data?.rw_info?.rw_list?.length > 0) && (
        <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
          <div className="flex items-center gap-2 mb-1">
            <MapPin className="h-4 w-4 text-blue-600 dark:text-blue-400 flex-shrink-0" />
            <span className="text-sm font-semibold text-blue-700 dark:text-blue-300">
              {data.rw_nama || data.rw_info.rw_list.map(r => r.nama_rw).join(', ')}
            </span>
          </div>
          {data.rw_alamat && (
            <p className="text-xs text-blue-500 dark:text-blue-400 ml-6 mb-1">{data.rw_alamat}</p>
          )}
          <p className="text-xs text-blue-600 dark:text-blue-400 ml-6">
            {data.jumlah_rt} Blok RT · {data.total_warga} Warga · {data.total_rumah} Rumah
          </p>
        </div>
      )}

      {/* KPI Cards Row 1 — Wilayah */}
      <div>
        <h2 className="text-sm font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-3">
          Statistik Wilayah
        </h2>
        <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-2 sm:gap-4">
          <StatCard title="Jumlah RT" value={data?.jumlah_rt || 0} icon={MapPin} dropdown={false} />
          <StatCard title="Total Warga" value={data?.total_warga || 0} icon={Users} dropdown={false} />
          <StatCard title="Total Rumah" value={data?.total_rumah || 0} icon={Home} dropdown={false} />
          <StatCard title="Rumah Berpenghuni" value={data?.rumah_berpenghuni || 0} icon={CheckCircle} dropdown={false} />
        </div>
      </div>

      {/* KPI Cards Row 2 — Keuangan */}
      <div>
        <h2 className="text-sm font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-3">
          Keuangan
        </h2>
        <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-3 gap-2 sm:gap-4">
          <StatCard title="Kas RW" value={formatCurrency(data?.kas_rw)} icon={DollarSign} dropdown={false} />
          <StatCard title="Total Kas RT" value={formatCurrency(data?.total_kas_rt)} icon={TrendingUp} dropdown={false} />
          <StatCard title="Total Kas Seluruh" value={formatCurrency(data?.total_kas_seluruh)} icon={DollarSign} dropdown={false} />
        </div>
      </div>

      {/* KPI Cards Row 3 — Aktivitas */}
      <div>
        <h2 className="text-sm font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-3">
          Aktivitas
        </h2>
        <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-2 sm:gap-4">
          <StatCard title="Surat Bulan Ini" value={data?.surat_bulan_ini || 0} icon={FileText} dropdown={false} />
          <StatCard title="Total Surat" value={data?.total_surat || 0} icon={FileText} dropdown={false} />
          <StatCard title="Pengaduan Aktif" value={data?.pengaduan_aktif || 0} icon={AlertCircle} dropdown={false} />
          <StatCard title="Total Pengaduan" value={data?.pengaduan_total || 0} icon={Bell} dropdown={false} />
        </div>
      </div>

      {/* Bantuan Sosial */}
      {data?.bantuan_stats && data.bantuan_stats.total_penerima > 0 && (
        <div>
          <div className="flex justify-end mb-2">
            <Button
              variant="outline"
              size="sm"
              onClick={handlePrintBantuanSosial}
              disabled={printingBantuan}
              className="border-orange-600 text-orange-700 hover:bg-orange-50 dark:border-orange-500 dark:text-orange-400"
            >
              {printingBantuan ? (
                <><Loader2 className="h-4 w-4 mr-1.5 animate-spin" />Membuat PDF...</>
              ) : (
                <><Printer className="h-4 w-4 mr-1.5" />Print PDF</>
              )}
            </Button>
          </div>
          <BantuanSosialWidget stats={data.bantuan_stats} />
        </div>
      )}

      {/* Distribusi Strata Ekonomi + Statistik Demografi Warga — dibungkus supaya bisa di-Print PDF sekaligus. Data mengikuti tenant yang sedang difilter (RT tertentu atau agregat semua RT di bawah RW ini). */}
      <div>
        <div className="flex justify-end mb-2">
          <Button
            variant="outline"
            size="sm"
            onClick={handlePrintStrataDemografi}
            disabled={printingStrata}
            className="border-orange-600 text-orange-700 hover:bg-orange-50 dark:border-orange-500 dark:text-orange-400"
          >
            {printingStrata ? (
              <><Loader2 className="h-4 w-4 mr-1.5 animate-spin" />Membuat PDF...</>
            ) : (
              <><Printer className="h-4 w-4 mr-1.5" />Print PDF</>
            )}
          </Button>
        </div>
        <div ref={strataDemografiRef} className="space-y-6">
          {/* Distribusi Strata Ekonomi — breakdown per RT di bawah RW ini */}
          <StrataEkonomiSection strataData={data?.strata_ekonomi} mode="rw" />

          {/* Statistik Demografi Warga (Umur/Agama/Jenis Kelamin) — agregat semua RT di bawah RW ini */}
          {data?.demografi && data.demografi.total > 0 && (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              <DonutChart
                title="Jumlah Warga Berdasarkan Umur"
                data={data.demografi.by_umur}
                totalLabel={`(${data.demografi.total} total)`}
              />
              <DonutChart
                title="Jumlah Warga Berdasarkan Agama"
                data={data.demografi.by_agama}
                totalLabel={`(${data.demografi.total} total)`}
              />
              <DonutChart
                title="Jumlah Warga Berdasarkan Jenis Kelamin"
                data={data.demografi.by_gender}
                totalLabel={`(${data.demografi.total} total)`}
              />
            </div>
          )}

          {/* Statistik tambahan: Status Warga / Kewarganegaraan (WNI-WNA) / Pekerjaan — agregat semua RT di bawah RW ini */}
          {data?.demografi && data.demografi.total > 0 && (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              <Pie3DChart
                title="Jumlah Warga Berdasarkan Status"
                data={data.demografi.by_status}
                totalLabel={`(${data.demografi.total} total)`}
              />
              <Pie3DChart
                title="Jumlah Warga Berdasarkan Kewarganegaraan"
                data={data.demografi.by_kewarganegaraan}
                totalLabel={`(${data.demografi.total} total)`}
              />
              <Pie3DChart
                title="Jumlah Warga Berdasarkan Pekerjaan"
                data={data.demografi.by_pekerjaan}
                totalLabel={`(${data.demografi.total} total)`}
              />
            </div>
          )}
        </div>
      </div>

      {/* IPL Summary */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* IPL Status */}
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow p-6">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-4">
            Status IPL
          </h3>
          <div className="space-y-3">
            <div className="flex justify-between items-center pb-3 border-b border-gray-100 dark:border-gray-700">
              <span className="text-sm text-gray-600 dark:text-gray-400">IPL Sudah Bayar</span>
              <span className="font-semibold text-green-600">{formatCurrency(data?.ipl_sudah_bayar)}</span>
            </div>
            <div className="flex justify-between items-center pb-3 border-b border-gray-100 dark:border-gray-700">
              <span className="text-sm text-gray-600 dark:text-gray-400">IPL Belum Bayar</span>
              <span className="font-semibold text-red-600">{formatCurrency(data?.ipl_belum_bayar)}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-sm text-gray-600 dark:text-gray-400">Warga Aktif</span>
              <span className="font-semibold text-gray-900 dark:text-white">{data?.warga_aktif || 0} orang</span>
            </div>
          </div>
        </div>

        {/* Daftar RT */}
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow p-6">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
              Daftar RT
            </h3>
            <span className="text-xs bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300 font-semibold px-2 py-0.5 rounded-full">
              {data?.rt_list?.length || 0} RT
            </span>
          </div>
          {data?.rt_list?.length > 0 ? (
            <div className="space-y-2 max-h-64 overflow-y-auto pr-1">
              {data.rt_list.map((rt, idx) => (
                <div key={rt.id || idx} className="flex items-center gap-3 p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                  <div className="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center text-white text-xs font-bold flex-shrink-0">
                    {String(idx + 1).padStart(2, '0')}
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-semibold text-gray-900 dark:text-white">{rt.nama}</p>
                    {rt.alamat
                      ? <p className="text-xs text-gray-500 dark:text-gray-400 truncate">{rt.alamat}</p>
                      : <p className="text-xs text-gray-400 dark:text-gray-500 italic">Alamat belum diisi</p>
                    }
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-6">
              <MapPin className="h-10 w-10 text-gray-300 dark:text-gray-600 mx-auto mb-2" />
              <p className="text-sm text-gray-500 dark:text-gray-400">Belum ada data RT</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default RWDashboard;
