import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';
import { useSidebar } from '../contexts/SidebarContext';
import { useRWFilter } from '../contexts/RWFilterContext';
import { API_BASE_URL } from '../config/api';
import {
  UserPlus, Plus, Trash2, Eye, RefreshCw, Filter, Mic, Pause, X, ChevronLeft, ChevronRight
} from 'lucide-react';
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter
} from "@/components/ui/dialog";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Button } from '@/components/ui/button';
import TamuLaporImageUploader from '../components/TamuLaporImageUploader';
import VoiceRecorder from '../components/VoiceRecorder';
import VoiceNotePlayer from '../components/VoiceNotePlayer';
import { toast } from '@/components/ui/sonner';

const KATEGORI_OPTIONS = [
  { value: 'Tamu', label: 'Tamu Biasa' },
  { value: 'Tamu Menginap', label: 'Tamu Menginap' },
  { value: 'Kost/Kontrakan Baru', label: 'Kost / Kontrakan — Penghuni Baru' },
  { value: 'Acara/Kegiatan', label: 'Acara / Kegiatan' },
  { value: 'Lainnya', label: 'Lainnya' },
];

const STATUS_COLORS = {
  'Baru': 'border-amber-500 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
  'Sudah Diketahui': 'border-blue-500 text-blue-600 bg-blue-50 dark:bg-blue-900/20',
  'Selesai': 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20',
};

const serverUrl = (path) => `${API_BASE_URL}/${path}`;
const formatDate = (d) => d ? new Date(d).toLocaleString('id-ID', { dateStyle: 'medium', timeStyle: 'short' }) : '-';

// Ambil bagian angka/kode saja dari nama tenant, buang prefix "RT"/"RW" yang sudah ada di data
// supaya tidak dobel (contoh: "RT 02" -> "02"), lalu gabungkan jadi "02/07".
const stripPrefix = (name, prefix) => name ? name.replace(new RegExp(`^${prefix}\\s*`, 'i'), '').trim() : null;
const formatAsalRtRw = (namaRt, namaRw) => {
  const rt = stripPrefix(namaRt, 'RT');
  const rw = stripPrefix(namaRw, 'RW');
  if (!rt) return '-';
  return rw ? `${rt}/${rw}` : rt;
};

const TamuLaporPage = () => {
  const { token, user } = useAuth();
  const { isMobile } = useSidebar();
  const { selectedRT } = useRWFilter();
  const isWarga = user?.role === 'warga';
  const isPengurus = ['admin', 'pengurus_rt', 'rw', 'pengurus_rw', 'kelurahan', 'pengurus_kelurahan'].includes(user?.role);
  const isRwViewer = ['rw', 'pengurus_rw', 'kelurahan', 'pengurus_kelurahan'].includes(user?.role);

  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filterStatus, setFilterStatus] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [viewItem, setViewItem] = useState(null);
  const [saving, setSaving] = useState(false);
  const [wargaBlok, setWargaBlok] = useState('');
  const [deleteTarget, setDeleteTarget] = useState(null);

  // Quick preview langsung dari list — tanpa buka dialog detail
  const [quickLightbox, setQuickLightbox] = useState(null); // { images: [], index: 0 }
  const [playingVoiceId, setPlayingVoiceId] = useState(null);
  const quickAudioRef = useRef(null);

  // form state
  const defaultForm = { kategori: 'Tamu', nama_tamu: '', alasan: '', keterangan: '', pelapor_nama: '', blok_rumah: '' };
  const [form, setForm] = useState(defaultForm);
  const [localFiles, setLocalFiles] = useState([]);
  const [voiceBlob, setVoiceBlob] = useState(null);
  const [voiceDuration, setVoiceDuration] = useState(0);

  // status update (RT/RW)
  const [statusDraft, setStatusDraft] = useState('');
  const [catatanDraft, setCatatanDraft] = useState('');
  const [savingStatus, setSavingStatus] = useState(false);

  useEffect(() => { fetchData(); }, [token, filterStatus, selectedRT]);

  useEffect(() => {
    if (isWarga && token) {
      fetch(`${API_BASE_URL}/api/warga/me`, { headers: { Authorization: `Bearer ${token}` } })
        .then(r => r.ok ? r.json() : null)
        .then(d => { if (d?.block_house) setWargaBlok(d.block_house); })
        .catch(() => {});
    }
  }, [token, isWarga]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = new URLSearchParams();
      if (filterStatus) params.append('status', filterStatus);
      if (isRwViewer && selectedRT?.id) params.append('rt_id', selectedRT.id);
      const res = await axios.get(`${API_BASE_URL}/api/tamu-lapor?${params}`, { headers });
      setData(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      console.error('Gagal load lapor tamu', err);
    } finally {
      setLoading(false);
    }
  };

  const openAdd = () => {
    setForm({ ...defaultForm, pelapor_nama: user?.fullname || '', blok_rumah: wargaBlok });
    setLocalFiles([]);
    setVoiceBlob(null);
    setVoiceDuration(0);
    setShowForm(true);
  };

  const handleSave = async () => {
    if (!form.alasan.trim()) {
      toast.error('Alasan / tujuan kedatangan harus diisi');
      return;
    }
    try {
      setSaving(true);
      const headers = { Authorization: `Bearer ${token}` };
      const fd = new FormData();
      Object.entries(form).forEach(([k, v]) => { if (v !== undefined && v !== null) fd.append(k, v); });
      localFiles.forEach(f => fd.append('files', f));
      if (voiceBlob) {
        const ext = voiceBlob.type.includes('mp4') ? 'm4a' : 'webm';
        fd.append('voice', voiceBlob, `voice.${ext}`);
        fd.append('voice_duration', String(voiceDuration));
      }
      await axios.post(`${API_BASE_URL}/api/tamu-lapor/with-media`, fd, { headers });
      toast.success('Laporan tamu berhasil dikirim ke RT/RW');
      setShowForm(false);
      fetchData();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Gagal mengirim laporan');
    } finally {
      setSaving(false);
    }
  };

  const openView = (item) => {
    setViewItem(item);
    setStatusDraft(item.status);
    setCatatanDraft(item.catatan_rt || '');
  };

  const toggleQuickVoice = (item) => {
    const audio = quickAudioRef.current;
    if (!audio) return;
    if (playingVoiceId === item.id) {
      audio.pause();
      setPlayingVoiceId(null);
      return;
    }
    audio.src = serverUrl(item.voice_note_path);
    audio.currentTime = 0;
    audio.play();
    setPlayingVoiceId(item.id);
  };

  const openQuickLightbox = (images, index = 0) => {
    setQuickLightbox({ images, index });
  };

  const lightboxNav = (dir) => {
    setQuickLightbox(prev => {
      if (!prev) return prev;
      const next = (prev.index + dir + prev.images.length) % prev.images.length;
      return { ...prev, index: next };
    });
  };

  const handleSaveStatus = async () => {
    try {
      setSavingStatus(true);
      const headers = { Authorization: `Bearer ${token}` };
      await axios.put(`${API_BASE_URL}/api/tamu-lapor/${viewItem.id}`, {
        status: statusDraft, catatan_rt: catatanDraft,
      }, { headers });
      toast.success('Status laporan diperbarui');
      setViewItem(null);
      fetchData();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Gagal update status');
    } finally {
      setSavingStatus(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.delete(`${API_BASE_URL}/api/tamu-lapor/${deleteTarget.id}`, { headers });
      toast.success('Laporan tamu dihapus');
      setDeleteTarget(null);
      fetchData();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Gagal menghapus');
    }
  };

  return (
    <div className="p-4 md:p-6 space-y-4">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-3">
        <div>
          <h1 className="text-xl font-bold text-gray-900 dark:text-gray-100 flex items-center gap-2">
            <UserPlus className="h-5 w-5 text-[var(--rw-primary)]" />
            Lapor Tamu
          </h1>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            {isWarga
              ? 'Beri tahu RT & RW jika ada tamu, penyewa/kost baru, atau kegiatan di rumah Anda.'
              : 'Daftar laporan tamu dari warga di wilayah Anda.'}
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={fetchData} className="gap-1.5">
            <RefreshCw className="h-4 w-4" /> Refresh
          </Button>
          {isWarga && (
            <Button onClick={openAdd} className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white gap-1.5">
              <Plus className="h-4 w-4" /> Lapor Tamu
            </Button>
          )}
        </div>
      </div>

      {/* Filter */}
      <div className="flex items-center gap-2">
        <Filter className="h-4 w-4 text-gray-400" />
        <Select value={filterStatus || 'all'} onValueChange={v => setFilterStatus(v === 'all' ? '' : v)}>
          <SelectTrigger className="w-48"><SelectValue placeholder="Semua Status" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Semua Status</SelectItem>
            <SelectItem value="Baru">Baru</SelectItem>
            <SelectItem value="Sudah Diketahui">Sudah Diketahui</SelectItem>
            <SelectItem value="Selesai">Selesai</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Table */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Kategori</TableHead>
              <TableHead>Alasan / Tujuan</TableHead>
              {isPengurus && <TableHead>Pelapor</TableHead>}
              <TableHead>Blok</TableHead>
              {isRwViewer && <TableHead>Asal RT / RW</TableHead>}
              <TableHead>Lampiran</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Tanggal</TableHead>
              <TableHead className="text-right">Aksi</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow><TableCell colSpan={7 + (isPengurus ? 1 : 0) + (isRwViewer ? 1 : 0)} className="text-center py-8 text-gray-500">Memuat...</TableCell></TableRow>
            ) : data.length === 0 ? (
              <TableRow><TableCell colSpan={7 + (isPengurus ? 1 : 0) + (isRwViewer ? 1 : 0)} className="text-center py-8 text-gray-500">Belum ada laporan tamu.</TableCell></TableRow>
            ) : data.map(item => {
              const images = item.images_json ? JSON.parse(item.images_json) : [];
              return (
                <TableRow key={item.id} className="dark:border-gray-700">
                  <TableCell className="text-sm font-medium">{item.kategori}</TableCell>
                  <TableCell className="text-sm text-gray-600 dark:text-gray-400 max-w-xs truncate" title={item.alasan}>{item.alasan}</TableCell>
                  {isPengurus && <TableCell className="text-sm">{item.pelapor_nama || '-'}</TableCell>}
                  <TableCell className="text-sm">{item.blok_rumah || '-'}</TableCell>
                  {isRwViewer && (
                    <TableCell className="text-sm font-medium text-gray-700 dark:text-gray-300">
                      {formatAsalRtRw(item.tenant_nama_rt, item.tenant_nama_rw)}
                    </TableCell>
                  )}
                  <TableCell>
                    <div className="flex items-center gap-2">
                      {images.length > 0 && (
                        <button
                          type="button"
                          onClick={() => openQuickLightbox(images, 0)}
                          className="relative w-9 h-9 rounded-md overflow-hidden border border-[var(--rw-border)] dark:border-gray-700 hover:ring-2 hover:ring-[var(--rw-primary)] transition-all flex-shrink-0"
                          title={`Lihat ${images.length} foto`}
                        >
                          <img src={serverUrl(images[0])} alt="Lampiran" className="w-full h-full object-cover" />
                          {images.length > 1 && (
                            <span className="absolute bottom-0 right-0 bg-black/70 text-white text-[9px] font-bold px-1 rounded-tl">
                              +{images.length - 1}
                            </span>
                          )}
                        </button>
                      )}
                      {item.voice_note_path && (
                        <button
                          type="button"
                          onClick={() => toggleQuickVoice(item)}
                          className={`w-9 h-9 rounded-md flex items-center justify-center border transition-all flex-shrink-0 ${
                            playingVoiceId === item.id
                              ? 'bg-emerald-500 border-emerald-500 text-white ring-2 ring-emerald-300'
                              : 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-200 dark:border-emerald-800 text-emerald-600 hover:ring-2 hover:ring-emerald-400'
                          }`}
                          title="Putar voice note"
                        >
                          {playingVoiceId === item.id ? <Pause className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
                        </button>
                      )}
                      {images.length === 0 && !item.voice_note_path && (
                        <span className="text-gray-400 text-sm">-</span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={STATUS_COLORS[item.status] || ''}>{item.status}</Badge>
                  </TableCell>
                  <TableCell className="text-xs text-gray-500">{formatDate(item.created_at)}</TableCell>
                  <TableCell className="text-right">
                    <div className="flex justify-end gap-1">
                      <Button size="sm" variant="ghost" onClick={() => openView(item)} className="h-7 px-2">
                        <Eye className="h-3.5 w-3.5" />
                      </Button>
                      {(isPengurus || (isWarga && item.status === 'Baru')) && (
                        <Button size="sm" variant="ghost" onClick={() => setDeleteTarget(item)} className="h-7 px-2 text-gray-400 hover:text-red-600">
                          <Trash2 className="h-3.5 w-3.5" />
                        </Button>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </div>

      {/* FORM DIALOG — Lapor Tamu (Warga) */}
      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 max-w-lg max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <UserPlus className="h-5 w-5 text-[var(--rw-primary)]" /> Lapor Tamu ke RT / RW
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div>
              <Label>Kategori</Label>
              <Select value={form.kategori} onValueChange={v => setForm(f => ({ ...f, kategori: v }))}>
                <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {KATEGORI_OPTIONS.map(k => <SelectItem key={k.value} value={k.value}>{k.label}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Nama Tamu / Penyewa (opsional)</Label>
              <Input className="mt-1" value={form.nama_tamu} onChange={e => setForm(f => ({ ...f, nama_tamu: e.target.value }))} placeholder="Contoh: Budi Santoso" />
            </div>
            <div>
              <Label>Alasan / Tujuan Kedatangan <span className="text-red-500">*</span></Label>
              <Textarea className="mt-1" rows={2} value={form.alasan} onChange={e => setForm(f => ({ ...f, alasan: e.target.value }))} placeholder="Contoh: Menginap 2 malam, kunjungan keluarga" />
            </div>
            <div>
              <Label>Keterangan Tambahan</Label>
              <Textarea className="mt-1" rows={2} value={form.keterangan} onChange={e => setForm(f => ({ ...f, keterangan: e.target.value }))} placeholder="Info lain yang perlu diketahui RT/RW..." />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Siapa yang Lapor</Label>
                <Input className="mt-1" value={form.pelapor_nama} onChange={e => setForm(f => ({ ...f, pelapor_nama: e.target.value }))} />
              </div>
              <div>
                <Label>Blok Rumah</Label>
                <Input className="mt-1" value={form.blok_rumah} onChange={e => setForm(f => ({ ...f, blok_rumah: e.target.value }))} placeholder="Contoh: A-5" />
              </div>
            </div>

            {/* Upload foto */}
            <div className="pt-1">
              <TamuLaporImageUploader
                tamuId={null}
                savedImages={[]}
                localFiles={localFiles}
                onFilesChange={setLocalFiles}
                token={token}
              />
            </div>

            {/* Voice note — hanya tampil di mobile mode */}
            {isMobile && (
              <div className="pt-1">
                <Label className="block mb-1.5">Voice Note (opsional)</Label>
                {voiceBlob ? (
                  <div className="flex items-center gap-2">
                    <audio controls src={URL.createObjectURL(voiceBlob)} className="h-10 flex-1" />
                    <Button size="sm" variant="ghost" onClick={() => { setVoiceBlob(null); setVoiceDuration(0); }} className="text-red-500">
                      <Trash2 className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                ) : (
                  <VoiceRecorder
                    onRecorded={(blob, dur) => { setVoiceBlob(blob); setVoiceDuration(dur); }}
                    onClear={() => { setVoiceBlob(null); setVoiceDuration(0); }}
                  />
                )}
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowForm(false)}>Batal</Button>
            <Button onClick={handleSave} disabled={saving} className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white">
              {saving ? 'Mengirim...' : 'Kirim Laporan'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* VIEW DIALOG */}
      <Dialog open={!!viewItem} onOpenChange={() => setViewItem(null)}>
        <DialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 max-w-lg max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <UserPlus className="h-5 w-5 text-[var(--rw-primary)]" /> {viewItem?.kategori}
            </DialogTitle>
          </DialogHeader>
          {viewItem && (
            <div className="space-y-3 text-sm">
              <div className="flex gap-2 flex-wrap">
                <Badge variant="outline" className={STATUS_COLORS[viewItem.status] || ''}>{viewItem.status}</Badge>
                {viewItem.nama_tamu && <Badge variant="outline">Tamu: {viewItem.nama_tamu}</Badge>}
              </div>
              <div className="grid grid-cols-2 gap-2 text-gray-600 dark:text-gray-400">
                <div><span className="font-medium">Pelapor:</span> {viewItem.pelapor_nama || '-'}</div>
                <div><span className="font-medium">Blok:</span> {viewItem.blok_rumah || '-'}</div>
                {isRwViewer && (
                  <div className="col-span-2">
                    <span className="font-medium">Asal:</span>{' '}
                    {formatAsalRtRw(viewItem.tenant_nama_rt, viewItem.tenant_nama_rw)}
                  </div>
                )}
                <div className="col-span-2"><span className="font-medium">Tanggal:</span> {formatDate(viewItem.created_at)}</div>
              </div>
              <div>
                <p className="font-medium text-gray-700 dark:text-gray-300 mb-1">Alasan / Tujuan:</p>
                <p className="text-gray-600 dark:text-gray-400 bg-[var(--rw-bg-card-alt)] dark:bg-gray-800 rounded p-3">{viewItem.alasan}</p>
              </div>
              {viewItem.keterangan && (
                <div>
                  <p className="font-medium text-gray-700 dark:text-gray-300 mb-1">Keterangan:</p>
                  <p className="text-gray-600 dark:text-gray-400 bg-[var(--rw-bg-card-alt)] dark:bg-gray-800 rounded p-3">{viewItem.keterangan}</p>
                </div>
              )}

              {viewItem.voice_note_path && (
                <div>
                  <p className="font-medium text-gray-700 dark:text-gray-300 mb-1">Voice Note:</p>
                  <VoiceNotePlayer src={serverUrl(viewItem.voice_note_path)} durationHint={viewItem.voice_note_duration} />
                </div>
              )}

              <TamuLaporImageUploader
                tamuId={viewItem.id}
                savedImages={viewItem.images_json ? JSON.parse(viewItem.images_json) : []}
                localFiles={[]}
                token={token}
                readOnly={true}
              />

              {/* Update status — hanya RT/RW */}
              {isPengurus && (
                <div className="border-t border-[var(--rw-border)] dark:border-gray-700 pt-3 space-y-2">
                  <Label>Update Status</Label>
                  <Select value={statusDraft} onValueChange={setStatusDraft}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="Baru">Baru</SelectItem>
                      <SelectItem value="Sudah Diketahui">Sudah Diketahui</SelectItem>
                      <SelectItem value="Selesai">Selesai</SelectItem>
                    </SelectContent>
                  </Select>
                  <Textarea
                    rows={2}
                    placeholder="Catatan balasan untuk warga (opsional)..."
                    value={catatanDraft}
                    onChange={e => setCatatanDraft(e.target.value)}
                  />
                  <Button onClick={handleSaveStatus} disabled={savingStatus} className="w-full bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white">
                    {savingStatus ? 'Menyimpan...' : 'Simpan Status'}
                  </Button>
                </div>
              )}
              {!isPengurus && viewItem.catatan_rt && (
                <div>
                  <p className="font-medium text-gray-700 dark:text-gray-300 mb-1">Catatan RT/RW:</p>
                  <p className="text-gray-600 dark:text-gray-400 bg-green-50 dark:bg-green-900/20 rounded p-3">{viewItem.catatan_rt}</p>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* DELETE CONFIRM */}
      <AlertDialog open={!!deleteTarget} onOpenChange={(o) => !o && setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Laporan Tamu</AlertDialogTitle>
            <AlertDialogDescription>
              Apakah Anda yakin ingin menghapus laporan "{deleteTarget?.kategori} — {deleteTarget?.alasan}"? Tindakan ini tidak dapat dibatalkan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-red-500 hover:bg-red-600">Ya, Hapus</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Audio tersembunyi — untuk play/pause voice note langsung dari list */}
      <audio
        ref={quickAudioRef}
        onEnded={() => setPlayingVoiceId(null)}
        className="hidden"
      />

      {/* QUICK LIGHTBOX — preview gambar langsung diperbesar dari list, tanpa buka dialog detail */}
      {quickLightbox && (
        <div
          className="fixed inset-0 bg-black/85 z-[100] flex items-center justify-center p-4"
          onClick={() => setQuickLightbox(null)}
        >
          <button
            type="button"
            onClick={() => setQuickLightbox(null)}
            className="absolute top-4 right-4 text-white/80 hover:text-white p-2"
          >
            <X className="w-6 h-6" />
          </button>

          {quickLightbox.images.length > 1 && (
            <button
              type="button"
              onClick={(e) => { e.stopPropagation(); lightboxNav(-1); }}
              className="absolute left-2 md:left-6 text-white/80 hover:text-white p-2"
            >
              <ChevronLeft className="w-8 h-8" />
            </button>
          )}

          <img
            src={serverUrl(quickLightbox.images[quickLightbox.index])}
            alt="Preview"
            className="max-w-full max-h-[85vh] rounded-lg object-contain"
            onClick={(e) => e.stopPropagation()}
          />

          {quickLightbox.images.length > 1 && (
            <>
              <button
                type="button"
                onClick={(e) => { e.stopPropagation(); lightboxNav(1); }}
                className="absolute right-2 md:right-6 text-white/80 hover:text-white p-2"
              >
                <ChevronRight className="w-8 h-8" />
              </button>
              <span className="absolute bottom-4 left-1/2 -translate-x-1/2 text-white/80 text-sm bg-black/40 px-3 py-1 rounded-full">
                {quickLightbox.index + 1} / {quickLightbox.images.length}
              </span>
            </>
          )}
        </div>
      )}
    </div>
  );
};

export default TamuLaporPage;
