import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { AlertTriangle, Info } from 'lucide-react';

let _resolve = null;

function dispatch(detail) {
  window.dispatchEvent(new CustomEvent('__vendor_dialog', { detail }));
}

export function vendorConfirm(message, title = 'Konfirmasi') {
  return new Promise((resolve) => {
    _resolve = resolve;
    dispatch({ type: 'confirm', title, message });
  });
}

export function vendorAlert(message, title = 'Informasi') {
  return new Promise((resolve) => {
    _resolve = resolve;
    dispatch({ type: 'alert', title, message });
  });
}

export function VendorConfirmDialog() {
  const [state, setState] = useState({ open: false, type: 'confirm', title: '', message: '' });

  useEffect(() => {
    const handler = (e) => setState({ open: true, ...e.detail });
    window.addEventListener('__vendor_dialog', handler);
    return () => window.removeEventListener('__vendor_dialog', handler);
  }, []);

  const close = (result) => {
    setState(s => ({ ...s, open: false }));
    if (_resolve) { _resolve(result); _resolve = null; }
  };

  if (!state.open) return null;

  const isAlert = state.type === 'alert';

  return createPortal(
    <div className="fixed inset-0 z-[99999] flex items-center justify-center p-4"
      style={{ backdropFilter: 'blur(4px)', background: 'rgba(0,0,0,0.35)' }}>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-in">
        <div className="p-6">
          <div className="flex items-start gap-3 mb-4">
            <div className={`w-9 h-9 rounded-full flex items-center justify-center flex-shrink-0 ${
              isAlert ? 'bg-blue-100' : 'bg-red-100'
            }`}>
              {isAlert
                ? <Info size={18} className="text-blue-600" />
                : <AlertTriangle size={18} className="text-[#ed6f5c]" />}
            </div>
            <div>
              <p className="font-bold text-gray-800 text-sm">{state.title}</p>
              <p className="text-sm text-gray-500 mt-0.5 leading-relaxed">{state.message}</p>
            </div>
          </div>

          {isAlert ? (
            <button onClick={() => close(true)}
              className="w-full bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-xl py-2.5 text-sm font-semibold transition-colors">
              OK
            </button>
          ) : (
            <div className="flex gap-3">
              <button onClick={() => close(false)}
                className="flex-1 border border-gray-200 rounded-xl py-2.5 text-sm font-medium hover:bg-gray-50 text-gray-700 transition-colors">
                Batal
              </button>
              <button onClick={() => close(true)}
                className="flex-1 bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-xl py-2.5 text-sm font-semibold transition-colors">
                Ya, Lanjutkan
              </button>
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}
