import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { API_BASE_URL } from '../config/api';
import { Send, MessageCircle } from 'lucide-react';

const ROLE_LABEL = {
  warga: 'Warga',
  admin: 'RT',
  pengurus_rw: 'RW',
  pengurus_kelurahan: 'Kelurahan',
  rw: 'RW',
  kelurahan: 'Kelurahan',
};

const formatWaktu = (d) => {
  if (!d) return '';
  const date = new Date(d);
  const now = new Date();
  const sameDay = date.toDateString() === now.toDateString();
  const time = date.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
  if (sameDay) return time;
  return `${date.toLocaleDateString('id-ID', { day: '2-digit', month: 'short' })}, ${time}`;
};

/**
 * Thread balasan 2 arah pada satu Pengaduan.
 * Dipakai di dalam Dialog/View detail — cukup drop komponen ini dengan pengaduanId yang aktif.
 */
export default function PengaduanKomentarThread({ pengaduanId, token, currentUserId }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [pesan, setPesan] = useState('');
  const [sending, setSending] = useState(false);
  const [error, setError] = useState(null);
  const bottomRef = useRef(null);

  useEffect(() => {
    if (!pengaduanId || !token) return;
    let cancelled = false;
    setLoading(true);
    setError(null);
    axios.get(`${API_BASE_URL}/api/pengaduan/${pengaduanId}/komentar`, {
      headers: { Authorization: `Bearer ${token}` }
    }).then(res => {
      if (!cancelled) setItems(Array.isArray(res.data) ? res.data : []);
    }).catch(err => {
      if (!cancelled) setError(err.response?.data?.detail || 'Gagal memuat balasan');
    }).finally(() => {
      if (!cancelled) setLoading(false);
    });
    return () => { cancelled = true; };
  }, [pengaduanId, token]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }, [items.length]);

  const handleSend = async () => {
    const text = pesan.trim();
    if (!text || sending) return;
    setSending(true);
    setError(null);
    try {
      const res = await axios.post(
        `${API_BASE_URL}/api/pengaduan/${pengaduanId}/komentar`,
        { pesan: text },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setItems(prev => [...prev, res.data]);
      setPesan('');
    } catch (err) {
      setError(err.response?.data?.detail || 'Gagal mengirim balasan');
    } finally {
      setSending(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="border-t border-[var(--rw-border)] dark:border-gray-700 pt-3 mt-1">
      <p className="font-medium text-gray-700 dark:text-gray-300 mb-2 flex items-center gap-1.5">
        <MessageCircle className="w-4 h-4" /> Balasan
      </p>

      <div className="max-h-56 overflow-y-auto space-y-2 pr-1 mb-2">
        {loading ? (
          <p className="text-xs text-gray-400 py-2">Memuat...</p>
        ) : items.length === 0 ? (
          <p className="text-xs text-gray-400 py-2">Belum ada balasan. Mulai percakapan di bawah.</p>
        ) : (
          items.map(k => {
            const isMine = k.user_id === currentUserId;
            return (
              <div key={k.id} className={`flex ${isMine ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] rounded-lg px-3 py-2 text-sm ${
                  isMine
                    ? 'bg-[var(--rw-primary)] text-white rounded-br-none'
                    : 'bg-[var(--rw-bg-card-alt)] dark:bg-gray-800 text-gray-700 dark:text-gray-200 rounded-bl-none'
                }`}>
                  <p className={`text-[10px] font-semibold mb-0.5 ${isMine ? 'text-white/80' : 'text-gray-500 dark:text-gray-400'}`}>
                    {k.user_name} · {ROLE_LABEL[k.user_role] || k.user_role}
                  </p>
                  <p className="whitespace-pre-line break-words">{k.pesan}</p>
                  <p className={`text-[10px] mt-1 text-right ${isMine ? 'text-white/70' : 'text-gray-400'}`}>
                    {formatWaktu(k.created_at)}
                  </p>
                </div>
              </div>
            );
          })
        )}
        <div ref={bottomRef} />
      </div>

      {error && <p className="text-xs text-red-500 mb-1">{error}</p>}

      <div className="flex gap-2">
        <textarea
          value={pesan}
          onChange={e => setPesan(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Tulis balasan..."
          rows={1}
          className="flex-1 resize-none text-sm rounded-lg border border-[var(--rw-border)] dark:border-gray-700 bg-white dark:bg-gray-900 px-3 py-2 focus:outline-none focus:ring-1 focus:ring-[var(--rw-primary)]"
        />
        <button
          onClick={handleSend}
          disabled={sending || !pesan.trim()}
          className="px-3 rounded-lg bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white disabled:opacity-50 flex items-center justify-center"
          title="Kirim"
        >
          <Send className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}
