import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { useKelurahanFilter } from '../../contexts/KelurahanFilterContext';
import { API_BASE_URL, API_ENDPOINTS } from '../../config/api';
import { FileText, Search, RefreshCw, Eye, BarChart3, X, Check, Inbox } from 'lucide-react';

const STATUS_CONFIG = {
  pending:     { label: 'Menunggu RT',        bg: 'bg-amber-100',  text: 'text-amber-700' },
  rt_approved: { label: 'Menunggu RW',         bg: 'bg-blue-100',   text: 'text-blue-700' },
  rw_approved: { label: 'Perlu TTD Lurah',     bg: 'bg-indigo-100', text: 'text-indigo-700' },
  approved:    { label: 'Diterbitkan',          bg: 'bg-green-100',  text: 'text-green-700' },
  rejected:    { label: 'Ditolak',              bg: 'bg-red-100',    text: 'text-red-700'  },
};

const hdrs = (token) => ({ Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' });

function DetailModal({ open, onClose, item }) {
  if (!open || !item) return null;
  const sc = STATUS_CONFIG[item.status] || STATUS_CONFIG.pending;
  const formatDate = (d) => d
    ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' })
    : '-';
  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-xl max-h-[85vh] flex flex-col">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between flex-shrink-0">
          <div>
            <h3 className="font-bold text-gray-800 text-lg">{item.jenis_surat || 'Detail Surat Resmi'}</h3>
            <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${sc.bg} ${sc.text}`}>{sc.label}</span>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18}/></button>
        </div>
        <div className="flex-1 overflow-y-auto p-5 space-y-3 text-sm">
          <div className="grid grid-cols-2 gap-3">
            <div><p className="text-gray-400 text-xs">Nama Pemohon</p><p className="font-medium text-gray-800">{item.pemohon_nama || '-'}</p></div>
            <div><p className="text-gray-400 text-xs">RT</p><p className="font-medium text-gray-800">{item.tenant_name || '-'}</p></div>
            {item.nomor_surat && <div className="col-span-2"><p className="text-gray-400 text-xs">Nomor Surat</p><p className="font-medium text-gray-800 font-mono">{item.nomor_surat}</p></div>}
            <div><p className="text-gray-400 text-xs">Tanggal Ajuan</p><p className="font-medium text-gray-800">{formatDate(item.created_at)}</p></div>
            {item.issued_at && <div><p className="text-gray-400 text-xs">Tanggal Terbit</p><p className="font-medium text-gray-800">{formatDate(item.issued_at)}</p></div>}
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
}

function ApproveModal({ open, item, onClose, onDone, token }) {
  const [pin, setPin]       = useState('');
  const [catatan, setCatatan] = useState('');
  const [mode, setMode]     = useState('approve');
  const [loading, setLoading] = useState(false);
  const [error, setError]   = useState('');

  useEffect(() => { if (open) { setPin(''); setCatatan(''); setMode('approve'); setError(''); } }, [open]);

  if (!open || !item) return null;

  const handleSubmit = async () => {
    setLoading(true); setError('');
    try {
      const url  = mode === 'approve' ? API_ENDPOINTS.SURAT_KEL_APPROVE(item.id) : API_ENDPOINTS.SURAT_KEL_TOLAK(item.id);
      const body = mode === 'approve' ? { pin } : { catatan };
      const res  = await fetch(url, { method: 'POST', headers: hdrs(token), body: JSON.stringify(body) });
      const data = await res.json();
      if (!res.ok) { setError(data.detail || 'Gagal'); setLoading(false); return; }
      onDone();
    } catch { setError('Terjadi kesalahan'); setLoading(false); }
  };

  return createPortal(
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm">
        <div className="p-5 border-b border-gray-200 flex items-center justify-between">
          <h3 className="font-bold text-gray-800">Tindakan Persetujuan Kelurahan</h3>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X size={18}/></button>
        </div>
        <div className="p-5 space-y-4">
          <div className="bg-indigo-50 rounded-xl p-3 text-sm">
            <p className="font-medium text-indigo-800">{item.jenis_surat}</p>
            <p className="text-indigo-600 text-xs mt-0.5">{item.pemohon_nama} — {item.tenant_name}</p>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setMode('approve')}
              className={`flex-1 py-2 rounded-lg text-sm font-medium border transition-colors ${mode === 'approve' ? 'bg-green-500 text-white border-green-500' : 'border-gray-200 text-gray-600 hover:border-green-300'}`}>
              Terbitkan Surat
            </button>
            <button onClick={() => setMode('tolak')}
              className={`flex-1 py-2 rounded-lg text-sm font-medium border transition-colors ${mode === 'tolak' ? 'bg-red-500 text-white border-red-500' : 'border-gray-200 text-gray-600 hover:border-red-300'}`}>
              Tolak
            </button>
          </div>
          {mode === 'approve' && (
            <div>
              <label className="block text-xs font-medium text-gray-600 mb-1.5">PIN Tanda Tangan (jika ada)</label>
              <input type="password" value={pin} onChange={e => setPin(e.target.value)}
                placeholder="Kosongkan jika tidak menggunakan PIN"
                className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-400"/>
            </div>
          )}
          {mode === 'tolak' && (
            <div>
              <label className="block text-xs font-medium text-gray-600 mb-1.5">Alasan Penolakan <span className="text-red-500">*</span></label>
              <textarea value={catatan} onChange={e => setCatatan(e.target.value)} rows={3}
                placeholder="Tulis alasan penolakan..."
                className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-red-400 resize-none"/>
            </div>
          )}
          {error && <p className="text-xs text-red-600 bg-red-50 rounded-lg px-3 py-2">{error}</p>}
          <button onClick={handleSubmit} disabled={loading || (mode === 'tolak' && !catatan.trim())}
            className={`w-full py-2.5 rounded-lg text-sm font-semibold text-white transition-colors disabled:opacity-50 disabled:cursor-not-allowed ${mode === 'approve' ? 'bg-green-500 hover:bg-green-600' : 'bg-red-500 hover:bg-red-600'}`}>
            {loading ? 'Memproses...' : mode === 'approve' ? 'Konfirmasi Terbitkan' : 'Konfirmasi Tolak'}
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
}

const KelurahanMonitoringSuratResmi = () => {
  const { token } = useAuth();
  const { rwId } = useKelurahanFilter();
  const [data, setData]         = useState(null);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState(null);
  const [search, setSearch]     = useState('');
  const [filterStatus, setFilterStatus] = useState('rw_approved');
  const [viewItem, setViewItem] = useState(null);
  const [approveItem, setApproveItem] = useState(null);

  const fetchData = useCallback(async (q = '', statusFilter = filterStatus) => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const params = new URLSearchParams();
      if (q) params.append('search', q);
      if (rwId) params.append('rw_id', rwId);
      // fetch all for stats, filter client-side
      const res = await axios.get(`${API_BASE_URL}/api/kelurahan/monitoring-surat-resmi?${params}`, { headers });
      setData(res.data);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  }, [token, rwId]);

  useEffect(() => { fetchData(search); }, [token, rwId]);

  const formatDate = (d) => d
    ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
    : '-';

  const allSurat = data?.data || [];
  const stats = data?.stats || {};
  const perluLurah = stats.perlu_lurah || allSurat.filter(s => s.status === 'rw_approved').length;

  const filtered = allSurat.filter(s => {
    const q = search.trim().toLowerCase();
    const matchSearch = !q || (s.pemohon_nama || '').toLowerCase().includes(q) || (s.nomor_surat || '').toLowerCase().includes(q) || (s.jenis_surat || '').toLowerCase().includes(q);
    const matchStatus = !filterStatus || s.status === filterStatus;
    return matchSearch && matchStatus;
  });

  if (loading && !data) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat data surat resmi...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>Kelurahan</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Monitoring Surat Resmi</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-amber-500 to-orange-600 rounded-xl flex items-center justify-center shadow">
            <FileText className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Monitoring Surat Resmi</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Permohonan surat resmi warga — {data?.total || 0} surat</p>
          </div>
        </div>
        <button onClick={() => fetchData(search)} className="flex items-center gap-2 px-3 py-2 text-sm bg-[var(--rw-bg-card)] dark:bg-gray-800 border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors">
          <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {/* Alert banner jika ada surat perlu TTD Lurah */}
      {perluLurah > 0 && filterStatus !== 'rw_approved' && (
        <div className="bg-indigo-50 dark:bg-indigo-900/20 border border-indigo-200 dark:border-indigo-800 rounded-xl px-4 py-3 flex items-center gap-3">
          <Inbox size={18} className="text-indigo-500 flex-shrink-0"/>
          <p className="text-sm text-indigo-700 dark:text-indigo-300 flex-1">
            Ada <strong>{perluLurah} surat</strong> menunggu tanda tangan Lurah untuk diterbitkan
          </p>
          <button onClick={() => setFilterStatus('rw_approved')}
            className="text-xs px-3 py-1.5 bg-indigo-500 hover:bg-indigo-600 text-white rounded-lg flex-shrink-0 transition-colors">
            Proses Sekarang
          </button>
        </div>
      )}

      {/* Stats Cards — clickable filter */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Total Surat',       value: data?.total || 0,   color: 'from-blue-500 to-indigo-600',    filter: '' },
          { label: 'Perlu TTD Lurah',   value: perluLurah,          color: 'from-indigo-500 to-purple-600', filter: 'rw_approved' },
          { label: 'Diterbitkan',        value: allSurat.filter(s => s.status === 'approved').length,   color: 'from-green-500 to-emerald-600', filter: 'approved' },
          { label: 'Ditolak',            value: allSurat.filter(s => s.status === 'rejected').length,   color: 'from-red-500 to-rose-600',      filter: 'rejected' },
        ].map((card) => (
          <button key={card.label} onClick={() => setFilterStatus(card.filter)}
            className={`bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow p-4 flex items-center gap-3 text-left transition-all ${filterStatus === card.filter ? 'ring-2 ring-offset-1 ring-indigo-400' : 'hover:opacity-80'}`}>
            <div className={`w-10 h-10 bg-gradient-to-br ${card.color} rounded-lg flex items-center justify-center flex-shrink-0`}>
              <FileText className="h-5 w-5 text-white" />
            </div>
            <div>
              <p className="text-xs text-gray-500 dark:text-gray-400">{card.label}</p>
              <p className="text-xl font-bold text-gray-900 dark:text-white">{card.value}</p>
            </div>
          </button>
        ))}
      </div>

      {/* Volume per Bulan Chart */}
      {stats.volume_per_bulan && stats.volume_per_bulan.length > 0 && (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow">
          <div className="p-4 border-b border-[var(--rw-border)] dark:border-gray-700 flex items-center gap-2">
            <BarChart3 className="h-5 w-5 text-amber-500" />
            <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">Volume Surat Resmi per Bulan</h3>
          </div>
          <div className="p-4">
            <div className="flex items-end gap-2 h-28">
              {stats.volume_per_bulan.map((v, i) => {
                const maxVal = Math.max(...stats.volume_per_bulan.map(x => x.jumlah || 0), 1);
                const pct = Math.round(((v.jumlah || 0) / maxVal) * 100);
                return (
                  <div key={i} className="flex-1 flex flex-col items-center gap-1">
                    <span className="text-xs text-gray-500 dark:text-gray-400">{v.jumlah}</span>
                    <div className="w-full bg-gradient-to-t from-amber-500 to-orange-400 rounded-t-sm"
                      style={{ height: `${Math.max(pct, 4)}%`, minHeight: '4px' }} />
                    <span className="text-xs text-gray-400 dark:text-gray-500 truncate w-full text-center">{v.bulan}</span>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {/* Search + filter */}
      <div className="flex gap-3">
        <form onSubmit={(e) => { e.preventDefault(); fetchData(search); }} className="flex gap-3 flex-1">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <input
              placeholder="Cari nama pemohon, nomor surat..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="w-full pl-9 pr-3 py-2 border border-[var(--rw-border)] dark:border-gray-600 rounded-lg text-sm bg-[var(--rw-bg-card)] dark:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-amber-400 text-gray-700 dark:text-gray-200"
            />
          </div>
          <button type="submit" className="px-4 py-2 bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white text-sm rounded-lg transition-colors">Cari</button>
          {search && (
            <button type="button" onClick={() => { setSearch(''); fetchData(''); }}
              className="px-4 py-2 bg-[var(--rw-bg-card-alt)] dark:bg-gray-700 text-gray-700 dark:text-gray-300 text-sm rounded-lg">Reset</button>
          )}
        </form>
        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)}
          className="border border-[var(--rw-border)] dark:border-gray-600 rounded-lg px-3 py-2 text-sm bg-[var(--rw-bg-card)] dark:bg-gray-800 text-gray-700 dark:text-gray-200 focus:outline-none focus:ring-2 focus:ring-amber-400">
          <option value="">Semua Status</option>
          <option value="pending">Menunggu RT</option>
          <option value="rt_approved">Menunggu RW</option>
          <option value="rw_approved">Perlu TTD Lurah ✦</option>
          <option value="approved">Diterbitkan</option>
          <option value="rejected">Ditolak</option>
        </select>
      </div>

      {/* Table */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        <div className="p-4 border-b border-[var(--rw-border)] dark:border-gray-700 flex items-center justify-between">
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">
            {filterStatus === 'rw_approved' ? 'Surat Menunggu Tanda Tangan Lurah' : 'Daftar Surat Resmi'}
          </h3>
          <span className="text-sm text-gray-500 dark:text-gray-400">{filtered.length} surat</span>
        </div>
        {filtered.length > 0 ? (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-[var(--rw-bg-card-alt)] dark:bg-gray-700">
                  {['Nomor Surat', 'Jenis Surat', 'Pemohon', 'RT', 'Status', 'Tanggal', 'Aksi'].map(h => (
                    <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--rw-border)] dark:divide-gray-700">
                {filtered.map(s => {
                  const sc = STATUS_CONFIG[s.status] || STATUS_CONFIG.pending;
                  return (
                    <tr key={s.id} className={`hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700/50 ${s.status === 'rw_approved' ? 'bg-indigo-50/40 dark:bg-indigo-900/10' : ''}`}>
                      <td className="px-4 py-3">
                        {s.nomor_surat
                          ? <span className="font-mono text-xs text-gray-700 dark:text-gray-300">{s.nomor_surat}</span>
                          : <span className="text-gray-400 text-xs">—</span>}
                      </td>
                      <td className="px-4 py-3">
                        <span className="text-xs font-bold px-2 py-0.5 rounded bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-400 mr-1">{s.kode || ''}</span>
                        <span className="text-gray-700 dark:text-gray-300">{s.jenis_surat || '—'}</span>
                      </td>
                      <td className="px-4 py-3 font-medium text-gray-800 dark:text-gray-200">{s.pemohon_nama}</td>
                      <td className="px-4 py-3 text-xs text-gray-500 dark:text-gray-400">{s.tenant_name || '—'}</td>
                      <td className="px-4 py-3">
                        <span className={`text-xs px-2.5 py-1 rounded-full font-medium ${sc.bg} ${sc.text}`}>{sc.label}</span>
                      </td>
                      <td className="px-4 py-3 text-xs text-gray-500 dark:text-gray-400 whitespace-nowrap">
                        {formatDate(s.created_at)}
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-1.5">
                          <button onClick={() => setViewItem(s)}
                            className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded transition-colors">
                            <Eye className="h-4 w-4" />
                          </button>
                          {s.status === 'rw_approved' && (
                            <button onClick={() => setApproveItem(s)}
                              className="flex items-center gap-1 text-xs px-2.5 py-1.5 bg-indigo-500 hover:bg-indigo-600 text-white rounded-lg transition-colors">
                              <Check size={12}/> Terbitkan
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            <div className="px-4 py-3 border-t border-[var(--rw-border)] dark:border-gray-700 text-xs text-gray-400">
              {filtered.length} dari {data?.total || 0} surat resmi
            </div>
          </div>
        ) : (
          <div className="text-center py-12">
            <FileText className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
            <p className="text-gray-500 dark:text-gray-400">
              {filterStatus === 'rw_approved' ? 'Tidak ada surat menunggu tanda tangan Lurah' : 'Belum ada surat resmi'}
            </p>
            {filterStatus && (
              <button onClick={() => setFilterStatus('')} className="mt-2 text-xs text-indigo-500 hover:underline">
                Tampilkan semua surat
              </button>
            )}
          </div>
        )}
      </div>

      <DetailModal open={!!viewItem} onClose={() => setViewItem(null)} item={viewItem} />
      <ApproveModal
        open={!!approveItem}
        item={approveItem}
        token={token}
        onClose={() => setApproveItem(null)}
        onDone={() => { setApproveItem(null); fetchData(search); }}
      />
    </div>
  );
};

export default KelurahanMonitoringSuratResmi;
