import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { API_BASE_URL } from '@/config/api';
import { Plus, Trash2, GripVertical, Edit2, Check, X } from 'lucide-react';
import { countryCodeToFlag } from '@/utils/countryFlag';
import { toast } from '@/components/ui/sonner';
import {
  AlertDialog,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogContent,
  AlertDialogCancel,
  AlertDialogAction,
} from '@/components/ui/alert-dialog';

const KATEGORI_META = {
  strata_ekonomi: { label: 'Strata Ekonomi', color: 'blue', hint: 'Contoh: Desil 1, Desil 2, ...' },
  bantuan_sosial:  { label: 'Bantuan Sosial',  color: 'green', hint: 'Contoh: PKH, PIP, BLT, ...' },
  negara: { label: 'Negara (Kewarganegaraan)', color: 'purple', hint: 'Kode ISO 3166-1 2 huruf, mis. ID, MY, SG — dipakai untuk dropdown Kewarganegaraan di form Warga' },
  status_warga: { label: 'Status Warga', color: 'orange', hint: 'Contoh: Aktif, Kontrak, Kos, Pendatang Warga Sementara, Pindah, Meninggal, Tidak Aktif — dipakai untuk dropdown Status di form Warga' },
  pekerjaan: { label: 'Pekerjaan', color: 'teal', hint: 'Dipakai untuk dropdown Pekerjaan di form Warga' },
  posisi_keluarga: { label: 'Posisi Keluarga', color: 'pink', hint: 'Contoh: Kepala Keluarga, Istri, Anak — dipakai untuk dropdown Posisi Keluarga di form Warga' },
  agama: { label: 'Agama', color: 'indigo', hint: 'Dipakai untuk dropdown Agama di form Warga' },
  jenis_kelamin: { label: 'Jenis Kelamin', color: 'rose', hint: 'Dipakai untuk dropdown Jenis Kelamin di form Warga' },
  kategori_informasi: { label: 'Kategori Informasi', color: 'blue', hint: 'Dipakai untuk dropdown Kategori di menu Informasi RT' },
  link_eksternal: { label: 'Link Eksternal (Menu Embed)', color: 'cyan', hint: 'Isi "Nilai" dengan URL lengkap (https://...) dan "Label" dengan judul menu. Muncul otomatis sebagai menu baru (embed iframe) di sidebar RT, RW, Kelurahan, dan Warga. Centang "Proxy" kalau situs tujuan menolak tampil di iframe langsung (server kita yang akan ambil kontennya) — catatan: situs dengan form/CAPTCHA interaktif bisa saja tetap gagal di langkah submit meski proxy diaktifkan. Nonaktifkan togglenya untuk sembunyikan menu tanpa hapus datanya.' },
  jenis_kepemilikan_rumah: { label: 'Jenis Bangunan (Menu Rumah)', color: 'teal', hint: 'Dipakai untuk dropdown "Jenis Bangunan" di menu Rumah RT — menggantikan "Jenis Pemilik" lama.' },
  status_hunian_rumah: { label: 'Status Hunian (Menu Rumah)', color: 'rose', hint: 'Dipakai untuk dropdown "Status Hunian" di menu Rumah RT — menggantikan "Status Penghuni" lama. Nilai "Kosong" otomatis menandai rumah sebagai kosong (menggantikan checkbox "Sedang Kosong" yang sudah dihapus dari form).' },
};

const DEFAULTS = {
  strata_ekonomi: [
    {nilai:'Desil 1'},{nilai:'Desil 2'},{nilai:'Desil 3'},{nilai:'Desil 4'},{nilai:'Desil 5'},
    {nilai:'Desil 6'},{nilai:'Desil 7'},{nilai:'Desil 8'},{nilai:'Desil 9'},{nilai:'Desil 10'},
  ],
  bantuan_sosial: [
    {nilai:'PKH',label:'Program Keluarga Harapan'},
    {nilai:'PIP',label:'Program Indonesia Pintar'},
    {nilai:'KIP',label:'Kartu Indonesia Pintar'},
    {nilai:'PBI-JK',label:'Penerima Bantuan Iuran Jaminan Kesehatan'},
    {nilai:'BST',label:'Bantuan Sosial Tunai'},
    {nilai:'BLT',label:'Bantuan Langsung Tunai'},
    {nilai:'BB/CCP',label:'Beras Bulog / Cadangan Pangan'},
    {nilai:'Rutilahu',label:'Rumah Tidak Layak Huni'},
  ],
};

function OpsiTable({ kategori, token }) {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [adding, setAdding] = useState(false);
  const [newNilai, setNewNilai] = useState('');
  const [newLabel, setNewLabel] = useState('');
  const [newUseProxy, setNewUseProxy] = useState(false);
  const [editId, setEditId] = useState(null);
  const [editNilai, setEditNilai] = useState('');
  const [editLabel, setEditLabel] = useState('');
  const [deleteConfirm, setDeleteConfirm] = useState(null); // id opsi yang mau dihapus
  const [seedConfirm, setSeedConfirm] = useState(false);

  const headers = { Authorization: `Bearer ${token}` };
  const meta = KATEGORI_META[kategori];

  const load = async () => {
    try {
      setLoading(true);
      const res = await axios.get(`${API_BASE_URL}/api/vendor/opsi-referensi/?kategori=${kategori}`, { headers });
      setRows(res.data);
    } catch { setRows([]); }
    finally { setLoading(false); }
  };

  useEffect(() => { load(); }, [kategori]);

  const handleAdd = async () => {
    if (!newNilai.trim()) return;
    try {
      await axios.post(`${API_BASE_URL}/api/vendor/opsi-referensi/`, {
        kategori, nilai: newNilai.trim(), label: newLabel.trim() || null, urutan: rows.length,
        ...(kategori === 'link_eksternal' ? { use_proxy: newUseProxy } : {}),
      }, { headers });
      setNewNilai(''); setNewLabel(''); setNewUseProxy(false); setAdding(false);
      load();
      toast.success('Opsi berhasil ditambahkan');
    } catch (e) { toast.error('Gagal menambah: ' + (e.response?.data?.detail || e.message)); }
  };

  const handleToggleProxy = async (row) => {
    try {
      await axios.put(`${API_BASE_URL}/api/vendor/opsi-referensi/${row.id}`, { use_proxy: !row.use_proxy }, { headers });
      load();
    } catch (e) { toast.error('Gagal update: ' + e.message); }
  };

  const handleEdit = async (id) => {
    try {
      await axios.put(`${API_BASE_URL}/api/vendor/opsi-referensi/${id}`, {
        nilai: editNilai.trim(), label: editLabel.trim() || null,
      }, { headers });
      setEditId(null); load();
      toast.success('Opsi berhasil diperbarui');
    } catch (e) { toast.error('Gagal update: ' + (e.response?.data?.detail || e.message)); }
  };

  const handleDelete = async () => {
    if (!deleteConfirm) return;
    try {
      await axios.delete(`${API_BASE_URL}/api/vendor/opsi-referensi/${deleteConfirm}`, { headers });
      load();
      toast.success('Opsi dihapus');
    } catch (e) { toast.error('Gagal hapus: ' + e.message); }
    finally { setDeleteConfirm(null); }
  };

  const handleToggleAktif = async (row) => {
    try {
      await axios.put(`${API_BASE_URL}/api/vendor/opsi-referensi/${row.id}`, { aktif: !row.aktif }, { headers });
      load();
    } catch (e) { toast.error('Gagal update: ' + e.message); }
  };

  const handleSeed = async () => {
    try {
      await axios.post(`${API_BASE_URL}/api/vendor/opsi-referensi/seed`, {}, { headers });
      load();
      toast.success('Data default berhasil dimuat');
    } catch (e) { toast.error('Gagal seed: ' + e.message); }
    finally { setSeedConfirm(false); }
  };

  const colorMap = {
    blue: 'bg-blue-100 text-blue-700', green: 'bg-green-100 text-green-700',
    purple: 'bg-purple-100 text-purple-700', orange: 'bg-orange-100 text-orange-700',
    teal: 'bg-teal-100 text-teal-700', pink: 'bg-pink-100 text-pink-700',
    indigo: 'bg-indigo-100 text-indigo-700', rose: 'bg-rose-100 text-rose-700',
    cyan: 'bg-cyan-100 text-cyan-700',
  };
  const isLink = kategori === 'link_eksternal';
  const nilaiPlaceholder = isLink ? 'https://...' : 'Nilai / kode';
  const labelPlaceholder = isLink ? 'Judul menu (mis. Cek Bansos Kemensos)' : 'Label (opsional)';

  return (
    <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden">
      {/* Header */}
      <div className="px-6 py-4 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between">
        <div>
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">{meta.label}</h3>
          <p className="text-xs text-gray-500 mt-0.5">{meta.hint}</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setSeedConfirm(true)} className="text-xs px-3 py-1.5 rounded-lg border border-gray-300 text-gray-600 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-400">
            Reset Default
          </button>
          <button onClick={() => setAdding(true)} className="flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg bg-orange-500 text-white hover:bg-orange-600">
            <Plus className="w-3.5 h-3.5" /> Tambah
          </button>
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-700/30">
              <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 uppercase w-8">#</th>
              <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 uppercase">{isLink ? 'URL' : 'Nilai (Kode)'}</th>
              <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 uppercase">{isLink ? 'Judul Menu' : 'Label / Deskripsi'}</th>
              {isLink && <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 uppercase">Proxy</th>}
              <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 uppercase">Status</th>
              <th className="text-right px-4 py-2.5 text-xs font-semibold text-gray-500 uppercase">Aksi</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
            {loading && (
              <tr><td colSpan={isLink ? 6 : 5} className="text-center py-8 text-gray-400 text-sm">Memuat...</td></tr>
            )}
            {!loading && rows.length === 0 && (
              <tr><td colSpan={isLink ? 6 : 5} className="text-center py-8 text-gray-400 text-sm">
                Belum ada opsi. Klik "Reset Default" untuk isi data awal.
              </td></tr>
            )}
            {rows.map((row, i) => (
              <tr key={row.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/20">
                <td className="px-4 py-2.5 text-gray-400 text-xs">{i + 1}</td>
                <td className="px-4 py-2.5">
                  {editId === row.id ? (
                    <input value={editNilai} onChange={e => setEditNilai(e.target.value)}
                      className={`border border-gray-300 rounded px-2 py-1 text-xs dark:bg-gray-700 dark:border-gray-600 dark:text-white ${isLink ? 'w-72' : 'w-32'}`} />
                  ) : isLink ? (
                    <a href={row.nilai} target="_blank" rel="noreferrer" className="text-xs text-cyan-700 dark:text-cyan-400 underline break-all">
                      {row.nilai}
                    </a>
                  ) : (
                    <span className={`px-2 py-0.5 rounded-full text-xs font-semibold ${colorMap[meta.color]}`}>
                      {kategori === 'negara' && <span className="mr-1">{countryCodeToFlag(row.nilai)}</span>}
                      {row.nilai}
                    </span>
                  )}
                </td>
                <td className="px-4 py-2.5 text-gray-600 dark:text-gray-400">
                  {editId === row.id ? (
                    <input value={editLabel} onChange={e => setEditLabel(e.target.value)}
                      className="border border-gray-300 rounded px-2 py-1 text-xs w-48 dark:bg-gray-700 dark:border-gray-600 dark:text-white"
                      placeholder="Label opsional" />
                  ) : (
                    <span className="text-xs">{row.label || <span className="text-gray-300">—</span>}</span>
                  )}
                </td>
                {isLink && (
                  <td className="px-4 py-2.5">
                    <label className="inline-flex items-center gap-1.5 cursor-pointer" title="Kalau situs tujuan menolak di-iframe langsung (X-Frame-Options), aktifkan ini supaya dimuat lewat proxy server kita">
                      <input type="checkbox" checked={!!row.use_proxy} onChange={() => handleToggleProxy(row)}
                        className="rounded border-gray-300 text-cyan-600 focus:ring-cyan-500" />
                      <span className="text-xs text-gray-500">{row.use_proxy ? 'Aktif' : 'Nonaktif'}</span>
                    </label>
                  </td>
                )}
                <td className="px-4 py-2.5">
                  <button onClick={() => handleToggleAktif(row)}
                    className={`text-xs px-2 py-0.5 rounded-full font-semibold ${row.aktif ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}>
                    {row.aktif ? 'Aktif' : 'Nonaktif'}
                  </button>
                </td>
                <td className="px-4 py-2.5">
                  <div className="flex gap-2 justify-end">
                    {editId === row.id ? (
                      <>
                        <button onClick={() => handleEdit(row.id)} className="p-1 text-green-600 hover:bg-green-50 rounded"><Check className="w-3.5 h-3.5" /></button>
                        <button onClick={() => setEditId(null)} className="p-1 text-gray-400 hover:bg-gray-50 rounded"><X className="w-3.5 h-3.5" /></button>
                      </>
                    ) : (
                      <>
                        <button onClick={() => { setEditId(row.id); setEditNilai(row.nilai); setEditLabel(row.label || ''); }}
                          className="p-1 text-blue-500 hover:bg-blue-50 rounded"><Edit2 className="w-3.5 h-3.5" /></button>
                        <button onClick={() => setDeleteConfirm(row.id)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 className="w-3.5 h-3.5" /></button>
                      </>
                    )}
                  </div>
                </td>
              </tr>
            ))}

            {/* Add row inline */}
            {adding && (
              <tr className="bg-blue-50 dark:bg-blue-900/10">
                <td className="px-4 py-2.5 text-gray-300">—</td>
                <td className="px-4 py-2.5">
                  <input value={newNilai} onChange={e => setNewNilai(e.target.value)}
                    placeholder={nilaiPlaceholder} autoFocus
                    className={`border border-blue-300 rounded px-2 py-1 text-xs dark:bg-gray-700 dark:border-gray-600 dark:text-white ${isLink ? 'w-72' : 'w-32'}`} />
                </td>
                <td className="px-4 py-2.5">
                  <input value={newLabel} onChange={e => setNewLabel(e.target.value)}
                    placeholder={labelPlaceholder}
                    className="border border-blue-300 rounded px-2 py-1 text-xs w-48 dark:bg-gray-700 dark:border-gray-600 dark:text-white" />
                </td>
                {isLink && (
                  <td className="px-4 py-2.5">
                    <label className="inline-flex items-center gap-1.5 cursor-pointer">
                      <input type="checkbox" checked={newUseProxy} onChange={e => setNewUseProxy(e.target.checked)}
                        className="rounded border-gray-300 text-cyan-600 focus:ring-cyan-500" />
                      <span className="text-xs text-gray-500">Proxy</span>
                    </label>
                  </td>
                )}
                <td />
                <td className="px-4 py-2.5">
                  <div className="flex gap-2 justify-end">
                    <button onClick={handleAdd} className="p-1 text-green-600 hover:bg-green-50 rounded"><Check className="w-3.5 h-3.5" /></button>
                    <button onClick={() => { setAdding(false); setNewNilai(''); setNewLabel(''); }} className="p-1 text-gray-400 hover:bg-gray-50 rounded"><X className="w-3.5 h-3.5" /></button>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Konfirmasi Hapus — dialog standar bawaan sistem, bukan browser confirm() */}
      <AlertDialog open={deleteConfirm !== null} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus opsi ini?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-red-600 hover:bg-red-700">
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Konfirmasi Reset Default */}
      <AlertDialog open={seedConfirm} onOpenChange={setSeedConfirm}>
        <AlertDialogContent className="bg-[#f7f1de] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Reset ke opsi default?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Hanya akan mengisi data kalau tabel kategori ini masih kosong.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction onClick={handleSeed} className="bg-orange-500 hover:bg-orange-600">
              Reset
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

export default function VendorOpsiReferensi({ token }) {
  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-xl font-bold text-gray-900 dark:text-gray-100">Opsi Referensi</h2>
        <p className="text-sm text-gray-500 mt-1">
          Kelola semua pilihan dropdown yang dipakai di form warga RT/RW/Kelurahan: <strong>Strata Ekonomi</strong>, <strong>Bantuan Sosial</strong>, <strong>Negara (Kewarganegaraan)</strong>, <strong>Status Warga</strong>, <strong>Pekerjaan</strong>, <strong>Posisi Keluarga</strong>, <strong>Agama</strong>, <strong>Jenis Kelamin</strong>, dan <strong>Kategori Informasi</strong>.
        </p>
      </div>
      <OpsiTable kategori="strata_ekonomi" token={token} />
      <OpsiTable kategori="bantuan_sosial" token={token} />
      <OpsiTable kategori="negara" token={token} />
      <OpsiTable kategori="status_warga" token={token} />
      <OpsiTable kategori="pekerjaan" token={token} />
      <OpsiTable kategori="posisi_keluarga" token={token} />
      <OpsiTable kategori="agama" token={token} />
      <OpsiTable kategori="jenis_kelamin" token={token} />
      <OpsiTable kategori="kategori_informasi" token={token} />
      <OpsiTable kategori="link_eksternal" token={token} />
      <OpsiTable kategori="jenis_kepemilikan_rumah" token={token} />
      <OpsiTable kategori="status_hunian_rumah" token={token} />
    </div>
  );
}
