import React, { createContext, useContext, useState, useEffect } from 'react';
import { API_BASE_URL } from '../config/api';

const DEFAULTS = {
  appName:        'Ruang Warga',
  appVersion:     '2.4',
  appTitle:       'Ruang Warga App',
  appDescription: 'Solusi Terintegrasi untuk RT, RW, dan Kelurahan',
  logoUrl:        null,
  kopLogoUrl:     null,
  socialTwitter:  null,
  socialFacebook: null,
  socialYoutube:  null,
  socialTiktok:    null,
  socialDiscord:   null,
  socialInstagram: null,
  socialTwitterEnabled:  true,
  socialFacebookEnabled: true,
  socialYoutubeEnabled:  true,
  socialTiktokEnabled:    true,
  socialDiscordEnabled:   true,
  socialInstagramEnabled: true,
  kelurahanBillingEnabled: true,
  // Tampilan widget Support Chat (diatur vendor di menu Settings)
  supportWidget: {
    theme: 'green',          // green | blue | dark
    color: null,             // override hex custom, mis. "#7c3aed"
    icon: 'message-circle',  // message-circle | headset | help-circle | message-square
    position: 'left',        // left | right
  },
  notifikasiAktif: null,   // notifikasi vendor default yg published (atau null)
  banners:         [],     // daftar banner vendor yg published, urut sort_order
  bannerConfig: {          // ukuran banner (px), bisa dicustom vendor lewat Settings
    dashboardHeight: 160,
    loginHeight: 56,
    loginMaxWidth: 384,
    stretchMode: true,     // true = stretch penuh ke kotak; false = fit + transparan sisi kiri/kanan
    dashboardPosition: 'top', // 'top' (bawah header) atau 'bottom' (bawah konten halaman)
    transitionType: 'fade',       // fade / slide / zoom / none
    transitionDurationMs: 700,    // lama animasi transisi antar banner (ms)
  },
};

const AppSettingsContext = createContext(DEFAULTS);

const resolveUrl = (url) => {
  if (!url) return null;
  if (url.startsWith('http')) return url;
  return `${API_BASE_URL}${url}`;
};

export function AppSettingsProvider({ children }) {
  const [settings, setSettings] = useState(DEFAULTS);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/app/settings`)
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (!data) return;
        const next = {
          appName:        data.app_name        || DEFAULTS.appName,
          appVersion:     data.app_version     || DEFAULTS.appVersion,
          appTitle:       data.app_title       || DEFAULTS.appTitle,
          appDescription: data.app_description || DEFAULTS.appDescription,
          logoUrl:        resolveUrl(data.logo_url),
          kopLogoUrl:     resolveUrl(data.kop_logo_url),
          socialTwitter:  data.social_twitter  || null,
          socialFacebook: data.social_facebook || null,
          socialYoutube:  data.social_youtube  || null,
          socialTiktok:    data.social_tiktok    || null,
          socialDiscord:   data.social_discord   || null,
          socialInstagram: data.social_instagram || null,
          socialTwitterEnabled:  data.social_twitter_enabled  !== false,
          socialFacebookEnabled: data.social_facebook_enabled !== false,
          socialYoutubeEnabled:  data.social_youtube_enabled  !== false,
          socialTiktokEnabled:    data.social_tiktok_enabled    !== false,
          socialDiscordEnabled:   data.social_discord_enabled   !== false,
          socialInstagramEnabled: data.social_instagram_enabled !== false,
          kelurahanBillingEnabled: data.kelurahan_billing_enabled !== false,
          supportWidget: {
            theme:    data.support_widget_theme    || DEFAULTS.supportWidget.theme,
            color:    data.support_widget_color    || null,
            icon:     data.support_widget_icon     || DEFAULTS.supportWidget.icon,
            position: data.support_widget_position || DEFAULTS.supportWidget.position,
          },
        };
        setSettings(s => ({ ...s, ...next }));
        document.title = next.appTitle;
        if (next.logoUrl) {
          let link = document.querySelector("link[rel~='icon']");
          if (!link) {
            link = document.createElement('link');
            link.rel = 'icon';
            document.head.appendChild(link);
          }
          link.href = next.logoUrl;
        }
      })
      .catch(() => {});

    // Notifikasi vendor (default + published) — banner teks dashboard RT/RW/Kel
    fetch(`${API_BASE_URL}/api/app/notifikasi-aktif`)
      .then(r => r.ok ? r.json() : null)
      .then(data => setSettings(s => ({ ...s, notifikasiAktif: data || null })))
      .catch(() => {});

    // Banner gambar vendor (published, urut sort_order) — carousel login & dashboard
    fetch(`${API_BASE_URL}/api/app/banners`)
      .then(r => r.ok ? r.json() : [])
      .then(data => setSettings(s => ({
        ...s,
        banners: Array.isArray(data)
          ? data.map(b => ({ ...b, image_url: resolveUrl(b.image_url) }))
          : [],
      })))
      .catch(() => {});

    // Ukuran banner custom vendor (px) — dashboard height, login height & max width
    fetch(`${API_BASE_URL}/api/app/banner-config`)
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (!data) return;
        setSettings(s => ({
          ...s,
          bannerConfig: {
            dashboardHeight: data.dashboard_height ?? DEFAULTS.bannerConfig.dashboardHeight,
            loginHeight:     data.login_height     ?? DEFAULTS.bannerConfig.loginHeight,
            loginMaxWidth:   data.login_max_width  ?? DEFAULTS.bannerConfig.loginMaxWidth,
            stretchMode:     data.stretch_mode      ?? DEFAULTS.bannerConfig.stretchMode,
            dashboardPosition: data.dashboard_position ?? DEFAULTS.bannerConfig.dashboardPosition,
            transitionType:      data.transition_type        ?? DEFAULTS.bannerConfig.transitionType,
            transitionDurationMs: data.transition_duration_ms ?? DEFAULTS.bannerConfig.transitionDurationMs,
          },
        }));
      })
      .catch(() => {});
  }, []);

  return (
    <AppSettingsContext.Provider value={settings}>
      {children}
    </AppSettingsContext.Provider>
  );
}

export const useAppSettings = () => useContext(AppSettingsContext);
