import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '@/config/api';
import { toast } from '@/components/ui/sonner';
import { vendorConfirm } from './VendorConfirm';
import { Palette, Check, Plus, Pencil, Trash2, Loader2, X } from 'lucide-react';

const token = () => localStorage.getItem('vendor_token');
const hdrs  = () => ({ Authorization: `Bearer ${token()}` });

const COLOR_FIELDS = [
  { key: 'bg_page',       label: 'Latar Halaman' },
  { key: 'bg_card',       label: 'Latar Kartu' },
  { key: 'bg_card_alt',   label: 'Latar Panel Filter' },
  { key: 'border',        label: 'Garis Tepi' },
  { key: 'primary',       label: 'Warna Utama (tombol/aksen)' },
  { key: 'primary_hover', label: 'Warna Utama — Hover' },
  { key: 'text_accent',   label: 'Warna Teks Aksen' },
];

const emptyColors = {
  bg_page: '#efe7d2', bg_card: '#f7f1de', bg_card_alt: '#ece4cf',
  border: '#d5cebc', primary: '#ed6f5c', primary_hover: '#e05544',
  text_accent: '#ed6f5c',
};

function ThemeSwatch({ colors }) {
  return (
    <div className="flex items-center -space-x-1.5">
      {['bg_page', 'primary', 'primary_hover', 'text_accent'].map((k, i) => (
        <span
          key={k}
          className="w-5 h-5 rounded-full border-2 border-white shadow-sm"
          style={{ backgroundColor: colors[k], zIndex: 4 - i }}
        />
      ))}
    </div>
  );
}

function ThemeFormModal({ open, onClose, onSave, editData }) {
  const [name, setName] = useState('');
  const [colors, setColors] = useState(emptyColors);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (open) {
      setName(editData?.name || '');
      setColors(editData?.colors || emptyColors);
    }
  }, [open, editData]);

  if (!open) return null;

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!name.trim()) { toast.error('Nama tema wajib diisi'); return; }
    setSaving(true);
    try {
      const url = editData
        ? `${API_BASE_URL}/api/vendor/theme-settings/custom/${editData.id}`
        : `${API_BASE_URL}/api/vendor/theme-settings/custom`;
      const res = await fetch(url, {
        method: editData ? 'PUT' : 'POST',
        headers: { ...hdrs(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, colors }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menyimpan tema');
      toast.success(editData ? 'Tema custom berhasil diperbarui' : 'Tema custom berhasil dibuat');
      onSave();
      onClose();
    } catch (e) {
      toast.error(e.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-y-auto">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100">
          <h3 className="font-bold text-gray-800">{editData ? 'Edit Tema Custom' : 'Buat Tema Custom'}</h3>
          <button onClick={onClose} className="p-1 rounded-lg hover:bg-gray-100 text-gray-400">
            <X size={16} />
          </button>
        </div>
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1">Nama Tema *</label>
            <input
              value={name}
              onChange={e => setName(e.target.value)}
              placeholder="contoh: Biru Kelurahan Kami"
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500"
              required
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {COLOR_FIELDS.map(f => (
              <div key={f.key}>
                <label className="text-xs font-medium text-gray-600 block mb-1">{f.label}</label>
                <div className="flex items-center gap-2 border border-gray-200 rounded-lg px-2 py-1.5">
                  <input
                    type="color"
                    value={colors[f.key]}
                    onChange={e => setColors(c => ({ ...c, [f.key]: e.target.value }))}
                    className="w-8 h-8 rounded cursor-pointer border-0 bg-transparent flex-shrink-0"
                  />
                  <input
                    value={colors[f.key]}
                    onChange={e => setColors(c => ({ ...c, [f.key]: e.target.value }))}
                    className="flex-1 min-w-0 text-xs font-mono text-gray-600 focus:outline-none"
                  />
                </div>
              </div>
            ))}
          </div>

          {/* Preview mini */}
          <div className="rounded-xl border border-gray-200 p-4" style={{ backgroundColor: colors.bg_page }}>
            <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Preview</p>
            <div className="rounded-lg p-3" style={{ backgroundColor: colors.bg_card, border: `1px solid ${colors.border}` }}>
              <p className="text-sm font-bold" style={{ color: colors.text_accent }}>Contoh Judul</p>
              <button
                type="button"
                className="mt-2 px-3 py-1.5 rounded-lg text-white text-xs font-semibold"
                style={{ backgroundColor: colors.primary }}
              >
                Contoh Tombol
              </button>
            </div>
          </div>

          <div className="flex gap-2 pt-2">
            <button type="button" onClick={onClose}
              className="flex-1 py-2.5 rounded-xl border border-gray-200 text-sm text-gray-600 hover:bg-gray-50">
              Batal
            </button>
            <button type="submit" disabled={saving}
              className="flex-1 py-2.5 rounded-xl bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm font-semibold disabled:opacity-50">
              {saving ? 'Menyimpan...' : editData ? 'Simpan Perubahan' : 'Buat Tema'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default function VendorThemeSettings() {
  const [data, setData] = useState(null); // { active_id, presets, custom }
  const [loading, setLoading] = useState(true);
  const [activating, setActivating] = useState(null); // id yang sedang diproses
  const [formOpen, setFormOpen] = useState(false);
  const [editTheme, setEditTheme] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/theme-settings`, { headers: hdrs() });
      const json = await res.json();
      if (!res.ok) throw new Error(json.detail || 'Gagal memuat tema');
      setData(json);
    } catch (e) {
      toast.error(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const activate = async (themeId) => {
    if (activating) return;
    setActivating(themeId);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/theme-settings/activate`, {
        method: 'PUT',
        headers: { ...hdrs(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ theme_id: themeId }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.detail || 'Gagal mengaktifkan tema');
      setData(d => ({ ...d, active_id: themeId }));
      toast.success('Tema warna berhasil diaktifkan. Halaman non-vendor (login, RT/RW/Kelurahan/Warga) akan memakai tema ini.');
    } catch (e) {
      toast.error(e.message);
    } finally {
      setActivating(null);
    }
  };

  const remove = async (theme) => {
    const ok = await vendorConfirm(`Hapus tema custom "${theme.name}"? Tindakan ini tidak bisa dibatalkan.`, 'Hapus Tema');
    if (!ok) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/theme-settings/custom/${theme.id}`, {
        method: 'DELETE', headers: hdrs(),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.detail || 'Gagal menghapus tema');
      toast.success('Tema custom berhasil dihapus');
      load();
    } catch (e) {
      toast.error(e.message);
    }
  };

  if (loading) {
    return (
      <div className="lg:col-span-3 bg-white rounded-xl border border-gray-200 p-5 flex justify-center py-16">
        <Loader2 size={24} className="animate-spin text-gray-400" />
      </div>
    );
  }
  if (!data) return null;

  const allThemes = [...data.presets, ...data.custom];

  return (
    <div className="lg:col-span-3 bg-white rounded-xl border border-gray-200 p-5 space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-sm font-semibold text-gray-800 flex items-center gap-2">
            <Palette size={15} className="text-[#ed6f5c]" /> Tema Warna
          </h2>
          <p className="text-xs text-gray-400 mt-0.5">
            Mengatur warna tampilan untuk halaman login &amp; dashboard RT/RW/Kelurahan/Warga (bukan halaman vendor ini).
          </p>
        </div>
        <button
          onClick={() => { setEditTheme(null); setFormOpen(true); }}
          className="flex items-center gap-1.5 px-3 py-2 rounded-lg bg-gray-800 hover:bg-gray-900 text-white text-xs font-semibold flex-shrink-0"
        >
          <Plus size={13} /> Tema Custom
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {allThemes.map(theme => {
          const isActive = data.active_id === theme.id;
          const isCustom = !theme.is_preset;
          const isBusy = activating === theme.id;
          return (
            <div
              key={theme.id}
              className={`relative rounded-xl border-2 p-3 transition-colors ${
                isActive ? 'border-[#ed6f5c]' : 'border-gray-200 hover:border-gray-300'
              }`}
              style={{ backgroundColor: theme.colors.bg_page }}
            >
              {isActive && (
                <span className="absolute top-2 right-2 w-5 h-5 rounded-full bg-[#ed6f5c] text-white flex items-center justify-center">
                  <Check size={11} />
                </span>
              )}
              <div className="rounded-lg p-2.5 mb-2" style={{ backgroundColor: theme.colors.bg_card, border: `1px solid ${theme.colors.border}` }}>
                <ThemeSwatch colors={theme.colors} />
              </div>
              <p className="text-xs font-semibold text-gray-800 truncate">{theme.name}</p>
              <p className="text-[10px] text-gray-400 mb-2">{isCustom ? 'Custom' : 'Preset bawaan'}</p>

              <div className="flex items-center gap-1.5">
                <button
                  onClick={() => activate(theme.id)}
                  disabled={isActive || isBusy}
                  className={`flex-1 py-1.5 rounded-lg text-[11px] font-semibold transition-colors ${
                    isActive
                      ? 'bg-gray-100 text-gray-400 cursor-default'
                      : 'text-white hover:opacity-90'
                  }`}
                  style={!isActive ? { backgroundColor: theme.colors.primary } : {}}
                >
                  {isBusy ? 'Memproses...' : isActive ? 'Aktif' : 'Aktifkan'}
                </button>
                {isCustom && (
                  <>
                    <button
                      onClick={() => { setEditTheme(theme); setFormOpen(true); }}
                      className="p-1.5 rounded-lg bg-white/70 text-gray-500 hover:text-gray-800"
                      title="Edit tema"
                    >
                      <Pencil size={12} />
                    </button>
                    <button
                      onClick={() => remove(theme)}
                      className="p-1.5 rounded-lg bg-white/70 text-gray-500 hover:text-red-500"
                      title="Hapus tema"
                    >
                      <Trash2 size={12} />
                    </button>
                  </>
                )}
              </div>
            </div>
          );
        })}
      </div>

      <ThemeFormModal
        open={formOpen}
        onClose={() => { setFormOpen(false); setEditTheme(null); }}
        onSave={load}
        editData={editTheme}
      />
    </div>
  );
}
