import { useEffect, useState } from "react";
import axios from "axios";
import { API_BASE_URL } from "@/config/api";
import { useAuth } from "@/contexts/AuthContext";
import { useRWFilter } from "@/contexts/RWFilterContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "@/components/ui/sonner";
import { Users, RefreshCw, MapPin, CheckCircle2, XCircle } from "lucide-react";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import UserForm from "../users/UserForm";

export default function RWUsers() {
  const { token, user }       = useAuth();
  const { rtId, rtList }      = useRWFilter(); // terhubung ke dropdown header

  const [users, setUsers]     = useState([]);
  const [tenantMap, setTenantMap] = useState({}); // tenant_id → label
  const [loading, setLoading] = useState(true);
  const [search, setSearch]   = useState("");

  const [openForm, setOpenForm]         = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);

  const headers = { Authorization: `Bearer ${token}` };

  const loadUsers = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_BASE_URL}/api/users`, { headers });
      setUsers(res.data || []);
    } catch {
      toast.error("Gagal memuat data pengguna");
    }
    setLoading(false);
  };

  // Build tenant_id → label map dari rtList context + RW sendiri
  useEffect(() => {
    const map = {};
    rtList.forEach(rt => {
      // rtList item: { id, nama_rt, no_rt, ... }
      map[rt.id] = rt.nama_rt || rt.name || `RT ${rt.no_rt}`;
    });
    if (user?.tenant_id) map[user.tenant_id] = "RW";
    setTenantMap(map);
  }, [rtList, user]);

  useEffect(() => { loadUsers(); }, [token]);

  const getWilayah = (u) => {
    if (!u.tenant_id) return "-";
    return tenantMap[u.tenant_id] || "RW";
  };

  // Filter: pakai rtId dari header dropdown global, lalu search lokal
  const filtered = users
    .filter(u => {
      if (!rtId) return true;                // "Semua RT" → tampil semua
      return u.tenant_id === rtId;           // filter sesuai RT dipilih
    })
    .filter(u =>
      !search ||
      u.fullname?.toLowerCase().includes(search.toLowerCase()) ||
      u.username?.toLowerCase().includes(search.toLowerCase()) ||
      u.role?.toLowerCase().includes(search.toLowerCase())
    );

  const handleDelete = async (id) => {
    if (!window.confirm("Hapus pengguna ini?")) return;
    try {
      await axios.delete(`${API_BASE_URL}/api/users/${id}`, { headers });
      toast.success("Pengguna berhasil dihapus");
      loadUsers();
    } catch {
      toast.error("Gagal menghapus pengguna");
    }
  };

  return (
    <div className="p-6 space-y-5 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Pengguna</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center shadow">
            <Users className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Pengguna</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              Kelola pengguna di RW ini dan RT di bawahnya
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={loadUsers}
            className="flex items-center gap-1.5 px-3 py-2 text-sm bg-[var(--rw-bg-card)] dark:bg-gray-800 border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors">
            <RefreshCw className="h-4 w-4" />
          </button>
          <Button onClick={() => { setSelectedUser(null); setOpenForm(true); }}
            className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white">
            + Tambah User
          </Button>
        </div>
      </div>

      {/* Search */}
      <div className="flex gap-3 items-center">
        <Input
          placeholder="Cari nama, email, atau role..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="flex-1 dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
        />
        {rtId && (
          <span className="text-xs text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 px-3 py-1.5 rounded-lg border border-blue-200 dark:border-blue-700 flex items-center gap-1">
            <MapPin className="h-3 w-3" />
            Filter: {tenantMap[rtId] || 'RT'}
          </span>
        )}
      </div>

      {/* Table */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        {loading ? (
          <div className="flex items-center justify-center py-16">
            <div className="w-10 h-10 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
          </div>
        ) : (
          <>
            <Table>
              <TableHeader>
                <TableRow className="dark:border-gray-700">
                  <TableHead>Nama</TableHead>
                  <TableHead>Email</TableHead>
                  <TableHead>No. WhatsApp</TableHead>
                  <TableHead>Blok / No. Rumah</TableHead>
                  <TableHead>
                    <div className="flex items-center gap-1">
                      <MapPin className="h-3.5 w-3.5 text-blue-500" />
                      Wilayah
                    </div>
                  </TableHead>
                  <TableHead>Role</TableHead>
                  <TableHead className="text-center">Status</TableHead>
                  <TableHead className="text-right">Aksi</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={8} className="text-center text-gray-400 py-10">
                      Tidak ada pengguna {rtId ? `di ${tenantMap[rtId] || 'RT ini'}` : ''}
                    </TableCell>
                  </TableRow>
                ) : filtered.map(u => (
                  <TableRow key={u.id} className="dark:border-gray-700 dark:hover:bg-gray-700/50">
                    <TableCell className="font-medium text-gray-900 dark:text-white">
                      {u.fullname}
                    </TableCell>
                    <TableCell className="text-gray-600 dark:text-gray-300 text-sm">
                      {u.username}
                    </TableCell>
                    <TableCell className="text-gray-600 dark:text-gray-300 text-sm">
                      {u.country_code || '+62'} {u.whatsapp}
                    </TableCell>
                    <TableCell className="text-gray-600 dark:text-gray-300 text-sm">
                      {u.block_house || '-'}
                    </TableCell>
                    <TableCell>
                      <span className={`inline-flex items-center gap-1 text-xs font-semibold px-2 py-0.5 rounded-full ${
                        getWilayah(u) === 'RW'
                          ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300'
                          : 'bg-cyan-100 dark:bg-cyan-900/30 text-cyan-700 dark:text-cyan-300'
                      }`}>
                        <MapPin className="h-3 w-3" />
                        {getWilayah(u)}
                      </span>
                    </TableCell>
                    <TableCell className="text-sm text-gray-600 dark:text-gray-300">
                      {u.role}
                    </TableCell>
                    <TableCell className="text-center">
                      {u.status === 'active'
                        ? <CheckCircle2 className="w-5 h-5 text-green-500 mx-auto" />
                        : <XCircle className="w-5 h-5 text-red-400 mx-auto" />}
                    </TableCell>
                    <TableCell className="text-right">
                      <button
                        onClick={() => { setSelectedUser(u); setOpenForm(true); }}
                        className="text-xs px-2.5 py-1.5 rounded-lg bg-blue-50 text-blue-700 border border-blue-200 hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-700 transition-colors font-medium"
                      >
                        Edit
                      </button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
            <div className="px-4 py-3 text-sm text-gray-500 dark:text-gray-400 border-t border-gray-100 dark:border-gray-700">
              {filtered.length} dari {users.length} pengguna
            </div>
          </>
        )}
      </div>

      {/* Form */}
      <UserForm
        open={openForm}
        onOpenChange={setOpenForm}
        user={selectedUser}
        onSaved={() => { loadUsers(); setSelectedUser(null); }}
      />
    </div>
  );
}
