import React, { useState, useEffect, useCallback, useRef } from 'react';
import { createPortal } from 'react-dom';
import { API_BASE_URL } from '../../config/api';
import { toast } from '@/components/ui/sonner';
import { vendorConfirm } from './VendorConfirm';
import {
  Headset, Plus, Trash2, RefreshCw, Edit2, X, Loader2, MessageCircle, Smartphone, Upload,
} from 'lucide-react';

const token = () => localStorage.getItem('vendor_token');
const hdrs  = () => ({ Authorization: `Bearer ${token()}`, 'Content-Type': 'application/json' });
// Upload file TIDAK boleh menyertakan Content-Type manual — browser harus
// mengisinya sendiri lengkap dengan boundary multipart.
const authOnly = () => ({ Authorization: `Bearer ${token()}` });

const initial = (n) => (n || '?').trim().charAt(0).toUpperCase();

const EMPTY_FORM = { name: '', role_label: '', whatsapp: '', device_id: '', is_active: true };

function AgentFormModal({ open, onClose, onSaved, editData, devices }) {
  const [form, setForm] = useState(EMPTY_FORM);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!open) return;
    setError('');
    setForm(editData ? {
      name:       editData.name || '',
      role_label: editData.role_label || '',
      whatsapp:   editData.whatsapp || '',
      device_id:  editData.device_id || '',
      is_active:  editData.is_active !== false,
    } : EMPTY_FORM);
  }, [open, editData]);

  if (!open) return null;

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name.trim()) { setError('Nama wajib diisi'); return; }
    if (!form.whatsapp.trim()) { setError('Nomor WhatsApp wajib diisi'); return; }

    setSaving(true);
    setError('');
    try {
      const payload = {
        name: form.name.trim(),
        role_label: form.role_label.trim() || null,
        whatsapp: form.whatsapp.trim(),
        device_id: form.device_id || '',   // '' = otomatis (device aktif pertama)
        is_active: form.is_active,
      };
      const url = editData
        ? `${API_BASE_URL}/api/vendor/support-agents/${editData.id}`
        : `${API_BASE_URL}/api/vendor/support-agents`;
      const method = editData ? 'PATCH' : 'POST';
      const res = await fetch(url, { method, headers: hdrs(), body: JSON.stringify(payload) });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menyimpan');
      toast.success(editData ? 'Support agent diperbarui' : 'Support agent ditambahkan');
      onSaved();
      onClose();
    } catch (err) {
      setError(err.message);
    } finally {
      setSaving(false);
    }
  };

  return createPortal(
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[9999] p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-bold text-gray-900">{editData ? 'Edit Support Agent' : 'Tambah Support Agent'}</h2>
          <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-gray-100">
            <X size={18} className="text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {error && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-600">{error}</div>
          )}

          {/* Nama agent */}
          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1.5">
              Nama Agent <span className="text-red-500">*</span>
            </label>
            <input value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
              placeholder="mis. Budi Santoso"
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-green-500" />
          </div>

          {/* Jabatan */}
          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1.5">Jabatan / Peran (opsional)</label>
            <input value={form.role_label} onChange={e => setForm(f => ({ ...f, role_label: e.target.value }))}
              placeholder="mis. Admin Support, Teknisi WA"
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-green-500" />
          </div>

          {/* Nomor WA */}
          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1.5">
              Nomor WhatsApp <span className="text-red-500">*</span>
            </label>
            <input value={form.whatsapp} onChange={e => setForm(f => ({ ...f, whatsapp: e.target.value }))}
              placeholder="contoh: 081234567890"
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-green-500" />
            <p className="text-xs text-gray-400 mt-1">Otomatis dinormalisasi ke format 62xxx saat disimpan.</p>
          </div>

          {/* Nomor relay (WA Device) */}
          <div>
            <label className="text-sm font-medium text-gray-700 block mb-1.5">Nomor WhatsApp Relay</label>
            <select value={form.device_id} onChange={e => setForm(f => ({ ...f, device_id: e.target.value }))}
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-green-500 bg-white">
              <option value="">Otomatis — pakai device aktif pertama</option>
              {devices.map(d => (
                <option key={d.id} value={d.id} disabled={!d.ready}>
                  {d.name}{d.phone_number ? ` — +${d.phone_number}` : ''} {d.ready ? '(online)' : '(offline)'}
                </option>
              ))}
            </select>
            <p className="text-xs text-gray-400 mt-1">
              Nomor yang dipakai sistem untuk meneruskan chat ke WhatsApp agent ini. Device offline tidak bisa dipilih —
              hubungkan dulu di menu <strong>WA Devices</strong>.
            </p>
          </div>

          {/* Aktif */}
          <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer">
            <input type="checkbox" checked={form.is_active}
              onChange={e => setForm(f => ({ ...f, is_active: e.target.checked }))}
              className="rounded border-gray-300 text-green-600 focus:ring-green-500/30" />
            Aktif — muncul di widget Support Chat
          </label>

          <div className="flex gap-3 pt-2">
            <button type="button" onClick={onClose}
              className="flex-1 px-4 py-2 rounded-xl border border-gray-300 text-sm text-gray-600 hover:bg-gray-50">
              Batal
            </button>
            <button type="submit" disabled={saving}
              className="flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-xl bg-green-600 hover:bg-green-700 text-white text-sm font-medium disabled:opacity-50">
              {saving ? <Loader2 size={15} className="animate-spin" /> : <Plus size={15} />}
              {saving ? 'Menyimpan...' : editData ? 'Simpan Perubahan' : 'Tambah Agent'}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  );
}

export default function VendorSupportAgents() {
  const [agents, setAgents] = useState([]);
  const [devices, setDevices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editData, setEditData] = useState(null);
  const [deletingId, setDeletingId] = useState(null);
  const [uploadingId, setUploadingId] = useState(null);
  const avatarInputRef = useRef(null);
  const avatarTargetRef = useRef(null);   // id agent yang sedang diganti fotonya

  const pickAvatar = (agentId) => {
    avatarTargetRef.current = agentId;
    avatarInputRef.current?.click();
  };

  const handleAvatarFile = async (file) => {
    const agentId = avatarTargetRef.current;
    if (!file || !agentId) return;
    if (!file.type.startsWith('image/')) { toast.error('File harus berupa gambar'); return; }
    if (file.size > 2 * 1024 * 1024) { toast.error('Ukuran foto maksimal 2 MB'); return; }
    setUploadingId(agentId);
    try {
      const fd = new FormData();
      fd.append('file', file);
      const res = await fetch(`${API_BASE_URL}/api/vendor/support-agents/${agentId}/avatar`, {
        method: 'POST', headers: authOnly(), body: fd,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal mengunggah foto');
      toast.success('Foto agent diperbarui');
      loadAgents();
    } catch (e) {
      toast.error(e.message);
    } finally {
      setUploadingId(null);
      avatarTargetRef.current = null;
      if (avatarInputRef.current) avatarInputRef.current.value = '';
    }
  };

  const removeAvatar = async (agent) => {
    if (!await vendorConfirm(`Hapus foto agent "${agent.name}"?`, 'Hapus Foto')) return;
    setUploadingId(agent.id);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/support-agents/${agent.id}/avatar`, {
        method: 'DELETE', headers: hdrs(),
      });
      if (!res.ok) throw new Error('Gagal menghapus foto');
      toast.success('Foto dihapus');
      loadAgents();
    } catch (e) {
      toast.error(e.message);
    } finally { setUploadingId(null); }
  };

  const loadAgents = useCallback(async () => {
    if (!token()) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/support-agents`, { headers: hdrs() });
      if (res.ok) setAgents(await res.json());
    } catch { /* silent */ } finally {
      setLoading(false);
    }
  }, []);

  // Daftar device WA (untuk memilih nomor relay) — reuse endpoint menu WA Devices
  const loadDevices = useCallback(async () => {
    if (!token()) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/whatsapp-devices`, { headers: hdrs() });
      if (res.ok) setDevices(await res.json());
    } catch { /* silent */ }
  }, []);

  useEffect(() => { loadAgents(); loadDevices(); }, [loadAgents, loadDevices]);

  const handleAdd = () => { setEditData(null); setShowModal(true); };
  const handleEdit = (agent) => { setEditData(agent); setShowModal(true); };

  const handleDelete = async (agent) => {
    if (!await vendorConfirm(`Hapus support agent "${agent.name}"? Kontak ini tidak akan lagi muncul di widget Support Chat.`, 'Hapus Support Agent')) return;
    setDeletingId(agent.id);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/support-agents/${agent.id}`, {
        method: 'DELETE', headers: hdrs(),
      });
      if (res.ok) { toast.success('Support agent dihapus'); loadAgents(); }
      else { const d = await res.json(); toast.error(d.detail || 'Gagal menghapus'); }
    } catch { toast.error('Gagal menghubungi server'); }
    finally { setDeletingId(null); }
  };

  const toggleActive = async (agent) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/support-agents/${agent.id}`, {
        method: 'PATCH', headers: hdrs(),
        body: JSON.stringify({ is_active: !agent.is_active }),
      });
      if (res.ok) { loadAgents(); }
      else { const d = await res.json(); toast.error(d.detail || 'Gagal mengubah status'); }
    } catch { toast.error('Gagal menghubungi server'); }
  };

  return (
    <div className="p-6 space-y-5 bg-[#f7f1de] min-h-full">
      {/* Header */}
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-green-600 flex items-center justify-center shadow">
            <Headset size={20} className="text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Support Agent</h1>
            <p className="text-sm text-gray-500">Kelola kontak WhatsApp support untuk widget Support Chat — berlaku untuk semua RT/RW/Kelurahan</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={() => { loadAgents(); loadDevices(); }}
            className="p-2 rounded-lg bg-white shadow-sm hover:bg-gray-100" title="Refresh">
            <RefreshCw size={16} className="text-gray-500" />
          </button>
          <button onClick={handleAdd}
            className="flex items-center gap-2 px-4 py-2 rounded-xl bg-green-600 hover:bg-green-700 text-white text-sm font-medium shadow">
            <Plus size={16} /> Tambah Support Agent
          </button>
        </div>
      </div>

      {/* Info banner */}
      <div className="bg-green-50 border border-green-200 rounded-xl px-4 py-3 text-sm text-green-800">
        <strong>Cara kerja:</strong> Semua agent aktif di sini muncul untuk admin RT, RW, maupun Kelurahan/Desa — tidak dibatasi per wilayah. Saat warga/pengurus mulai chat lewat widget, pesan WhatsApp pertama otomatis menyertakan info wilayah pengirim (RT/RW/Kelurahan mana), jadi agent langsung tahu asalnya.
      </div>

      {/* List */}
      {loading ? (
        <div className="flex items-center justify-center py-16">
          <Loader2 size={28} className="animate-spin text-green-600" />
        </div>
      ) : agents.length === 0 ? (
        <div className="bg-white rounded-2xl shadow p-12 text-center">
          <Headset size={48} className="mx-auto text-gray-300 mb-3" />
          <p className="text-gray-500 text-sm mb-4">Belum ada support agent terdaftar</p>
          <button onClick={handleAdd}
            className="flex items-center gap-2 px-4 py-2 rounded-xl bg-green-600 hover:bg-green-700 text-white text-sm font-medium mx-auto">
            <Plus size={15} /> Tambah Agent Pertama
          </button>
        </div>
      ) : (
        <div className="bg-white rounded-2xl shadow overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-gray-50 text-xs text-gray-500 uppercase">
              <tr>
                <th className="px-4 py-3 text-left w-16">Foto</th>
                <th className="px-4 py-3 text-left">Nama</th>
                <th className="px-4 py-3 text-left">Jabatan</th>
                <th className="px-4 py-3 text-left">No. WhatsApp</th>
                <th className="px-4 py-3 text-left">Nomor Relay</th>
                <th className="px-4 py-3 text-center">Status</th>
                <th className="px-4 py-3 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {agents.map(a => (
                <tr key={a.id} className="hover:bg-gray-50">
                  <td className="px-4 py-3">
                    <div className="relative group w-11 h-11">
                      {a.avatar_url ? (
                        <img src={`${API_BASE_URL}${a.avatar_url}`} alt={a.name}
                          className="w-11 h-11 rounded-full object-cover border border-gray-200" />
                      ) : (
                        <div className="w-11 h-11 rounded-full bg-green-100 text-green-700 flex items-center justify-center font-bold">
                          {initial(a.name)}
                        </div>
                      )}
                      <button onClick={() => pickAvatar(a.id)} disabled={uploadingId === a.id}
                        title="Ganti foto"
                        className="absolute inset-0 rounded-full bg-black/50 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                        {uploadingId === a.id
                          ? <Loader2 size={14} className="animate-spin" />
                          : <Upload size={14} />}
                      </button>
                      {a.avatar_url && uploadingId !== a.id && (
                        <button onClick={() => removeAvatar(a)} title="Hapus foto"
                          className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-red-500 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                          <X size={9} />
                        </button>
                      )}
                    </div>
                  </td>
                  <td className="px-4 py-3 font-medium text-gray-800">{a.name}</td>
                  <td className="px-4 py-3 text-gray-500">{a.role_label || '-'}</td>
                  <td className="px-4 py-3 text-gray-600">
                    <span className="flex items-center gap-1.5">
                      <MessageCircle size={13} className="text-green-500" /> +{a.whatsapp}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    {a.device_name ? (
                      <span className="inline-flex items-center gap-1.5 text-xs text-gray-600">
                        <Smartphone size={12} className="text-gray-400" />
                        {a.device_name}{a.device_phone ? ` (+${a.device_phone})` : ''}
                      </span>
                    ) : (
                      <span className="text-xs text-gray-400 italic">Otomatis</span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-center">
                    <button onClick={() => toggleActive(a)}
                      className={`text-xs px-2.5 py-1 rounded-full font-medium transition-colors ${
                        a.is_active
                          ? 'bg-green-100 text-green-700 hover:bg-green-200'
                          : 'bg-gray-100 text-gray-500 hover:bg-gray-200'
                      }`}>
                      {a.is_active ? 'Aktif' : 'Nonaktif'}
                    </button>
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center justify-end gap-1.5">
                      <button onClick={() => handleEdit(a)}
                        className="p-1.5 rounded-lg text-gray-500 hover:bg-gray-100 hover:text-gray-700">
                        <Edit2 size={15} />
                      </button>
                      <button onClick={() => handleDelete(a)} disabled={deletingId === a.id}
                        className="p-1.5 rounded-lg text-red-500 hover:bg-red-50 disabled:opacity-50">
                        {deletingId === a.id ? <Loader2 size={15} className="animate-spin" /> : <Trash2 size={15} />}
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Satu input file dipakai bergantian oleh semua baris — target agent
          disimpan di avatarTargetRef saat tombol ganti foto diklik. */}
      <input ref={avatarInputRef} type="file" accept="image/png,image/jpeg,image/webp"
        className="hidden" onChange={e => handleAvatarFile(e.target.files?.[0])} />

      <AgentFormModal
        open={showModal}
        onClose={() => setShowModal(false)}
        onSaved={loadAgents}
        editData={editData}
        devices={devices}
      />
    </div>
  );
}
