import React, { useEffect, useState } from 'react';
import { Heart } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { API_BASE_URL } from '@/config/api';

// Warna badge cycling untuk bantuan yang tidak ada di config
const BADGE_COLORS = [
  'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300',
  'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300',
  'bg-orange-100 text-orange-700 dark:bg-orange-900/40 dark:text-orange-300',
  'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300',
  'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300',
  'bg-rose-100 text-rose-700 dark:bg-rose-900/40 dark:text-rose-300',
  'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300',
  'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300',
];

const CARD_COLORS = [
  { bg: 'bg-blue-50 dark:bg-blue-900/20', border: 'border-blue-200 dark:border-blue-700', num: 'text-blue-700 dark:text-blue-300', lbl: 'text-blue-600 dark:text-blue-400' },
  { bg: 'bg-emerald-50 dark:bg-emerald-900/20', border: 'border-emerald-200 dark:border-emerald-700', num: 'text-emerald-700 dark:text-emerald-300', lbl: 'text-emerald-600 dark:text-emerald-400' },
  { bg: 'bg-orange-50 dark:bg-orange-900/20', border: 'border-orange-200 dark:border-orange-700', num: 'text-orange-700 dark:text-orange-300', lbl: 'text-orange-600 dark:text-orange-400' },
  { bg: 'bg-purple-50 dark:bg-purple-900/20', border: 'border-purple-200 dark:border-purple-700', num: 'text-purple-700 dark:text-purple-300', lbl: 'text-purple-600 dark:text-purple-400' },
  { bg: 'bg-amber-50 dark:bg-amber-900/20', border: 'border-amber-200 dark:border-amber-700', num: 'text-amber-700 dark:text-amber-300', lbl: 'text-amber-600 dark:text-amber-400' },
  { bg: 'bg-rose-50 dark:bg-rose-900/20', border: 'border-rose-200 dark:border-rose-700', num: 'text-rose-700 dark:text-rose-300', lbl: 'text-rose-600 dark:text-rose-400' },
  { bg: 'bg-cyan-50 dark:bg-cyan-900/20', border: 'border-cyan-200 dark:border-cyan-700', num: 'text-cyan-700 dark:text-cyan-300', lbl: 'text-cyan-600 dark:text-cyan-400' },
  { bg: 'bg-indigo-50 dark:bg-indigo-900/20', border: 'border-indigo-200 dark:border-indigo-700', num: 'text-indigo-700 dark:text-indigo-300', lbl: 'text-indigo-600 dark:text-indigo-400' },
];

const BantuanSosialWidget = ({ stats, forPrint = false }) => {
  const [bantuanOpsi, setBantuanOpsi] = useState([]);
  const [page, setPage] = useState(1);
  const PER_PAGE = 10;

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/referensi/bantuan-sosial`)
      .then(r => r.json())
      .then(data => setBantuanOpsi(Array.isArray(data) ? data : []))
      .catch(() => {});
  }, []);

  useEffect(() => {
    setPage(1);
  }, [stats]);

  if (!stats || stats.total_penerima === 0) return null;

  const penerima = stats.penerima || [];
  const hasRT = penerima.some(p => p.rt_name && p.rt_name !== '-');
  const hasRW = penerima.some(p => p.rw_name && p.rw_name !== '-');

  // Ambil keys dari response stats (bantuan_keys) atau dari opsi API atau fallback
  const _opsi = Array.isArray(bantuanOpsi) ? bantuanOpsi : [];
  const bantuan_keys = stats.bantuan_keys
    || (_opsi.length > 0 ? _opsi.map(o => o.nilai) : ['PKH','PIP','KIP','PBI-JK','BST','BLT','BB/CCP','Rutilahu']);

  // Build label map dari opsi
  const labelMap = {};
  (Array.isArray(bantuanOpsi) ? bantuanOpsi : []).forEach(o => { labelMap[o.nilai] = o.label || o.nilai; });

  const getBadge = (key, idx) => BADGE_COLORS[idx % BADGE_COLORS.length];
  const getCard = (idx) => CARD_COLORS[idx % CARD_COLORS.length];

  return (
    <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow">
      {/* Header */}
      <div className="p-4 border-b border-[var(--rw-border)] dark:border-gray-700 flex items-center gap-2">
        <Heart className="h-5 w-5 text-rose-500 flex-shrink-0" />
        <div>
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">
            Penerima Bantuan Sosial
          </h3>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            {stats.total_penerima} warga penerima bantuan
            {stats.total_warga ? ` dari ${stats.total_warga} total warga` : ''}
          </p>
        </div>
      </div>

      {/* Stat Cards — dynamic */}
      <div className="p-4 border-b border-[var(--rw-border)] dark:border-gray-700">
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {bantuan_keys.map((key, idx) => {
            const col = getCard(idx);
            const count = stats[key] || 0;
            const desc = labelMap[key] || key;
            return (
              <div key={key} className={`rounded-lg border p-3 text-center ${col.bg} ${col.border}`}>
                <p className={`text-2xl font-bold ${col.num}`}>{count}</p>
                <p className={`text-xs font-semibold mt-0.5 ${col.lbl}`}>{key}</p>
                <p className="text-[10px] text-gray-400 dark:text-gray-500 leading-tight mt-0.5 line-clamp-2">
                  {desc}
                </p>
              </div>
            );
          })}
        </div>
      </div>

      {/* Table */}
      {penerima.length > 0 && (
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[var(--rw-border)] dark:border-gray-700 bg-[var(--rw-bg-page)]/50 dark:bg-gray-700/30">
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">Nama Warga</th>
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">Blok Rumah</th>
                {hasRT && <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">RT</th>}
                {hasRW && <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">RW</th>}
                <th className="text-left px-4 py-2.5 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">Bantuan Diterima</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--rw-border)] dark:divide-gray-700">
              {(forPrint ? penerima : penerima.slice((page - 1) * PER_PAGE, page * PER_PAGE))
                .map((p, i) => (
                <tr key={i} className="hover:bg-[var(--rw-bg-page)]/40 dark:hover:bg-gray-700/20 transition-colors">
                  <td className="px-4 py-2.5 font-medium text-gray-900 dark:text-gray-100">{p.nama}</td>
                  <td className="px-4 py-2.5 text-gray-600 dark:text-gray-400 font-mono text-sm">{p.blok_rumah}</td>
                  {hasRT && <td className="px-4 py-2.5 text-gray-600 dark:text-gray-400 text-xs">{p.rt_name || '-'}</td>}
                  {hasRW && <td className="px-4 py-2.5 text-gray-600 dark:text-gray-400 text-xs">{p.rw_name || '-'}</td>}
                  <td className="px-4 py-2.5">
                    <div className="flex flex-wrap gap-1">
                      {(p.bantuan || []).map((b, bi) => (
                        <span key={b} className={`px-1.5 py-0.5 rounded text-[10px] font-semibold ${getBadge(b, bantuan_keys.indexOf(b) >= 0 ? bantuan_keys.indexOf(b) : bi)}`}>
                          {b}
                        </span>
                      ))}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {!forPrint && penerima.length > PER_PAGE && (
            <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-400 px-4 py-3 border-t border-[var(--rw-border)] dark:border-gray-700">
              <span>
                {(page - 1) * PER_PAGE + 1}-{Math.min(page * PER_PAGE, penerima.length)} dari {penerima.length}
              </span>
              <div className="flex gap-2">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={page === 1}
                  className="dark:border-gray-700 dark:text-gray-200"
                >
                  Sebelumnya
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setPage((p) => Math.min(Math.ceil(penerima.length / PER_PAGE), p + 1))}
                  disabled={page === Math.ceil(penerima.length / PER_PAGE)}
                  className="dark:border-gray-700 dark:text-gray-200"
                >
                  Selanjutnya
                </Button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default BantuanSosialWidget;
