import React, { useState, useEffect, useCallback, useRef } from 'react';
import { API_BASE_URL } from '../../config/api';
import { toast } from '@/components/ui/sonner';
import {
  Inbox, RefreshCw, Send, Loader2, Paperclip, MapPin, Search, X, Headset,
} from 'lucide-react';

const MAX_FILE_BYTES = 8 * 1024 * 1024;

const token = () => localStorage.getItem('vendor_token');
const hdrs  = () => ({ Authorization: `Bearer ${token()}`, 'Content-Type': 'application/json' });

const LIST_POLL_MS = 10_000;
const CHAT_POLL_MS = 5_000;

function initials(name) {
  return (name || '?').trim().charAt(0).toUpperCase();
}

function waktu(iso) {
  if (!iso) return '';
  try {
    const d = new Date(iso);
    const now = new Date();
    const sameDay = d.toDateString() === now.toDateString();
    return sameDay
      ? d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })
      : d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short' });
  } catch { return ''; }
}

export default function VendorSupportInbox() {
  const [convos, setConvos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeId, setActiveId] = useState(null);
  const [active, setActive] = useState(null);
  const [messages, setMessages] = useState([]);
  const [loadingChat, setLoadingChat] = useState(false);
  const [input, setInput] = useState('');
  const [sending, setSending] = useState(false);
  const [search, setSearch] = useState('');
  const [agentFilter, setAgentFilter] = useState('');   // '' = semua agent
  const [attachment, setAttachment] = useState(null); // { data, mimetype, filename }

  const listEndRef = useRef(null);
  const fileRef = useRef(null);

  const loadConvos = useCallback(async () => {
    if (!token()) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/support-chat/vendor/conversations`, { headers: hdrs() });
      if (res.ok) setConvos(await res.json());
    } catch { /* silent */ } finally { setLoading(false); }
  }, []);

  useEffect(() => {
    loadConvos();
    const id = setInterval(loadConvos, LIST_POLL_MS);
    return () => clearInterval(id);
  }, [loadConvos]);

  const loadMessages = useCallback(async (cid, spinner = false) => {
    if (!cid) return;
    if (spinner) setLoadingChat(true);
    try {
      const res = await fetch(
        `${API_BASE_URL}/api/support-chat/vendor/conversations/${cid}/messages`,
        { headers: hdrs() },
      );
      if (res.ok) {
        const data = await res.json();
        setActive(data.conversation);
        setMessages(data.messages || []);
      }
    } catch { /* silent */ } finally { if (spinner) setLoadingChat(false); }
  }, []);

  useEffect(() => {
    if (!activeId) return;
    loadMessages(activeId, true);
    const id = setInterval(() => loadMessages(activeId), CHAT_POLL_MS);
    return () => clearInterval(id);
  }, [activeId, loadMessages]);

  useEffect(() => {
    listEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }, [messages]);

  const handleFile = (file) => {
    if (!file) return;
    if (file.size > MAX_FILE_BYTES) {
      toast.error('Ukuran file maksimal 8 MB');
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result || '');
      setAttachment({
        data: result.includes(',') ? result.split(',')[1] : result,
        mimetype: file.type || 'application/octet-stream',
        filename: file.name,
      });
    };
    reader.readAsDataURL(file);
  };

  const clearAttachment = () => {
    setAttachment(null);
    if (fileRef.current) fileRef.current.value = '';
  };

  const handleReply = async () => {
    const text = input.trim();
    if ((!text && !attachment) || sending || !activeId) return;
    setSending(true);
    try {
      const res = await fetch(
        `${API_BASE_URL}/api/support-chat/vendor/conversations/${activeId}/reply`,
        { method: 'POST', headers: hdrs(), body: JSON.stringify({ text, media: attachment || null }) },
      );
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal mengirim balasan');
      setMessages(m => [...m, data]);
      setInput('');
      clearAttachment();
      loadConvos();
    } catch (e) {
      toast.error(e.message);
    } finally {
      setSending(false);
    }
  };

  // Daftar agent diambil dari percakapan yang ada — otomatis sinkron, dan
  // agent tanpa percakapan tidak perlu muncul di filter.
  const agentOptions = Array.from(
    new Map(convos.filter(c => c.agent_id)
                  .map(c => [c.agent_id, c.agent_name || 'Tanpa nama'])).entries()
  ).sort((a, b) => a[1].localeCompare(b[1]));

  const filtered = convos.filter(c => {
    if (agentFilter && c.agent_id !== agentFilter) return false;
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    return (c.user_name || '').toLowerCase().includes(q)
        || (c.wilayah_label || '').toLowerCase().includes(q)
        || (c.agent_name || '').toLowerCase().includes(q);
  });

  const totalUnread = convos.reduce((n, c) => n + (c.unread || 0), 0);
  const unreadByAgent = (aid) =>
    convos.filter(c => c.agent_id === aid).reduce((n, c) => n + (c.unread || 0), 0);

  return (
    <div className="p-6 space-y-5 bg-[#f7f1de] min-h-full">
      {/* Header */}
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-green-600 flex items-center justify-center shadow">
            <Inbox size={20} className="text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900">
              Inbox Support
              {totalUnread > 0 && (
                <span className="ml-2 align-middle text-xs px-2 py-0.5 rounded-full bg-red-500 text-white">
                  {totalUnread} baru
                </span>
              )}
            </h1>
            <p className="text-sm text-gray-500">
              Balas chat dari RT/RW/Kelurahan — tiap wilayah punya thread sendiri, jadi balasan tidak mungkin salah sasaran
            </p>
          </div>
        </div>
        <button onClick={() => { loadConvos(); if (activeId) loadMessages(activeId); }}
          className="p-2 rounded-lg bg-white shadow-sm hover:bg-gray-100" title="Refresh">
          <RefreshCw size={16} className="text-gray-500" />
        </button>
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-16">
          <Loader2 size={28} className="animate-spin text-green-600" />
        </div>
      ) : convos.length === 0 ? (
        <div className="bg-white rounded-2xl shadow p-12 text-center">
          <Inbox size={48} className="mx-auto text-gray-300 mb-3" />
          <p className="text-gray-500 text-sm">Belum ada percakapan support masuk</p>
          <p className="text-gray-400 text-xs mt-1">
            Chat akan muncul di sini saat pengurus RT/RW/Kelurahan menghubungi lewat widget support
          </p>
        </div>
      ) : (
        <div className="bg-white rounded-2xl shadow overflow-hidden flex" style={{ height: '70vh' }}>
          {/* Daftar percakapan */}
          <div className="w-72 border-r border-gray-200 flex flex-col flex-shrink-0">
            <div className="p-2.5 border-b border-gray-200 space-y-2">
              <div className="relative">
                <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400" />
                <input value={search} onChange={e => setSearch(e.target.value)}
                  placeholder="Cari wilayah / nama..."
                  className="w-full pl-8 pr-3 py-1.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-green-500" />
              </div>
              <div className="relative">
                <Headset size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
                <select value={agentFilter} onChange={e => setAgentFilter(e.target.value)}
                  className="w-full pl-8 pr-3 py-1.5 border border-gray-200 rounded-lg text-sm bg-white focus:outline-none focus:ring-2 focus:ring-green-500">
                  <option value="">Semua Agent{totalUnread > 0 ? ` (${totalUnread} baru)` : ''}</option>
                  {agentOptions.map(([id, nama]) => {
                    const u = unreadByAgent(id);
                    return <option key={id} value={id}>{nama}{u > 0 ? ` (${u} baru)` : ''}</option>;
                  })}
                </select>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto divide-y divide-gray-100">
              {filtered.map(c => (
                <button key={c.id} onClick={() => { setActiveId(c.id); setInput(''); clearAttachment(); }}
                  className={`w-full text-left px-3 py-2.5 hover:bg-gray-50 transition-colors ${
                    activeId === c.id ? 'bg-green-50' : ''
                  }`}>
                  <div className="flex items-center gap-2.5">
                    <div className="w-9 h-9 rounded-full bg-green-100 text-green-700 flex items-center justify-center font-bold text-sm flex-shrink-0">
                      {initials(c.user_name)}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between gap-1">
                        <p className="text-sm font-semibold text-gray-800 truncate">{c.user_name || 'Pengurus'}</p>
                        <span className="text-[10px] text-gray-400 flex-shrink-0">{waktu(c.last_message_at)}</span>
                      </div>
                      {c.wilayah_label && (
                        <p className="text-[11px] text-gray-500 truncate flex items-center gap-1">
                          <MapPin size={9} className="flex-shrink-0" />{c.wilayah_label}
                        </p>
                      )}
                      {/* Nama agent tujuan — penting karena satu warga bisa
                          punya beberapa percakapan ke agent berbeda. */}
                      {c.agent_name && (
                        <span className="inline-flex items-center gap-1 mt-0.5 px-1.5 py-0.5 rounded bg-green-50 text-green-700 text-[10px] font-medium max-w-full">
                          <Headset size={9} className="flex-shrink-0" />
                          <span className="truncate">{c.agent_name}</span>
                        </span>
                      )}
                      <div className="flex items-center justify-between gap-1">
                        <p className="text-xs text-gray-400 truncate">{c.last_message || '—'}</p>
                        {c.unread > 0 && (
                          <span className="flex-shrink-0 min-w-[18px] h-[18px] px-1 rounded-full bg-red-500 text-white text-[10px] font-bold flex items-center justify-center">
                            {c.unread}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                </button>
              ))}
              {filtered.length === 0 && (
                <p className="text-xs text-gray-400 text-center py-6">Tidak ada yang cocok</p>
              )}
            </div>
          </div>

          {/* Ruang chat */}
          <div className="flex-1 flex flex-col min-w-0">
            {!activeId ? (
              <div className="flex-1 flex flex-col items-center justify-center text-center px-6">
                <Inbox size={40} className="text-gray-300 mb-2" />
                <p className="text-sm text-gray-500">Pilih percakapan di kiri untuk mulai membalas</p>
              </div>
            ) : (
              <>
                <div className="px-4 py-3 border-b border-gray-200 flex items-center gap-2.5 flex-shrink-0">
                  <div className="w-9 h-9 rounded-full bg-green-100 text-green-700 flex items-center justify-center font-bold text-sm">
                    {initials(active?.user_name)}
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-semibold text-gray-800 truncate">{active?.user_name || 'Pengurus'}</p>
                    {active?.wilayah_label && (
                      <p className="text-xs text-gray-500 truncate">{active.wilayah_label}</p>
                    )}
                  </div>
                  {active?.agent_name && (
                    <div className="flex-shrink-0 text-right">
                      <p className="text-[10px] text-gray-400 uppercase tracking-wide">Ditujukan ke</p>
                      <p className="text-xs font-semibold text-green-700 flex items-center gap-1 justify-end">
                        <Headset size={11} />{active.agent_name}
                      </p>
                      {active.agent_role_label && (
                        <p className="text-[10px] text-gray-400">{active.agent_role_label}</p>
                      )}
                    </div>
                  )}
                </div>

                <div className="flex-1 overflow-y-auto p-4 space-y-2 bg-gray-50">
                  {loadingChat && messages.length === 0 && (
                    <div className="flex justify-center py-6">
                      <Loader2 size={20} className="animate-spin text-green-500" />
                    </div>
                  )}
                  {messages.map(m => (
                    // direction "out" = pesan DARI pengurus wilayah (masuk ke agent),
                    // jadi di sisi panel agent tampil di KIRI.
                    <div key={m.id} className={`flex ${m.direction === 'in' ? 'justify-end' : 'justify-start'}`}>
                      <div className={`max-w-[70%] rounded-2xl px-3 py-2 text-sm ${
                        m.direction === 'in'
                          ? 'bg-green-600 text-white rounded-br-sm'
                          : 'bg-white text-gray-800 border border-gray-200 rounded-bl-sm'
                      }`}>
                        {m.media_url && (
                          (m.media_mimetype || '').startsWith('image/') ? (
                            <a href={`${API_BASE_URL}${m.media_url}`} target="_blank" rel="noopener noreferrer">
                              <img src={`${API_BASE_URL}${m.media_url}`} alt={m.media_filename || 'lampiran'}
                                className="rounded-lg mb-1 max-h-48 object-cover" />
                            </a>
                          ) : (
                            <a href={`${API_BASE_URL}${m.media_url}`} target="_blank" rel="noopener noreferrer"
                              className="flex items-center gap-1.5 underline mb-1 text-xs">
                              <Paperclip size={12} /> {m.media_filename || 'Lampiran'}
                            </a>
                          )
                        )}
                        {m.body && <p className="whitespace-pre-wrap break-words">{m.body}</p>}
                        <p className={`text-[10px] mt-0.5 text-right ${m.direction === 'in' ? 'text-green-100' : 'text-gray-400'}`}>
                          {waktu(m.created_at)}
                        </p>
                      </div>
                    </div>
                  ))}
                  <div ref={listEndRef} />
                </div>

                {attachment && (
                  <div className="px-3 py-2 bg-gray-50 border-t border-gray-200 flex items-center gap-2 text-xs flex-shrink-0">
                    <Paperclip size={13} className="text-gray-400 flex-shrink-0" />
                    <span className="flex-1 truncate text-gray-600">{attachment.filename}</span>
                    <button onClick={clearAttachment} className="text-gray-400 hover:text-red-500">
                      <X size={14} />
                    </button>
                  </div>
                )}

                <div className="p-3 border-t border-gray-200 flex items-end gap-2 flex-shrink-0">
                  <input ref={fileRef} type="file" className="hidden"
                    accept="image/*,application/pdf"
                    onChange={e => handleFile(e.target.files?.[0])} />
                  <button onClick={() => fileRef.current?.click()}
                    className="flex-shrink-0 w-10 h-10 rounded-full text-gray-400 hover:text-green-600 hover:bg-gray-100 flex items-center justify-center transition-colors"
                    title="Lampirkan gambar / PDF">
                    <Paperclip size={18} />
                  </button>
                  <textarea
                    rows={1}
                    value={input}
                    onChange={e => setInput(e.target.value)}
                    onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleReply(); } }}
                    placeholder="Ketik balasan..."
                    className="flex-1 resize-none max-h-28 text-sm border border-gray-200 rounded-2xl px-3 py-2 focus:outline-none focus:ring-2 focus:ring-green-500"
                  />
                  <button onClick={handleReply} disabled={sending || (!input.trim() && !attachment)}
                    className="flex-shrink-0 w-10 h-10 rounded-full bg-green-600 hover:bg-green-700 disabled:opacity-40 text-white flex items-center justify-center transition-colors">
                    {sending ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
