import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { API_BASE_URL } from '../../config/api';
import { Send, Bell, RefreshCw, Eye, Building2, MapPin, Users } from 'lucide-react';
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue
} from '@/components/ui/select';

const STATUS_COLORS = {
  draft: 'border-gray-400 text-gray-500 bg-[var(--rw-bg-card-alt)] dark:bg-gray-700',
  published: 'border-green-500 text-green-600 bg-green-50 dark:bg-green-900/20',
  archived: 'border-amber-400 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
};

const TIPE_COLORS = {
  info: 'border-blue-400 text-blue-600 bg-blue-50 dark:bg-blue-900/20',
  penting: 'border-amber-500 text-amber-600 bg-amber-50 dark:bg-amber-900/20',
  darurat: 'border-red-500 text-red-600 bg-red-50 dark:bg-red-900/20',
  kegiatan: 'border-purple-400 text-purple-600 bg-purple-50 dark:bg-purple-900/20',
};

const BroadcastKelurahan = () => {
  const { token } = useAuth();
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [viewItem, setViewItem] = useState(null);
  const [sending, setSending] = useState(false);
  const [rwOptions, setRwOptions] = useState([]);
  const [rtOptions, setRtOptions] = useState([]);
  const [form, setForm] = useState({
    judul: '', isi: '', tipe: 'info',
    targetType: 'all', targetId: '', level: 'Kelurahan', status: 'published'
  });

  useEffect(() => { fetchHistory(); fetchOptions(); }, [token]);

  const fetchHistory = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const res = await axios.get(`${API_BASE_URL}/api/kelurahan/broadcast`, { headers });
      setHistory(res.data?.data || []);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchOptions = async () => {
    try {
      const headers = { Authorization: `Bearer ${token}` };
      const res = await axios.get(`${API_BASE_URL}/api/kelurahan/regions`, { headers });
      const hierarchy = res.data?.hierarchy || [];
      setRwOptions(hierarchy.map(rw => ({ id: rw.id, name: rw.nama_rw })));
      setRtOptions(hierarchy.flatMap(rw =>
        (rw.rt_list || []).map(rt => ({ id: rt.id, name: rt.nama_rt, rw_name: rw.nama_rw }))
      ));
    } catch {
      // silently fail — options just won't show
    }
  };

  const handleSend = async () => {
    if (!form.judul || !form.isi) return;
    try {
      setSending(true);
      const headers = { Authorization: `Bearer ${token}` };
      let payload = { judul: form.judul, isi: form.isi, tipe: form.tipe, level: 'Kelurahan', status: 'published' };
      if (form.targetType === 'all') {
        payload = { ...payload, target: 'all' };
      } else if (form.targetType === 'all_rw') {
        payload = { ...payload, target: 'rw', target_rw_id: null };
      } else if (form.targetType === 'rw_specific') {
        payload = { ...payload, target: 'rw', target_rw_id: form.targetId };
      } else if (form.targetType === 'all_rt') {
        payload = { ...payload, target: 'rt', target_rt_blok: null };
      } else if (form.targetType === 'rt_specific') {
        payload = { ...payload, target: 'rt', target_rt_blok: form.targetId };
      }
      await axios.post(`${API_BASE_URL}/api/kelurahan/broadcast`, payload, { headers });
      setShowForm(false);
      setForm({ judul: '', isi: '', tipe: 'info', targetType: 'all', targetId: '', level: 'Kelurahan', status: 'published' });
      fetchHistory();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal mengirim broadcast');
    } finally {
      setSending(false);
    }
  };

  const formatDate = (d) => d
    ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' })
    : '-';

  const getTargetIcon = (target) => {
    if (target === 'all') return <Users className="h-3.5 w-3.5" />;
    if (target === 'rw') return <Building2 className="h-3.5 w-3.5" />;
    return <MapPin className="h-3.5 w-3.5" />;
  };

  const getTargetLabel = (target, targetRwId, targetRtBlok) => {
    if (target === 'all') return 'Seluruh Wilayah';
    if (target === 'rw' && !targetRwId) return 'Seluruh RW';
    if (target === 'rw' && targetRwId) {
      const rw = rwOptions.find(r => r.id === targetRwId);
      return `RW: ${rw?.name || 'Tertentu'}`;
    }
    if (target === 'rt' && !targetRtBlok) return 'Seluruh RT';
    if (target === 'rt' && targetRtBlok) {
      const rt = rtOptions.find(r => r.id === targetRtBlok);
      return `RT: ${rt?.name || 'Tertentu'}`;
    }
    return target;
  };

  if (loading) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat riwayat broadcast...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>Kelurahan</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Broadcast</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-xl flex items-center justify-center shadow">
            <Send className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Broadcast Kelurahan</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Kirim pengumuman ke seluruh RW / RT</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchHistory} className="flex items-center gap-2 px-3 py-2 text-sm bg-[var(--rw-bg-card)] dark:bg-gray-800 border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors">
            <RefreshCw className="h-4 w-4" />
          </button>
          <button
            onClick={() => setShowForm(true)}
            className="flex items-center gap-2 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white text-sm rounded-lg transition-colors"
          >
            <Send className="h-4 w-4" />Kirim Broadcast
          </button>
        </div>
      </div>

      {/* Target Options Info */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {[
          { icon: Users, label: 'Seluruh Wilayah', desc: 'Broadcast ke semua RW dan RT dalam kelurahan', color: 'from-emerald-500 to-teal-600' },
          { icon: Building2, label: 'RW Tertentu', desc: 'Broadcast ke RW yang dipilih beserta RT-nya', color: 'from-blue-500 to-indigo-600' },
          { icon: MapPin, label: 'RT Tertentu', desc: 'Broadcast ke blok/RT yang spesifik', color: 'from-purple-500 to-violet-600' },
        ].map((opt, i) => (
          <div key={i} className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow p-4 flex items-start gap-3">
            <div className={`w-10 h-10 bg-gradient-to-br ${opt.color} rounded-lg flex items-center justify-center flex-shrink-0`}>
              <opt.icon className="h-5 w-5 text-white" />
            </div>
            <div>
              <p className="font-medium text-gray-900 dark:text-white text-sm">{opt.label}</p>
              <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">{opt.desc}</p>
            </div>
          </div>
        ))}
      </div>

      {/* History Table */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        <div className="p-4 border-b border-[var(--rw-border)] dark:border-gray-700 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Bell className="h-5 w-5 text-emerald-500" />
            <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">
              Riwayat Broadcast ({history.length})
            </h3>
          </div>
        </div>
        {history.length > 0 ? (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Judul</TableHead>
                <TableHead>Tipe</TableHead>
                <TableHead>Target</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Dikirim Oleh</TableHead>
                <TableHead>Tanggal</TableHead>
                <TableHead className="text-center">Detail</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {history.map((b) => (
                <TableRow key={b.id}>
                  <TableCell className="font-medium text-gray-900 dark:text-white max-w-[200px]">
                    <span className="truncate block">{b.judul}</span>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={TIPE_COLORS[b.tipe] || ''}>{b.tipe}</Badge>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-1 text-sm text-gray-600 dark:text-gray-400">
                      {getTargetIcon(b.target)}
                      <span>{getTargetLabel(b.target, b.target_rw_id, b.target_rt_blok)}</span>
                    </div>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={STATUS_COLORS[b.status] || ''}>{b.status}</Badge>
                  </TableCell>
                  <TableCell className="text-sm text-gray-500 dark:text-gray-400">{b.creator_name || '-'}</TableCell>
                  <TableCell className="text-sm text-gray-500 dark:text-gray-400">{formatDate(b.published_at || b.created_at)}</TableCell>
                  <TableCell className="text-center">
                    <button onClick={() => setViewItem(b)} className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded">
                      <Eye className="h-3.5 w-3.5" />
                    </button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="text-center py-12">
            <Send className="h-12 w-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
            <p className="text-gray-500 dark:text-gray-400">Belum ada riwayat broadcast</p>
            <button
              onClick={() => setShowForm(true)}
              className="mt-4 inline-flex items-center gap-2 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white text-sm rounded-lg transition-colors"
            >
              <Send className="h-4 w-4" />Kirim Broadcast Pertama
            </button>
          </div>
        )}
      </div>

      {/* Compose Dialog */}
      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Send className="h-5 w-5 text-emerald-500" />
              Kirim Broadcast Kelurahan
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div>
              <Label>Judul Broadcast <span className="text-red-500">*</span></Label>
              <Input
                className="mt-1"
                placeholder="Judul pengumuman..."
                value={form.judul}
                onChange={e => setForm(f => ({ ...f, judul: e.target.value }))}
              />
            </div>
            <div>
              <Label>Isi Pesan <span className="text-red-500">*</span></Label>
              <Textarea
                className="mt-1"
                rows={5}
                placeholder="Tulis isi broadcast di sini..."
                value={form.isi}
                onChange={e => setForm(f => ({ ...f, isi: e.target.value }))}
              />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Tipe</Label>
                <Select value={form.tipe} onValueChange={v => setForm(f => ({ ...f, tipe: v }))}>
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="info">Info</SelectItem>
                    <SelectItem value="penting">Penting</SelectItem>
                    <SelectItem value="darurat">Darurat</SelectItem>
                    <SelectItem value="kegiatan">Kegiatan</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Target Penerima</Label>
                <Select
                  value={form.targetType}
                  onValueChange={v => setForm(f => ({ ...f, targetType: v, targetId: '' }))}
                >
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">Seluruh Wilayah</SelectItem>
                    <SelectItem value="all_rw">Seluruh RW</SelectItem>
                    <SelectItem value="rw_specific">RW Tertentu</SelectItem>
                    <SelectItem value="all_rt">Seluruh RT</SelectItem>
                    <SelectItem value="rt_specific">RT Tertentu</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            {form.targetType === 'rw_specific' && (
              <div>
                <Label>Pilih RW <span className="text-red-500">*</span></Label>
                <Select
                  value={form.targetId}
                  onValueChange={v => setForm(f => ({ ...f, targetId: v }))}
                >
                  <SelectTrigger className="mt-1">
                    <SelectValue placeholder="Pilih RW tujuan..." />
                  </SelectTrigger>
                  <SelectContent>
                    {rwOptions.map(rw => (
                      <SelectItem key={rw.id} value={rw.id}>{rw.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            {form.targetType === 'rt_specific' && (
              <div>
                <Label>Pilih RT <span className="text-red-500">*</span></Label>
                <Select
                  value={form.targetId}
                  onValueChange={v => setForm(f => ({ ...f, targetId: v }))}
                >
                  <SelectTrigger className="mt-1">
                    <SelectValue placeholder="Pilih RT tujuan..." />
                  </SelectTrigger>
                  <SelectContent>
                    {rtOptions.map(rt => (
                      <SelectItem key={rt.id} value={rt.id}>
                        {rt.name} <span className="text-gray-400 text-xs">({rt.rw_name})</span>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            <div className="bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg p-3 text-sm text-amber-700 dark:text-amber-300">
              Broadcast akan langsung dipublish dan dapat dilihat oleh seluruh target penerima.
            </div>
          </div>
          <DialogFooter>
            <button
              onClick={() => setShowForm(false)}
              className="px-4 py-2 text-sm border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-800"
            >
              Batal
            </button>
            <button
              onClick={handleSend}
              disabled={sending || !form.judul || !form.isi || (['rw_specific', 'rt_specific'].includes(form.targetType) && !form.targetId)}
              className="flex items-center gap-2 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white text-sm rounded-lg disabled:opacity-50"
            >
              <Send className="h-4 w-4" />
              {sending ? 'Mengirim...' : 'Kirim Sekarang'}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={!!viewItem} onOpenChange={() => setViewItem(null)}>
        <DialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Bell className="h-5 w-5 text-emerald-500" />
              {viewItem?.judul}
            </DialogTitle>
          </DialogHeader>
          {viewItem && (
            <div className="space-y-3 text-sm">
              <div className="flex gap-2 flex-wrap">
                <Badge variant="outline" className={STATUS_COLORS[viewItem.status] || ''}>{viewItem.status}</Badge>
                <Badge variant="outline" className={TIPE_COLORS[viewItem.tipe] || ''}>{viewItem.tipe}</Badge>
                <Badge variant="outline">{getTargetLabel(viewItem.target, viewItem.target_rw_id, viewItem.target_rt_blok)}</Badge>
              </div>
              <div className="text-gray-500 dark:text-gray-400 text-xs">
                Dikirim: {formatDate(viewItem.published_at || viewItem.created_at)} · Oleh: {viewItem.creator_name || '-'}
              </div>
              <div className="bg-[var(--rw-bg-card-alt)] dark:bg-gray-800 rounded-lg p-4 text-gray-700 dark:text-gray-300 whitespace-pre-wrap">
                {viewItem.isi}
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default BroadcastKelurahan;
