import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '@/contexts/AuthContext';
import { API_BASE_URL } from '@/config/api';
import {
  User, Home, CreditCard, ArrowLeft, MapPin, Phone
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';

const BANTUAN_COLORS = {
  KIS:      'bg-blue-100 text-blue-700',
  PIP:      'bg-purple-100 text-purple-700',
  BLT:      'bg-green-100 text-green-700',
  BNPT:     'bg-orange-100 text-orange-700',
  RUTILAHU: 'bg-red-100 text-red-700',
};

const Field = ({ label, value, children }) => (
  <div>
    <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-1">
      {label}
    </p>
    {children || (
      <p className="text-sm font-medium text-gray-900 dark:text-gray-100">
        {value || <span className="text-gray-400">-</span>}
      </p>
    )}
  </div>
);

const WargaDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { token, user } = useAuth();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchDetail = async () => {
      try {
        setLoading(true);
        const res = await axios.get(`${API_BASE_URL}/api/warga/${id}/detail`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        setData(res.data);
      } catch (err) {
        setError(err.response?.data?.detail || err.message);
      } finally {
        setLoading(false);
      }
    };
    if (token && id) fetchDetail();
  }, [token, id]);

  const formatDate = (val) => {
    if (!val) return '-';
    return new Date(val).toLocaleDateString('id-ID', {
      day: '2-digit', month: 'long', year: 'numeric',
    });
  };

  if (loading) {
    return (
      <div className="p-6 bg-[var(--rw-bg-card)] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat data...</p>
        </div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="p-6 bg-[var(--rw-bg-card)] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <p className="text-red-600 text-sm">Error: {error || 'Data tidak ditemukan'}</p>
        </div>
      </div>
    );
  }

  const { warga, rumah, kartu_keluarga: kk, kartu_keluarga_list: kkList = [], is_own_profile } = data;

  // KK tampil: admin selalu bisa lihat, warga hanya jika backend konfirmasi profil sendiri
  const showKK = user?.role !== 'warga' || is_own_profile === true;

  return (
    <div className="p-6 space-y-6 bg-[var(--rw-bg-card)] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <button
          onClick={() => navigate('/warga')}
          className="hover:text-gray-700 dark:hover:text-gray-200 transition-colors"
        >
          Daftar Warga
        </button>
        <span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">{warga.nama_lengkap}</span>
      </div>

      {/* Back + Header */}
      <div className="flex items-center gap-4">
        <button
          onClick={() => navigate('/warga')}
          className="p-2 rounded-lg bg-white dark:bg-gray-800 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors shadow-sm"
        >
          <ArrowLeft className="h-5 w-5 text-gray-600 dark:text-gray-400" />
        </button>
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center shadow">
            <User className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">{warga.nama_lengkap}</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Detail Warga</p>
          </div>
        </div>
      </div>

      {/* ── DATA WARGA ── */}
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow p-6 space-y-4">
        <div className="flex items-center gap-2 mb-2">
          <User className="h-5 w-5 text-indigo-500" />
          <h2 className="text-base font-semibold text-gray-900 dark:text-white">Informasi Warga</h2>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-5">
          <Field label="Nama Lengkap" value={warga.nama_lengkap} />
          <Field label="Jenis Kelamin" value={warga.jenis_kelamin} />
          <Field label="Agama" value={warga.agama} />
          <Field label="Tempat Lahir" value={warga.tempat_lahir} />
          <Field label="Tanggal Lahir" value={formatDate(warga.tanggal_lahir)} />
          <Field label="Pekerjaan" value={warga.pekerjaan} />
          <Field label="Posisi Keluarga" value={warga.posisi_keluarga} />
          <Field label="No WhatsApp">
            {warga.whatsapp
              ? <p className="text-sm font-medium text-gray-900 dark:text-gray-100 flex items-center gap-1">
                  <Phone className="h-3.5 w-3.5 text-green-500" />
                  {warga.country_code}{warga.whatsapp}
                </p>
              : <span className="text-gray-400 text-sm">-</span>
            }
          </Field>
          <Field label="Blok / No Rumah">
            {warga.blok_rumah
              ? <p className="text-sm font-medium text-gray-900 dark:text-gray-100 flex items-center gap-1">
                  <MapPin className="h-3.5 w-3.5 text-blue-500" />
                  {warga.blok_rumah}
                </p>
              : <span className="text-gray-400 text-sm">-</span>
            }
          </Field>
          <Field label="Status">
            <Badge
              variant="outline"
              className={warga.status === 'active'
                ? 'border-green-500 text-green-600 bg-green-50'
                : 'border-gray-400 text-gray-500 bg-gray-50'
              }
            >
              {warga.status_detail || (warga.status === 'active' ? 'Aktif' : 'Tidak Aktif')}
            </Badge>
          </Field>
          {['Pindah', 'Meninggal'].includes(warga.status_detail) && (
            <Field
              label={`Tanggal ${warga.status_detail === 'Pindah' ? 'Pindah' : 'Meninggal'}`}
              value={warga.status_changed_at ? formatDate(warga.status_changed_at) : '-'}
            />
          )}
          <Field label="Strata Ekonomi">
            {warga.strata_ekonomi
              ? <span className={`inline-flex px-2 py-1 rounded-full text-xs font-semibold ${
                  warga.strata_ekonomi === 'Mampu'
                    ? 'bg-green-100 text-green-700'
                    : 'bg-orange-100 text-orange-700'
                }`}>
                  {warga.strata_ekonomi}
                </span>
              : <span className="text-gray-400 text-sm">-</span>
            }
          </Field>
          <Field label="Bantuan Diterima">
            {Array.isArray(warga.bantuan_diterima) && warga.bantuan_diterima.length > 0
              ? <div className="flex flex-wrap gap-1">
                  {warga.bantuan_diterima.map(b => (
                    <span key={b} className={`px-2 py-0.5 rounded text-xs font-semibold ${BANTUAN_COLORS[b] || 'bg-gray-100 text-gray-700'}`}>
                      {b}
                    </span>
                  ))}
                </div>
              : <span className="text-gray-400 text-sm">-</span>
            }
          </Field>
          <div className="col-span-2 md:col-span-3">
            <Field label="Keterangan">
              <p className="text-sm font-medium text-gray-900 dark:text-gray-100 whitespace-pre-line">
                {warga.keterangan || <span className="text-gray-400">-</span>}
              </p>
            </Field>
          </div>
        </div>
      </div>

      {/* ── DATA RUMAH ── */}
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow p-6">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <Home className="h-5 w-5 text-blue-500" />
            <h2 className="text-base font-semibold text-gray-900 dark:text-white">Data Rumah</h2>
          </div>
          {rumah && (
            <button
              onClick={() => navigate('/rumah')}
              className="text-xs text-[var(--rw-primary)] hover:text-[var(--rw-primary-hover)] font-medium transition-colors"
            >
              Lihat Daftar Rumah →
            </button>
          )}
        </div>
        {rumah ? (
          <div className="grid grid-cols-2 md:grid-cols-3 gap-5">
            <Field label="Blok / No Rumah" value={rumah.blok_no} />
            <Field label="Nama Jalan" value={rumah.nama_jalan} />
            <Field label="Pemilik Sah" value={rumah.pemilik_sah} />
            <Field label="Jenis Bangunan" value={rumah.jenis_pemilik} />
            <Field label="Status Hunian" value={rumah.status_penghuni} />
            <Field label="Status">
              <div className="flex gap-2">
                <Badge variant="outline" className={rumah.aktif ? 'border-green-500 text-green-600 bg-green-50' : 'border-gray-400 text-gray-500 bg-gray-50'}>
                  {rumah.aktif ? 'Aktif' : 'Tidak Aktif'}
                </Badge>
                {rumah.sedang_kosong && (
                  <Badge variant="outline" className="border-yellow-500 text-yellow-600 bg-yellow-50">Kosong</Badge>
                )}
              </div>
            </Field>
            {rumah.remark && (
              <div className="col-span-2 md:col-span-3">
                <Field label="Catatan" value={rumah.remark} />
              </div>
            )}
          </div>
        ) : (
          <div className="text-center py-8 text-gray-400">
            <Home className="h-10 w-10 mx-auto mb-2 opacity-40" />
            <p className="text-sm">Belum ada data rumah yang terhubung ke warga ini</p>
          </div>
        )}
      </div>

      {/* ── KARTU KELUARGA — tampil hanya untuk profil sendiri (warga) atau semua (admin) ── */}
      {showKK && <div className="bg-white dark:bg-gray-800 rounded-xl shadow p-6">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <CreditCard className="h-5 w-5 text-emerald-500" />
            <h2 className="text-base font-semibold text-gray-900 dark:text-white">
              Kartu Keluarga
              {kkList.length > 1 && (
                <span className="ml-2 text-xs font-normal text-gray-400">({kkList.length} KK ditemukan)</span>
              )}
            </h2>
          </div>
          {kkList.length > 0 && (
            <button
              onClick={() => navigate('/kartu-keluarga')}
              className="text-xs text-[var(--rw-primary)] hover:text-[var(--rw-primary-hover)] font-medium transition-colors"
            >
              Lihat Daftar KK →
            </button>
          )}
        </div>
        {kkList.length > 0 ? (
          <div className="space-y-4">
            {kkList.map((k, idx) => (
              <div key={k.id} className={`grid grid-cols-2 md:grid-cols-3 gap-5 ${idx > 0 ? 'pt-4 border-t border-gray-100 dark:border-gray-700' : ''}`}>
                <Field label="Nomor KK">
                  <p className="text-sm font-mono font-semibold text-gray-900 dark:text-gray-100">{k.nomor_kk}</p>
                </Field>
                <Field label="Provinsi" value={k.provinsi} />
                <Field label="Kabupaten / Kota" value={k.kabupaten} />
                <Field label="Kecamatan" value={k.kecamatan} />
                <Field label="Kelurahan / Desa" value={k.kelurahan} />
                <Field label="Nama Desa" value={k.nama_desa} />
                <Field label="Nomor RT" value={k.nomor_rt ? `RT ${k.nomor_rt}` : null} />
                <Field label="Nomor RW" value={k.nomor_rw ? `RW ${k.nomor_rw}` : null} />
                <Field label="Status KK">
                  <Badge variant="outline" className={k.aktif ? 'border-green-500 text-green-600 bg-green-50' : 'border-gray-400 text-gray-500 bg-gray-50'}>
                    {k.aktif ? 'Aktif' : 'Tidak Aktif'}
                  </Badge>
                </Field>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-8 text-gray-400">
            <CreditCard className="h-10 w-10 mx-auto mb-2 opacity-40" />
            <p className="text-sm">
              {rumah ? 'Belum ada Kartu Keluarga yang terhubung ke rumah ini' : 'Data KK tidak tersedia (rumah belum terhubung)'}
            </p>
          </div>
        )}
      </div>}
    </div>
  );
};

export default WargaDetail;
