import { useState, useEffect } from 'react';
import { API_BASE_URL } from '@/config/api';

// Cache sederhana di level modul supaya Sidebar & Header tidak fetch dobel
// setiap kali komponennya di-mount ulang, selama token belum berubah.
let cachedToken = null;
let cachedProfile = null;
let pendingRequest = null;

/**
 * Ambil profil tenant milik user yang sedang login, termasuk label gabungan
 * wilayah (mis. "RT 01 / RW 07 / Kelurahan Kebonjati") dari endpoint
 * GET /api/tenant/my-profile.
 */
export function useTenantProfile(token) {
  const [profile, setProfile] = useState(cachedToken === token ? cachedProfile : null);

  useEffect(() => {
    if (!token) return;

    if (cachedToken === token && cachedProfile) {
      setProfile(cachedProfile);
      return;
    }

    if (!pendingRequest) {
      pendingRequest = fetch(`${API_BASE_URL}/api/tenant/my-profile`, {
        headers: { Authorization: `Bearer ${token}` },
      })
        .then((res) => (res.ok ? res.json() : null))
        .catch((err) => {
          console.error('Failed to load tenant profile:', err);
          return null;
        })
        .finally(() => {
          pendingRequest = null;
        });
    }

    pendingRequest.then((data) => {
      if (data) {
        cachedToken = token;
        cachedProfile = data;
        setProfile(data);
      }
    });
  }, [token]);

  return profile; // { name, address, city, tenant_type, parent_name, grandparent_name, label }
}
