import React, { createContext, useContext, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { API_BASE_URL } from '@/config/api';

const DEFAULT_COLORS = {
  bg_page: '#efe7d2',
  bg_card: '#f7f1de',
  bg_card_alt: '#ece4cf',
  border: '#d5cebc',
  primary: '#ed6f5c',
  primary_hover: '#e05544',
  text_accent: '#ed6f5c',
};

// Variabel shadcn/Tailwind (di index.css) yang ikut ditimpa berdasarkan tema
// aktif — INI PENTING karena banyak komponen (Card, Button varian dark, ring
// fokus, dsb) pakai class semantik seperti bg-card/bg-background/bg-primary,
// BUKAN bg-[var(--rw-...)] langsung. Tanpa ini, komponen seperti StatCard
// (yang pakai <Card className="bg-card">) tetap krem meski tema sudah diganti.
const SHADCN_VAR_MAP = {
  '--background': 'bg_page',
  '--card': 'bg_card',
  '--popover': 'bg_card',
  '--primary': 'primary',
  '--border': 'border',
  '--input': 'border',
  '--ring': 'primary',
  '--secondary': 'bg_card_alt',
  '--accent': 'bg_card_alt',
};

const ColorThemeContext = createContext({ colors: DEFAULT_COLORS, loading: true });

// Cache warna tema terakhir yang berhasil di-fetch dari vendor, supaya saat
// halaman di-refresh, browser bisa langsung pakai warna vendor yang BENAR
// (bukan warna default hardcoded) sebelum fetch /api/app/theme selesai.
// Tanpa ini, setiap refresh selalu ada jeda singkat pakai DEFAULT_COLORS dulu
// (krem bawaan) meskipun vendor sudah custom ke warna lain — baru berubah
// ke warna vendor setelah fetch selesai, jadi kelihatan "kedip" salah warna.
const THEME_CACHE_KEY = 'rw_theme_colors_cache';

function readCachedColors() {
  try {
    const raw = localStorage.getItem(THEME_CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    // Validasi minimal: harus punya semua key yang dipakai UI
    return parsed && parsed.bg_page ? parsed : null;
  } catch {
    return null;
  }
}

function writeCachedColors(colors) {
  try {
    localStorage.setItem(THEME_CACHE_KEY, JSON.stringify(colors));
  } catch {
    // localStorage penuh/diblokir (mode private, dsb) — abaikan, tidak fatal
  }
}

function hexToHslTriplet(hex) {
  const clean = (hex || '').replace('#', '');
  const full = clean.length === 3 ? clean.split('').map((c) => c + c).join('') : clean;
  const r = parseInt(full.substring(0, 2), 16) / 255;
  const g = parseInt(full.substring(2, 4), 16) / 255;
  const b = parseInt(full.substring(4, 6), 16) / 255;
  if ([r, g, b].some(Number.isNaN)) return '0 0% 100%';

  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let h = 0, s = 0;
  const l = (max + min) / 2;
  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      default: h = (r - g) / d + 4; break;
    }
    h /= 6;
  }
  return `${Math.round(h * 360)} ${Math.round(s * 100)}% ${Math.round(l * 100)}%`;
}

// CSS variable dengan prefix "rw" (Ruang Warga) supaya tidak bentrok dengan
// variable lain. Dikonsumsi lewat class Tailwind arbitrary value, mis.
// bg-[var(--rw-primary)] atau lewat inline style.
function applyRwVars(colors) {
  const root = document.documentElement;
  root.style.setProperty('--rw-bg-page', colors.bg_page);
  root.style.setProperty('--rw-bg-card', colors.bg_card);
  root.style.setProperty('--rw-bg-card-alt', colors.bg_card_alt);
  root.style.setProperty('--rw-border', colors.border);
  root.style.setProperty('--rw-primary', colors.primary);
  root.style.setProperty('--rw-primary-hover', colors.primary_hover);
  root.style.setProperty('--rw-text-accent', colors.text_accent);
}

// Timpa variabel shadcn HANYA saat mode terang aktif. Saat mode gelap (class
// "dark" di <html>) override ini dilepas lagi supaya palet gelap bawaan yang
// berlaku (bukan warna tema terang yang salah konteks).
function applyShadcnVars(colors) {
  const root = document.documentElement;
  if (root.classList.contains('dark')) return;
  Object.entries(SHADCN_VAR_MAP).forEach(([cssVar, colorKey]) => {
    root.style.setProperty(cssVar, hexToHslTriplet(colors[colorKey]));
  });
}

function clearShadcnVarOverrides() {
  const root = document.documentElement;
  Object.keys(SHADCN_VAR_MAP).forEach((cssVar) => root.style.removeProperty(cssVar));
}

export function ColorThemeProvider({ children }) {
  // Mulai dari cache tema vendor (kalau ada) — bukan selalu dari
  // DEFAULT_COLORS — supaya render pertama sudah pakai warna vendor yang
  // benar, bukan warna default yang nanti "kedip" berubah setelah fetch.
  const [colors, setColors] = useState(() => readCachedColors() || DEFAULT_COLORS);
  const [loading, setLoading] = useState(true);
  const colorsRef = useRef(colors);
  colorsRef.current = colors;

  const applyAll = (c) => {
    applyRwVars(c);
    applyShadcnVars(c);
  };

  // Terapkan warna (cache vendor kalau ada, atau default) SEBELUM browser
  // sempat paint pertama kali — useLayoutEffect jalan sinkron sebelum paint,
  // beda dengan useEffect yang jalan setelah paint (itu penyebab kedipnya).
  useLayoutEffect(() => {
    applyAll(colors);
  }, []);

  const load = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/app/theme`, { cache: 'no-store' });
      if (!res.ok) {
        console.warn(`[ColorTheme] GET /api/app/theme -> HTTP ${res.status}. Memakai tema default sebagai fallback.`);
        applyAll(DEFAULT_COLORS);
        return;
      }
      const data = await res.json();
      if (data?.colors) {
        setColors(data.colors);
        applyAll(data.colors);
        writeCachedColors(data.colors);
      } else {
        console.warn('[ColorTheme] Respons /api/app/theme tidak berisi field "colors". Memakai tema default.', data);
        applyAll(DEFAULT_COLORS);
      }
    } catch (err) {
      // Gagal ambil tema (mis. offline, backend belum di-deploy dengan endpoint
      // ini, atau migrasi kolom tema belum dijalankan) — pakai default supaya
      // tampilan tetap jalan, tapi log ke console supaya gampang di-debug.
      console.warn('[ColorTheme] Gagal fetch /api/app/theme, memakai tema default:', err);
      applyAll(DEFAULT_COLORS);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  // Pantau toggle dark/light (dikendalikan ThemeContext.jsx yang sudah ada)
  // supaya override shadcn otomatis dilepas/dipasang lagi sesuai mode.
  useEffect(() => {
    const observer = new MutationObserver(() => {
      if (document.documentElement.classList.contains('dark')) {
        clearShadcnVarOverrides();
      } else {
        applyShadcnVars(colorsRef.current);
      }
    });
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
    return () => observer.disconnect();
  }, []);

  return (
    <ColorThemeContext.Provider value={{ colors, loading, reload: load }}>
      {children}
    </ColorThemeContext.Provider>
  );
}

export function useColorTheme() {
  return useContext(ColorThemeContext);
}
