import { useEffect, useState } from "react";
import { API_BASE_URL } from "@/config/api";
import { useAuth } from "@/contexts/AuthContext";
import { Users, RefreshCw, CheckCircle2, XCircle, Building2, X, Save } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { toast } from "@/components/ui/sonner";

// Roles yang tidak boleh dibuat oleh Kelurahan
const FORBIDDEN = new Set(["admin", "pengurus_kelurahan", "pengurus_rt", "warga", "karyawan", "staff", "vendor"]);

const ROLE_LABEL = {
  pengurus_rw:        "Pengurus RW",
  pengurus_kelurahan: "Lurah / Pengurus Kelurahan",
};

function roleLabel(r) {
  return ROLE_LABEL[r] || (r.charAt(0).toUpperCase() + r.slice(1).replace(/_/g, " "));
}

// ── Form Modal ────────────────────────────────────────────────────────────────
function UserModal({ open, onClose, editUser, rwList, kelTenantId, authHeader, onSaved }) {
  const [roles,   setRoles]   = useState([]);
  const [saving,  setSaving]  = useState(false);
  const [form, setForm] = useState({
    fullname: "", username: "", whatsapp: "", password: "",
    role: "pengurus_rw", tenant_id: "", status: "active",
  });

  // Set default tenant_id when role changes
  useEffect(() => {
    if (form.role === "pengurus_rw") {
      setForm(f => ({ ...f, tenant_id: rwList[0]?.id || "" }));
    } else {
      setForm(f => ({ ...f, tenant_id: kelTenantId || "" }));
    }
  }, [form.role, rwList, kelTenantId]);

  // Load available roles
  useEffect(() => {
    if (!open) return;
    fetch(`${API_BASE_URL}/api/roles`, { headers: authHeader })
      .then(r => r.ok ? r.json() : [])
      .then(data => {
        const names = data.map(r => r.name || r).filter(r => !FORBIDDEN.has(r));
        // Sort: pengurus_rw first, then custom alphabetical
        const sorted = [
          ...["pengurus_rw"].filter(r => names.includes(r)),
          ...names.filter(r => r !== "pengurus_rw").sort((a, b) => a.localeCompare(b)),
        ];
        setRoles(sorted);
      })
      .catch(() => setRoles(["pengurus_rw"]));
  }, [open]);

  // Load edit data
  useEffect(() => {
    if (editUser) {
      setForm({
        fullname:  editUser.fullname  || "",
        username:  editUser.username  || "",
        whatsapp:  editUser.whatsapp  || "",
        password:  "",
        role:      editUser.role      || "pengurus_rw",
        tenant_id: editUser.tenant_id || "",
        status:    editUser.status    || "active",
      });
    } else {
      setForm({
        fullname: "", username: "", whatsapp: "", password: "",
        role: "pengurus_rw", tenant_id: rwList[0]?.id || kelTenantId || "",
        status: "active",
      });
    }
  }, [editUser, open, rwList, kelTenantId]);

  const save = async () => {
    if (!form.fullname.trim() || form.fullname.trim().length < 3) { toast.error("Nama lengkap minimal 3 karakter"); return; }
    if (!editUser && !form.whatsapp) { toast.error("Nomor WhatsApp harus diisi"); return; }
    if (!editUser && form.whatsapp.length < 10) { toast.error("Nomor WhatsApp minimal 10 digit"); return; }
    setSaving(true);
    const url    = editUser ? `${API_BASE_URL}/api/users/${editUser.id}` : `${API_BASE_URL}/api/users`;
    const method = editUser ? "PUT" : "POST";
    const payload = editUser
      ? { fullname: form.fullname, username: form.username, role: form.role, status: form.status, ...(form.password ? { password: form.password } : {}) }
      : { fullname: form.fullname, username: form.username, whatsapp: form.whatsapp, role: form.role, status: form.status, tenant_id: form.tenant_id };
    try {
      const res = await fetch(url, {
        method, headers: { ...authHeader, "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      if (!res.ok) {
        const d = await res.json().catch(() => ({}));
        toast.error(d.detail || "Gagal menyimpan");
        setSaving(false); return;
      }
      toast.success(editUser ? "User diperbarui" : "User baru ditambahkan");
      onSaved(); onClose();
    } catch { toast.success(editUser ? "User diperbarui" : "User baru ditambahkan"); onSaved(); onClose(); }
    setSaving(false);
  };

  const isPengRw = form.role === "pengurus_rw";

  return (
    <Dialog open={open} onOpenChange={v => !v && onClose()}>
      <DialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 dark:text-gray-100 max-w-md">
        <DialogHeader>
          <DialogTitle>{editUser ? "Edit Pengguna" : "Tambah Pengguna"}</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          {/* Nama */}
          <div className="space-y-1.5">
            <Label>Nama Lengkap <span className="text-red-500">*</span></Label>
            <Input value={form.fullname} onChange={e => setForm(f => ({ ...f, fullname: e.target.value }))}
              placeholder="Nama lengkap" className="dark:bg-gray-800 dark:text-gray-100" />
          </div>

          {/* Email/Username */}
          <div className="space-y-1.5">
            <Label>Email / Username <span className="text-red-500">*</span></Label>
            <Input value={form.username} onChange={e => setForm(f => ({ ...f, username: e.target.value }))}
              placeholder="Email atau username" className="dark:bg-gray-800 dark:text-gray-100" />
          </div>

          {/* WhatsApp — hanya saat tambah */}
          {!editUser && (
            <div className="space-y-1.5">
              <Label>Nomor WhatsApp <span className="text-red-500">*</span></Label>
              <Input value={form.whatsapp}
                onChange={e => setForm(f => ({ ...f, whatsapp: e.target.value.replace(/\D/g, "") }))}
                placeholder="Contoh: 08123456789" maxLength={15}
                className="dark:bg-gray-800 dark:text-gray-100" />
              <p className="text-xs text-gray-400">Password default = nomor WhatsApp</p>
            </div>
          )}

          {/* Role */}
          <div className="space-y-1.5">
            <Label>Role <span className="text-red-500">*</span></Label>
            <select value={form.role} onChange={e => setForm(f => ({ ...f, role: e.target.value }))}
              className="w-full p-2 rounded-md border border-gray-300 dark:border-gray-700 bg-[var(--rw-bg-card)] dark:bg-gray-800 text-gray-900 dark:text-gray-100 text-sm">
              {roles.map(r => <option key={r} value={r}>{roleLabel(r)}</option>)}
            </select>
            <p className="text-xs text-gray-400">
              {isPengRw ? "Akan ditugaskan ke RW yang dipilih" : "Akan ditugaskan ke Kelurahan"}
            </p>
          </div>

          {/* Wilayah RW — hanya untuk pengurus_rw dan saat tambah user */}
          {isPengRw && !editUser && (
            <div className="space-y-1.5">
              <Label>RW <span className="text-red-500">*</span></Label>
              <select value={form.tenant_id} onChange={e => setForm(f => ({ ...f, tenant_id: e.target.value }))}
                className="w-full p-2 rounded-md border border-gray-300 dark:border-gray-700 bg-[var(--rw-bg-card)] dark:bg-gray-800 text-gray-900 dark:text-gray-100 text-sm">
                <option value="">-- Pilih RW --</option>
                {rwList.map(rw => (
                  <option key={rw.id} value={rw.id}>{rw.name || rw.nama || `RW ${rw.no_rw || rw.id.slice(0, 6)}`}</option>
                ))}
              </select>
            </div>
          )}

          {/* Status */}
          <div className="space-y-1.5">
            <Label>Status</Label>
            <select value={form.status} onChange={e => setForm(f => ({ ...f, status: e.target.value }))}
              className="w-full p-2 rounded-md border border-gray-300 dark:border-gray-700 bg-[var(--rw-bg-card)] dark:bg-gray-800 text-gray-900 dark:text-gray-100 text-sm">
              <option value="active">Aktif</option>
              <option value="inactive">Tidak Aktif</option>
            </select>
          </div>

          {/* Password — opsional saat edit */}
          {editUser && (
            <div className="space-y-1.5">
              <Label>Password Baru <span className="text-gray-400 text-xs font-normal">(kosongkan jika tidak diubah)</span></Label>
              <Input type="password" value={form.password}
                onChange={e => setForm(f => ({ ...f, password: e.target.value }))}
                placeholder="Password baru" className="dark:bg-gray-800 dark:text-gray-100" />
            </div>
          )}

          <Button onClick={save} disabled={saving} className="w-full bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white">
            {saving ? "Menyimpan..." : <><Save className="h-4 w-4 mr-1.5" />{editUser ? "Simpan Perubahan" : "Tambah Pengguna"}</>}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

// ── Main Page ─────────────────────────────────────────────────────────────────
export default function KelurahanUsers() {
  const { token, user } = useAuth();
  const authHeader = { Authorization: `Bearer ${token}` };

  const [users,      setUsers]      = useState([]);
  const [rwList,     setRwList]     = useState([]);
  const [loading,    setLoading]    = useState(true);
  const [search,     setSearch]     = useState("");
  const [openForm,   setOpenForm]   = useState(false);
  const [editUser,   setEditUser]   = useState(null);

  // Map tenant_id → label (Kelurahan / RW nama)
  const [tenantMap,  setTenantMap]  = useState({});
  const kelTenantId = user?.tenant_id || "";

  const loadRwList = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/kelurahan/rw-list`, { headers: authHeader });
      if (res.ok) {
        const d = await res.json();
        // endpoint returns { rw_list: [...] }
        const list = Array.isArray(d) ? d : (d.rw_list || d.data || []);
        setRwList(list);
        const map = { [kelTenantId]: "Kelurahan" };
        list.forEach(rw => { map[rw.id] = rw.name || rw.nama || `RW ${rw.no_rw || ""}`.trim(); });
        setTenantMap(map);
      }
    } catch { /* ignore */ }
  };

  const loadUsers = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/users`, { headers: authHeader });
      if (res.ok) setUsers(await res.json());
      else toast.error("Gagal memuat data pengguna");
    } catch { toast.error("Gagal memuat data pengguna"); }
    setLoading(false);
  };

  useEffect(() => { loadRwList(); loadUsers(); }, [token]);

  const filtered = users.filter(u =>
    !search ||
    u.fullname?.toLowerCase().includes(search.toLowerCase()) ||
    u.username?.toLowerCase().includes(search.toLowerCase()) ||
    u.role?.toLowerCase().includes(search.toLowerCase())
  );

  const handleDelete = async (u) => {
    if (!window.confirm(`Hapus pengguna "${u.fullname}"?`)) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/users/${u.id}`, { method: "DELETE", headers: authHeader });
      if (!res.ok) { const d = await res.json().catch(() => ({})); toast.error(d.detail || "Gagal menghapus"); return; }
      toast.success("Pengguna dihapus");
      loadUsers();
    } catch { toast.error("Gagal menghapus"); }
  };

  const getWilayahLabel = (u) => {
    if (!u.tenant_id) return "-";
    return tenantMap[u.tenant_id] || "Kelurahan";
  };

  const isKelTenant = (tid) => tid === kelTenantId;

  return (
    <div className="p-6 space-y-5 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>Kelurahan</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Pengguna</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-xl flex items-center justify-center shadow">
            <Users className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Pengguna</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Kelola Pengurus RW dan staf Kelurahan</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={() => { loadRwList(); loadUsers(); }}
            className="flex items-center gap-1.5 px-3 py-2 text-sm bg-[var(--rw-bg-card)] dark:bg-gray-800 border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] transition-colors">
            <RefreshCw className="h-4 w-4" />
          </button>
          <Button onClick={() => { setEditUser(null); setOpenForm(true); }}
            className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white">
            + Tambah Pengguna
          </Button>
        </div>
      </div>

      {/* Info box */}
      <div className="flex items-start gap-3 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-700 rounded-xl px-4 py-3 text-xs text-emerald-700 dark:text-emerald-300">
        <Building2 className="h-4 w-4 flex-shrink-0 mt-0.5" />
        <div>
          <span className="font-semibold">Catatan:</span> Anda dapat menambahkan <strong>Pengurus RW</strong> (ditugaskan ke RW) dan <strong>staf Kelurahan</strong> seperti Bendahara, Sekretaris (ditugaskan ke Kelurahan).
          Role <em>Admin RT</em> dan <em>Lurah</em> tidak dapat dibuat di sini.
        </div>
      </div>

      {/* Search */}
      <Input placeholder="Cari nama, email, atau role..."
        value={search} onChange={e => setSearch(e.target.value)}
        className="max-w-sm dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700" />

      {/* Table */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
        {loading ? (
          <div className="flex items-center justify-center py-16">
            <div className="w-10 h-10 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin" />
          </div>
        ) : (
          <>
            <Table>
              <TableHeader>
                <TableRow className="dark:border-gray-700">
                  <TableHead>Nama</TableHead>
                  <TableHead>Email / Username</TableHead>
                  <TableHead>No. WhatsApp</TableHead>
                  <TableHead>Wilayah</TableHead>
                  <TableHead>Role</TableHead>
                  <TableHead className="text-center">Status</TableHead>
                  <TableHead className="text-right">Aksi</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={7} className="text-center text-gray-400 py-10">
                      Belum ada pengguna. Klik "+ Tambah Pengguna" untuk menambahkan.
                    </TableCell>
                  </TableRow>
                ) : filtered.map(u => (
                  <TableRow key={u.id} className="dark:border-gray-700 dark:hover:bg-gray-700/50">
                    <TableCell className="font-medium text-gray-900 dark:text-white">{u.fullname}</TableCell>
                    <TableCell className="text-gray-600 dark:text-gray-300 text-sm">{u.username}</TableCell>
                    <TableCell className="text-gray-600 dark:text-gray-300 text-sm">
                      {u.whatsapp ? `${u.country_code || "+62"} ${u.whatsapp}` : "-"}
                    </TableCell>
                    <TableCell>
                      <span className={`inline-flex items-center gap-1 text-xs font-semibold px-2 py-0.5 rounded-full ${
                        u.role === "pengurus_kelurahan"
                          ? "bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-300"
                          : isKelTenant(u.tenant_id)
                            ? "bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300"
                            : "bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300"
                      }`}>
                        {getWilayahLabel(u)}
                      </span>
                    </TableCell>
                    <TableCell className="text-sm text-gray-600 dark:text-gray-300">
                      {roleLabel(u.role)}
                    </TableCell>
                    <TableCell className="text-center">
                      {u.status === "active"
                        ? <CheckCircle2 className="w-5 h-5 text-green-500 mx-auto" />
                        : <XCircle className="w-5 h-5 text-red-400 mx-auto" />}
                    </TableCell>
                    <TableCell className="text-right">
                      {u.role === "pengurus_kelurahan" ? (
                        <span className="text-xs text-gray-400 dark:text-gray-500 italic">Hanya lihat</span>
                      ) : (
                        <div className="flex items-center justify-end gap-2">
                          <button onClick={() => { setEditUser(u); setOpenForm(true); }}
                            className="text-xs px-2.5 py-1.5 rounded-lg bg-blue-50 text-blue-700 border border-blue-200 hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-700 transition-colors font-medium">
                            Edit
                          </button>
                          <button onClick={() => handleDelete(u)}
                            className="text-xs px-2.5 py-1.5 rounded-lg bg-red-50 text-red-600 border border-red-200 hover:bg-red-100 dark:bg-red-900/20 dark:text-red-400 dark:border-red-700 transition-colors font-medium">
                            Hapus
                          </button>
                        </div>
                      )}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
            <div className="px-4 py-3 text-sm text-gray-500 dark:text-gray-400 border-t border-gray-100 dark:border-gray-700">
              {filtered.length} pengguna
            </div>
          </>
        )}
      </div>

      <UserModal
        open={openForm}
        onClose={() => { setOpenForm(false); setEditUser(null); }}
        editUser={editUser}
        rwList={rwList}
        kelTenantId={kelTenantId}
        authHeader={authHeader}
        onSaved={loadUsers}
      />
    </div>
  );
}
