import React, { useState } from 'react';
import { Layers, ChevronDown, ChevronRight } from 'lucide-react';

export const DESIL_LIST = Array.from({ length: 10 }, (_, i) => `Desil ${i + 1}`);

// Klasifikasi kelompok desil: D1-4 Rendah, D5-7 Menengah, D8-10 Tinggi
export const desilColor = (d) => {
  const n = parseInt(d.replace('Desil ', ''));
  if (n <= 4) return { bg: 'bg-red-100 dark:bg-red-900/30', text: 'text-red-700 dark:text-red-300', bar: 'bg-red-400' };
  if (n <= 7) return { bg: 'bg-amber-100 dark:bg-amber-900/30', text: 'text-amber-700 dark:text-amber-300', bar: 'bg-amber-400' };
  return { bg: 'bg-emerald-100 dark:bg-emerald-900/30', text: 'text-emerald-700 dark:text-emerald-300', bar: 'bg-emerald-400' };
};

export const DESIL_LEGEND = [
  { label: 'D1–4 Rendah', dot: 'bg-red-400' },
  { label: 'D5–7 Menengah', dot: 'bg-amber-400' },
  { label: 'D8–10 Tinggi', dot: 'bg-emerald-400' },
];

/**
 * Grid ringkasan 10 kolom desil + legend. Dipakai di semua level dashboard
 * (Kelurahan, RW, RT) — cukup diberi totals & total warga tercatat.
 */
export const StrataSummaryGrid = ({ totals = {}, total = 0 }) => (
  <div className="px-4 pt-4 pb-3">
    <div className="grid grid-cols-10 gap-1.5">
      {DESIL_LIST.map(d => {
        const val = totals[d] || 0;
        const pct = total > 0 ? Math.round((val / total) * 100) : 0;
        const barPct = total > 0 ? (val / total) * 100 : 0;
        const c = desilColor(d);
        return (
          <div key={d} className={`rounded-lg overflow-hidden border border-transparent ${c.bg}`}>
            <div className="h-1 w-full bg-black/5">
              <div className={`h-full ${c.bar} transition-all`} style={{ width: `${barPct}%` }} />
            </div>
            <div className="flex flex-col items-center px-1 py-2 gap-0.5">
              <span className={`text-[10px] font-bold leading-none ${c.text}`}>{d.replace('Desil ', 'D')}</span>
              <span className={`text-base font-extrabold leading-tight ${c.text}`}>{val}</span>
              <span className={`text-[10px] leading-none opacity-70 ${c.text}`}>{pct}%</span>
            </div>
          </div>
        );
      })}
    </div>
    <div className="flex gap-4 mt-2.5 text-[11px] text-gray-500 dark:text-gray-400 flex-wrap">
      {DESIL_LEGEND.map(l => (
        <span key={l.label} className="flex items-center gap-1">
          <span className={`w-2 h-2 rounded-sm inline-block ${l.dot}`} />
          {l.label}
        </span>
      ))}
      <span className="ml-auto font-medium text-gray-600 dark:text-gray-300">{total} warga tercatat</span>
    </div>
  </div>
);

const RtStrataRow = ({ rt }) => (
  <tr className="text-xs">
    <td className="pl-10 pr-2 py-1.5 text-gray-500 dark:text-gray-400" colSpan={1}>
      <span className="inline-flex items-center gap-1">
        <span className="w-1.5 h-1.5 rounded-full bg-gray-400 inline-block" />
        {rt.nama_rt}
      </span>
    </td>
    <td className="px-2 py-1.5 text-center font-medium text-gray-700 dark:text-gray-300">{rt.total}</td>
    {DESIL_LIST.map(d => {
      const val = rt.by_strata?.[d] || 0;
      const c = desilColor(d);
      return (
        <td key={d} className="px-1 py-1.5 text-center">
          {val > 0
            ? <span className={`inline-block px-1.5 py-0.5 rounded text-xs font-semibold ${c.bg} ${c.text}`}>{val}</span>
            : <span className="text-gray-300 dark:text-gray-600">-</span>
          }
        </td>
      );
    })}
  </tr>
);

const RwStrataRow = ({ rw }) => {
  const [open, setOpen] = useState(false);
  return (
    <>
      <tr
        className="cursor-pointer hover:bg-[#ece6d4] dark:hover:bg-gray-700/50 transition-colors"
        onClick={() => setOpen(o => !o)}
      >
        <td className="px-3 py-2 font-semibold text-gray-800 dark:text-gray-100 text-sm">
          <span className="inline-flex items-center gap-1.5">
            {open
              ? <ChevronDown className="w-3.5 h-3.5 text-gray-400" />
              : <ChevronRight className="w-3.5 h-3.5 text-gray-400" />
            }
            {rw.nama_rw}
          </span>
        </td>
        <td className="px-2 py-2 text-center font-bold text-gray-800 dark:text-gray-100 text-sm">{rw.total}</td>
        {DESIL_LIST.map(d => {
          const val = rw.by_strata?.[d] || 0;
          const c = desilColor(d);
          return (
            <td key={d} className="px-1 py-2 text-center text-sm">
              {val > 0
                ? <span className={`inline-block px-1.5 py-0.5 rounded font-semibold ${c.bg} ${c.text}`}>{val}</span>
                : <span className="text-gray-300 dark:text-gray-600">-</span>
              }
            </td>
          );
        })}
      </tr>
      {open && rw.by_rt?.map(rt => <RtStrataRow key={rt.rt_id} rt={rt} />)}
    </>
  );
};

const SimpleTenantRow = ({ row }) => (
  <tr className="text-xs">
    <td className="px-3 py-1.5 text-gray-600 dark:text-gray-300 font-medium">{row.nama_rt}</td>
    <td className="px-2 py-1.5 text-center font-semibold text-gray-700 dark:text-gray-300">{row.total}</td>
    {DESIL_LIST.map(d => {
      const val = row.by_strata?.[d] || 0;
      const c = desilColor(d);
      return (
        <td key={d} className="px-1 py-1.5 text-center">
          {val > 0
            ? <span className={`inline-block px-1.5 py-0.5 rounded text-xs font-semibold ${c.bg} ${c.text}`}>{val}</span>
            : <span className="text-gray-300 dark:text-gray-600">-</span>
          }
        </td>
      );
    })}
  </tr>
);

const BreakdownTable = ({ wilayahLabel, rows, mode, total, totals }) => (
  <div className="overflow-x-auto">
    <table className="w-full text-sm min-w-[700px]">
      <thead>
        <tr className="bg-[#e8e0cc] dark:bg-gray-700/60 text-xs text-gray-600 dark:text-gray-300">
          <th className="px-3 py-2 text-left font-semibold">{wilayahLabel}</th>
          <th className="px-2 py-2 text-center font-semibold">Total</th>
          {DESIL_LIST.map(d => (
            <th key={d} className="px-1 py-2 text-center font-semibold">{d.replace('Desil ', 'D')}</th>
          ))}
        </tr>
      </thead>
      <tbody className="divide-y divide-[#ddd6c4] dark:divide-gray-700">
        {mode === 'kelurahan' && rows.map(rw => <RwStrataRow key={rw.rw_id} rw={rw} />)}
        {mode === 'rw' && rows.map(rt => <SimpleTenantRow key={rt.rt_id} row={rt} />)}
        <tr className="bg-[#e8e0cc] dark:bg-gray-700/60 font-bold text-sm">
          <td className="px-3 py-2 text-gray-800 dark:text-gray-100">TOTAL</td>
          <td className="px-2 py-2 text-center text-gray-800 dark:text-gray-100">{total}</td>
          {DESIL_LIST.map(d => {
            const val = totals[d] || 0;
            const c = desilColor(d);
            return (
              <td key={d} className="px-1 py-2 text-center">
                {val > 0
                  ? <span className={`inline-block px-1.5 py-0.5 rounded font-bold ${c.bg} ${c.text}`}>{val}</span>
                  : <span className="text-gray-300 dark:text-gray-600">-</span>
                }
              </td>
            );
          })}
        </tr>
      </tbody>
    </table>
  </div>
);

/**
 * Section utuh (header + grid ringkasan + tabel breakdown wilayah).
 *
 * mode="kelurahan": strataData = { total_by_strata, grand_total, by_rw: [{ rw_id, nama_rw, total, by_strata, by_rt }] }
 * mode="rw":        strataData = { total_by_strata, grand_total, by_rt: [{ rt_id, nama_rt, total, by_strata }] }
 * mode="rt":        strataData = { total_by_strata, grand_total }  — tanpa tabel breakdown, hanya ringkasan tenant sendiri
 */
const StrataEkonomiSection = ({ strataData, mode = 'kelurahan', title = 'Distribusi Strata Ekonomi Warga' }) => {
  if (!strataData) return null;

  const total = strataData.grand_total || 0;
  const totals = strataData.total_by_strata || {};
  const rows = mode === 'kelurahan' ? strataData.by_rw : mode === 'rw' ? strataData.by_rt : null;

  if (mode !== 'rt' && !rows?.length) return null;
  if (mode === 'rt' && total === 0) return null;

  return (
    <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow">
      <div className="p-4 border-b border-[var(--rw-border)] dark:border-gray-700 flex items-center gap-2">
        <Layers className="h-5 w-5 text-indigo-500" />
        <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100">{title}</h3>
      </div>

      <StrataSummaryGrid totals={totals} total={total} />

      {mode !== 'rt' && (
        <BreakdownTable
          wilayahLabel="Wilayah"
          rows={rows}
          mode={mode}
          total={total}
          totals={totals}
        />
      )}
    </div>
  );
};

export default StrataEkonomiSection;
