import { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { API_BASE_URL } from '../../config/api';
import {
  Plus, RefreshCw, Pencil, Trash2, KeyRound,
  X, Check, AlertCircle, Eye, EyeOff, UserCog,
} from 'lucide-react';

const vToken = () => localStorage.getItem('vendor_token');
const vHdrs  = () => ({
  'Content-Type': 'application/json',
  Authorization: `Bearer ${vToken()}`,
});

const EMPTY_FORM = { name: '', phone: '', email: '', password: '', vendor_type: 'RT', status: 'active' };

function Badge({ status }) {
  const active = status === 'active';
  return (
    <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-semibold ${
      active ? 'bg-emerald-100 text-emerald-700' : 'bg-red-50 text-red-500'
    }`}>
      {active ? <Check size={10}/> : <X size={10}/>}
      {active ? 'Aktif' : 'Nonaktif'}
    </span>
  );
}

function Modal({ title, onClose, children }) {
  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/40 backdrop-blur-sm">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md mx-4 overflow-hidden">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100">
          <h2 className="font-bold text-gray-800 text-base">{title}</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
            <X size={18}/>
          </button>
        </div>
        <div className="px-6 py-5">{children}</div>
      </div>
    </div>,
    document.body
  );
}

function FormField({ label, children, hint }) {
  return (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>
      {children}
      {hint && <p className="mt-1 text-xs text-gray-400">{hint}</p>}
    </div>
  );
}

export default function VendorAccounts() {
  const [vendors, setVendors]     = useState([]);
  const [loading, setLoading]     = useState(false);
  const [toast, setToast]         = useState(null);
  const [search, setSearch]       = useState('');

  // Modal state
  const [modal, setModal]         = useState(null); // 'create' | 'edit' | 'reset' | 'delete'
  const [selected, setSelected]   = useState(null);
  const [form, setForm]           = useState(EMPTY_FORM);
  const [resetPwd, setResetPwd]   = useState('');
  const [showPwd, setShowPwd]     = useState(false);
  const [saving, setSaving]       = useState(false);

  const showToast = (msg, type = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const load = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/accounts`, { headers: vHdrs() });
      if (!res.ok) throw new Error(`Status ${res.status}`);
      setVendors(await res.json());
    } catch (e) {
      showToast('Gagal memuat data: ' + e.message, 'error');
    }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const openCreate = () => {
    setForm(EMPTY_FORM);
    setShowPwd(false);
    setModal('create');
  };

  const openEdit = (v) => {
    setSelected(v);
    setForm({ name: v.name, phone: v.phone || '', email: v.email || '',
              password: '', vendor_type: v.vendor_type, status: v.status });
    setShowPwd(false);
    setModal('edit');
  };

  const openReset = (v) => { setSelected(v); setResetPwd(''); setShowPwd(false); setModal('reset'); };
  const openDelete = (v) => { setSelected(v); setModal('delete'); };
  const closeModal = () => { setModal(null); setSelected(null); };

  const handleCreate = async () => {
    if (!form.name || !form.phone) return showToast('Nama dan nomor telepon wajib diisi', 'error');
    setSaving(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/accounts`, {
        method: 'POST', headers: vHdrs(),
        body: JSON.stringify(form),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal');
      setVendors(prev => [...prev, {
        id: data.id, name: data.name,
        phone: data.phone ?? form.phone,
        email: form.email,
        vendor_type: data.vendor_type ?? form.vendor_type,
        status: data.status ?? 'active',
        created_at: data.created_at ?? null,
      }]);
      showToast(`✓ Vendor "${data.name}" berhasil ditambahkan`);
      setSearch('');
      closeModal();
    } catch (e) { showToast(e.message, 'error'); }
    setSaving(false);
  };

  const handleEdit = async () => {
    if (!form.name) return showToast('Nama wajib diisi', 'error');
    setSaving(true);
    const payload = { ...form };
    if (!payload.password) delete payload.password;
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/accounts/${selected.id}`, {
        method: 'PATCH', headers: vHdrs(),
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal');
      showToast(`✓ Vendor "${data.name}" berhasil diperbarui`);
      closeModal();
      load();
    } catch (e) { showToast(e.message, 'error'); }
    setSaving(false);
  };

  const handleReset = async () => {
    if (!resetPwd) return showToast('Password baru wajib diisi', 'error');
    setSaving(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/accounts/${selected.id}/reset-password`, {
        method: 'POST', headers: vHdrs(),
        body: JSON.stringify({ password: resetPwd }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal');
      showToast(`✓ ${data.message}`);
      closeModal();
    } catch (e) { showToast(e.message, 'error'); }
    setSaving(false);
  };

  const handleDelete = async () => {
    setSaving(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/accounts/${selected.id}`, {
        method: 'DELETE', headers: vHdrs(),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal');
      showToast(`✓ ${data.message}`);
      closeModal();
      load();
    } catch (e) { showToast(e.message, 'error'); }
    setSaving(false);
  };

  const filtered = vendors.filter(v =>
    v.name.toLowerCase().includes(search.toLowerCase()) ||
    (v.phone || '').includes(search) ||
    (v.email || '').toLowerCase().includes(search.toLowerCase())
  );

  const inputCls = "w-full px-3 py-2 rounded-lg border border-gray-200 bg-gray-50 text-sm text-gray-900 focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/40 focus:border-[#ed6f5c]";
  const selectCls = inputCls + " cursor-pointer";

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
            <UserCog size={22} className="text-[#ed6f5c]"/> Akun Vendor
          </h1>
          <p className="text-sm text-gray-500">Kelola akun login untuk panel vendor.</p>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={load}
            className="flex items-center gap-2 px-3 py-2 border border-gray-200 rounded-xl text-sm hover:bg-gray-50">
            <RefreshCw size={14} className={loading ? 'animate-spin text-[#ed6f5c]' : ''}/>
            Refresh
          </button>
          <button onClick={openCreate}
            className="flex items-center gap-2 px-4 py-2 bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-xl text-sm font-semibold transition-colors">
            <Plus size={15}/> Tambah Vendor
          </button>
        </div>
      </div>

      {/* Info banner */}
      <div className="flex items-start gap-3 bg-blue-50 border border-blue-200 rounded-xl p-4 text-sm text-blue-700">
        <AlertCircle size={16} className="flex-shrink-0 mt-0.5"/>
        <span>Daftar akun yang dapat login ke panel vendor. Setiap vendor diidentifikasi dengan nomor telepon.</span>
      </div>

      {/* Search */}
      <input
        type="text"
        autoComplete="off"
        name="vendor-search"
        placeholder="Cari nama, nomor, atau email..."
        value={search}
        onChange={e => setSearch(e.target.value)}
        className="w-full max-w-sm px-4 py-2 rounded-xl border border-gray-200 bg-white text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/40 focus:border-[#ed6f5c]"
      />

      {/* Table */}
      {loading ? (
        <div className="flex justify-center py-16">
          <div className="w-10 h-10 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin"/>
        </div>
      ) : (
        <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm min-w-[600px]">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="px-5 py-3 text-left text-xs font-semibold text-gray-500 uppercase">Nama</th>
                  <th className="px-5 py-3 text-left text-xs font-semibold text-gray-500 uppercase">No. Telepon</th>
                  <th className="px-5 py-3 text-left text-xs font-semibold text-gray-500 uppercase">Email</th>
                  <th className="px-5 py-3 text-left text-xs font-semibold text-gray-500 uppercase">Tipe</th>
                  <th className="px-5 py-3 text-left text-xs font-semibold text-gray-500 uppercase">Status</th>
                  <th className="px-5 py-3 text-right text-xs font-semibold text-gray-500 uppercase">Aksi</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filtered.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="text-center py-12 text-gray-400 text-sm">
                      {search ? 'Tidak ada hasil yang cocok.' : 'Belum ada data vendor.'}
                    </td>
                  </tr>
                ) : filtered.map(v => (
                  <tr key={v.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-5 py-3.5">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-full bg-[#ed6f5c] flex items-center justify-center flex-shrink-0">
                          <span className="text-white text-xs font-bold">{v.name.charAt(0).toUpperCase()}</span>
                        </div>
                        <span className="font-medium text-gray-800">{v.name}</span>
                      </div>
                    </td>
                    <td className="px-5 py-3.5 text-gray-600">{v.phone || <span className="text-gray-300">—</span>}</td>
                    <td className="px-5 py-3.5 text-gray-600">{v.email || <span className="text-gray-300">—</span>}</td>
                    <td className="px-5 py-3.5">
                      <span className="px-2 py-0.5 bg-blue-50 text-blue-600 text-xs font-semibold rounded-full">
                        {v.vendor_type}
                      </span>
                    </td>
                    <td className="px-5 py-3.5"><Badge status={v.status}/></td>
                    <td className="px-5 py-3.5">
                      <div className="flex items-center justify-end gap-1">
                        <button onClick={() => openReset(v)} title="Reset Password"
                          className="p-1.5 rounded-lg text-gray-400 hover:bg-amber-50 hover:text-amber-500 transition-colors">
                          <KeyRound size={15}/>
                        </button>
                        <button onClick={() => openEdit(v)} title="Edit"
                          className="p-1.5 rounded-lg text-gray-400 hover:bg-blue-50 hover:text-blue-500 transition-colors">
                          <Pencil size={15}/>
                        </button>
                        <button onClick={() => openDelete(v)} title="Hapus"
                          className="p-1.5 rounded-lg text-gray-400 hover:bg-red-50 hover:text-red-500 transition-colors">
                          <Trash2 size={15}/>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="px-5 py-3 border-t border-gray-50 text-xs text-gray-400">
            {filtered.length} dari {vendors.length} vendor
          </div>
        </div>
      )}

      {/* ── CREATE MODAL ── */}
      {modal === 'create' && (
        <Modal title="Tambah Vendor Baru" onClose={closeModal}>
          <div className="space-y-4">
            <FormField label="Nama *">
              <input className={inputCls} placeholder="Nama vendor" value={form.name}
                onChange={e => setForm(f => ({ ...f, name: e.target.value }))}/>
            </FormField>
            <FormField label="Nomor Telepon *" hint="Digunakan untuk login, tanpa +62">
              <input className={inputCls} placeholder="081234567890" autoComplete="off" value={form.phone}
                onChange={e => setForm(f => ({ ...f, phone: e.target.value }))}/>
            </FormField>
            <FormField label="Email">
              <input className={inputCls} type="email" placeholder="email@contoh.com" value={form.email}
                onChange={e => setForm(f => ({ ...f, email: e.target.value }))}/>
            </FormField>
            <FormField label="Password *">
              <div className="relative">
                <input className={inputCls + ' pr-10'} type={showPwd ? 'text' : 'password'}
                  placeholder="Password awal" value={form.password}
                  onChange={e => setForm(f => ({ ...f, password: e.target.value }))}/>
                <button type="button" onClick={() => setShowPwd(!showPwd)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                  {showPwd ? <EyeOff size={15}/> : <Eye size={15}/>}
                </button>
              </div>
            </FormField>
            <div className="grid grid-cols-2 gap-3">
              <FormField label="Tipe">
                <select className={selectCls} value={form.vendor_type}
                  onChange={e => setForm(f => ({ ...f, vendor_type: e.target.value }))}>
                  <option value="RT">RT</option>
                  <option value="RW">RW</option>
                  <option value="Kelurahan">Kelurahan</option>
                  <option value="Vendor">Vendor</option>
                </select>
              </FormField>
              <FormField label="Status">
                <select className={selectCls} value={form.status}
                  onChange={e => setForm(f => ({ ...f, status: e.target.value }))}>
                  <option value="active">Aktif</option>
                  <option value="inactive">Nonaktif</option>
                </select>
              </FormField>
            </div>
          </div>
          <div className="flex gap-3 mt-6">
            <button onClick={closeModal}
              className="flex-1 py-2 rounded-lg border border-gray-200 text-sm text-gray-600 hover:bg-gray-50">
              Batal
            </button>
            <button onClick={handleCreate} disabled={saving}
              className="flex-1 py-2 rounded-lg bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm font-semibold disabled:opacity-50">
              {saving ? 'Menyimpan...' : 'Simpan'}
            </button>
          </div>
        </Modal>
      )}

      {/* ── EDIT MODAL ── */}
      {modal === 'edit' && selected && (
        <Modal title={`Edit Vendor — ${selected.name}`} onClose={closeModal}>
          <div className="space-y-4">
            <FormField label="Nama *">
              <input className={inputCls} value={form.name}
                onChange={e => setForm(f => ({ ...f, name: e.target.value }))}/>
            </FormField>
            <FormField label="Nomor Telepon" hint="Kosongkan jika tidak ingin mengubah">
              <input className={inputCls} value={form.phone}
                onChange={e => setForm(f => ({ ...f, phone: e.target.value }))}/>
            </FormField>
            <FormField label="Email">
              <input className={inputCls} type="email" value={form.email}
                onChange={e => setForm(f => ({ ...f, email: e.target.value }))}/>
            </FormField>
            <div className="grid grid-cols-2 gap-3">
              <FormField label="Tipe">
                <select className={selectCls} value={form.vendor_type}
                  onChange={e => setForm(f => ({ ...f, vendor_type: e.target.value }))}>
                  <option value="RT">RT</option>
                  <option value="RW">RW</option>
                  <option value="Kelurahan">Kelurahan</option>
                  <option value="Vendor">Vendor</option>
                </select>
              </FormField>
              <FormField label="Status">
                <select className={selectCls} value={form.status}
                  onChange={e => setForm(f => ({ ...f, status: e.target.value }))}>
                  <option value="active">Aktif</option>
                  <option value="inactive">Nonaktif</option>
                </select>
              </FormField>
            </div>
          </div>
          <div className="flex gap-3 mt-6">
            <button onClick={closeModal}
              className="flex-1 py-2 rounded-lg border border-gray-200 text-sm text-gray-600 hover:bg-gray-50">
              Batal
            </button>
            <button onClick={handleEdit} disabled={saving}
              className="flex-1 py-2 rounded-lg bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm font-semibold disabled:opacity-50">
              {saving ? 'Menyimpan...' : 'Perbarui'}
            </button>
          </div>
        </Modal>
      )}

      {/* ── RESET PASSWORD MODAL ── */}
      {modal === 'reset' && selected && (
        <Modal title={`Reset Password — ${selected.name}`} onClose={closeModal}>
          <FormField label="Password Baru *">
            <div className="relative">
              <input className={inputCls + ' pr-10'} type={showPwd ? 'text' : 'password'}
                placeholder="Masukkan password baru" value={resetPwd}
                onChange={e => setResetPwd(e.target.value)}/>
              <button type="button" onClick={() => setShowPwd(!showPwd)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                {showPwd ? <EyeOff size={15}/> : <Eye size={15}/>}
              </button>
            </div>
          </FormField>
          <div className="flex gap-3 mt-6">
            <button onClick={closeModal}
              className="flex-1 py-2 rounded-lg border border-gray-200 text-sm text-gray-600 hover:bg-gray-50">
              Batal
            </button>
            <button onClick={handleReset} disabled={saving}
              className="flex-1 py-2 rounded-lg bg-amber-500 hover:bg-amber-600 text-white text-sm font-semibold disabled:opacity-50">
              {saving ? 'Mereset...' : 'Reset Password'}
            </button>
          </div>
        </Modal>
      )}

      {/* ── DELETE MODAL ── */}
      {modal === 'delete' && selected && (
        <Modal title="Hapus Vendor" onClose={closeModal}>
          <div className="flex items-start gap-3 bg-red-50 border border-red-100 rounded-xl p-4 mb-4">
            <AlertCircle size={16} className="text-red-500 flex-shrink-0 mt-0.5"/>
            <div className="text-sm text-red-700">
              Anda yakin ingin menghapus vendor <strong>{selected.name}</strong>?
              Tindakan ini tidak dapat dibatalkan.
            </div>
          </div>
          <div className="flex gap-3">
            <button onClick={closeModal}
              className="flex-1 py-2 rounded-lg border border-gray-200 text-sm text-gray-600 hover:bg-gray-50">
              Batal
            </button>
            <button onClick={handleDelete} disabled={saving}
              className="flex-1 py-2 rounded-lg bg-red-500 hover:bg-red-600 text-white text-sm font-semibold disabled:opacity-50">
              {saving ? 'Menghapus...' : 'Hapus'}
            </button>
          </div>
        </Modal>
      )}

      {/* Toast */}
      {toast && (
        <div className={`fixed bottom-5 right-5 z-50 px-4 py-3 rounded-xl shadow-lg text-sm font-medium flex items-center gap-2 ${
          toast.type === 'error' ? 'bg-red-500 text-white' : 'bg-emerald-500 text-white'
        }`}>
          {toast.type === 'error' ? <X size={14}/> : <Check size={14}/>}
          {toast.msg}
        </div>
      )}
    </div>
  );
}
